INSERT INTO `book` (`book_id`, `title`, `author`, `isbn`, `publisher`, `published_date`, `price`, `category`, `image_url`, `description`, `stock`, `sales_count`, `created_date`, `last_modified_date`, `original_url`) VALUES (1,'希臘語課','韓江','9786264091961','漫遊者文化事業股份有限公司','2026-02-24',380,'文學','https://s.eslite.com/b2b/newItem/2026/01/30/8535_072808552_716_mainCoverImage1.jpg','<p>會員行銷說明│<br />黑卡/金卡會員凡購買<font color=\"#ff0000\">《希臘語課》</font>即回饋贈送會員消費點數活動。<br /><br />【注意事項如下】<br />1. 活動期間<font color=\"#ff0000\">2026/02/24~2026/04/12</font>於誠品實體門市、誠品線上凡購買<font color=\"#ff0000\">《希臘語課》單書或套書(紙本書、電子書)</font>即回饋贈送會員消費點數，黑卡/金卡會員200點(單書) 、250點(套書)。<br /><br />2. 消費時限累計黑卡/金卡會員消費才可列入計算。<br /> <br />3. 活動期間每人每卡不限回饋次數。 (活動期間贈消費點數，每人每卡購書不限次數可累贈；黑卡/金卡會員購買1本贈200點，購買2本贈400點、購買1套套書贈250點，購買2套套書贈500點，以此類推)<br /><br />4. 「黑卡/金卡會員購買《希臘語課》新書回饋贈點點活動」將於<font color=\"#0000ff\">2026/4/30</font>匯入符合回饋資格之會員帳戶內。<br />--------------------------------------------------------------------------------------------------------------------<br /></p><p>◎英國《衛報》2023年最期待的新作</p><p>◎入選《紐約客》、《時代》雜誌、《柯克斯書評》、《出版人週刊》、《圖書館雜誌》2023年度最佳書籍</p><p>◎入圍2024年華威大學女性翻譯文學獎決選</p><p><b><br /></b></p><p><b>諾貝爾文學獎得主&nbsp; 韓江</b></p><p><b>探索語言與人際連結救贖力量的深刻小說</b></p><p>一個慢慢失去視力的男人，遇上一個突然罹患失語症的女人。</p><p>他們在失去的光與靜默裡，找到了讓生命不再崩塌的縫隙。</p><p>◆</p><p><b>在光線消失之前，在聲音破碎之後，</b><b></b></p><p><b>他們選擇用思考、感受與凝視，抵抗消逝……</b><b></b></p><p><b></b></p><p><b>◎他的世界正在變暗，但他的內心卻因此對語言和聲音產生了新的「光芒」……</b><b></b></p><p><br /></p><p>一位教授古希臘語的講師，自幼輾轉韓國與德國之間，被兩種文化與語言撕扯，因為家族的遺傳性眼疾，醫生斷言他40歲後將逐漸失明。生活在逐漸變暗的世界裡，他的內心充滿了被文化和家庭割裂的孤獨感，以及自己即將失去獨立自主的恐懼。</p><p><b>◎</b><b>語言突然在她口中消失</b><b>，她決定在古老的希臘語中</b><b>找回與世界的連結</b><b>。</b></p><p>在短短數月內，她相繼失去了母親，又失去了九歲兒子的監護權。十七歲第一次罹患失語症後，某次她在課堂上受到一個普通的法文單字觸動，才重新找回語言能力。於是，這次她拒絕被世界抹去，決定透過學習已成死語的古希臘語，來對抗沉默，尋回語言。</p><p>這是他們的光芒與沉默相會於瞬間的故事。<b></b></p><p><b></b></p><p>◆</p><p>《希臘語課》是韓江探索感官的消逝、溝通的渴望，以及語言本質的作品。故事講述了兩個平凡人在各自痛苦的時刻相遇，卻發展出一段意想不到的情誼。就算失去語言與觀看的能力，兩人逐漸發現彼此間有種深切的連結，他們用聲音與觸覺交織出驚人的美感，如同從黑暗走向光明，從沉默走向呼吸與表達。這是一封描寫人與人之間親密與連結的溫柔情書，一部喚醒感官、鮮明描摹「活著」意味的小說。</p><p>◆</p><p><b>媒體評論</b></p><p>◎《希臘語課》是一封獻給語言的情書，也是對語言本身的批判。篇幅雖短，卻因其精煉與細膩，宛如一件琢磨完成的寶石……這是韓江最私密的作品之一。――《金融時報》</p><p>◎適合那些受吸引而去思考語言本身即為自我揭示之源的讀者……這本小說讚揚了在語言交流中，那份難以言表的默契與信任……韓江擅長描繪那些不循常規、拒絕屈從的女性。――《紐約時報》</p><p>◎在《希臘語課》中，韓江跨越一般感官的範圍，試圖翻譯那些不可言說之物……她讓「身心分離」這個反覆被書寫的主題，變得既新鮮又具重量。――《洛杉磯時報》</p><p>◎沉靜、稜角分明且具毀滅性……來自這位國際知名作家，對於語言、記憶與美的一次絕佳探索。――《柯克斯評論》</p><p>◎一場關於語言與殘疾的沉靜而美好的沉思……一個關於悲傷那無聲暴力、關於語言所能與不能跨越之鴻溝，以及關於溝通與連結之必要性的故事。—《Buzzfeed》</p><p>◎一封寫給語言、學習與連結之希望的情書。它關乎心靈與身體、我們的思想與感官—關乎生而為人活在世上的意義。――茱莉亞．菲利普斯（Julia Phillips），《消失的她們》（Disappearing Earth）作者</p><p>◎閱讀韓江的作品是一種無可比擬的享受。《希臘語課》既富詩意又極具哲學深度，是一個關於人際連結之脆弱與力量、美麗而令人難以忘懷的故事。――韓裔美籍小說家金秀妍（Angie Kim）</p><p>◎曲折幽微而崇高……針對語言、暴力、失落與親密感的一場非凡沉思。韓江是無可比擬的作家。她彷彿用短短幾行字便跨越整個人類經驗。――凱蒂．北村（Katie Kitamura）</p><p>◎韓江正是多數作家窮其一生努力成為的模樣：一位無畏而不煽情、直面人性真相的敘事者……韓江是天才。――麗莎．麥克倫尼（Lisa McInerney），《光榮的異端》（The Glorious\nHeresies）作者</p><p>◎令人屏息……她無疑是我最愛在閱讀中相伴、在思考中相隨、借其目光觀看世界的在世作家。――英國作家麥克斯．波特（Max Porter）</p><p>◎瀰漫著鮮活強烈的感官意象，強調著我們與世界的連結。――《明尼阿波利斯明星論壇報》</p><p>◎令人著迷……韓江是當今文壇最不落俗套、最具洞察力且真正具創新精神的作家之一。――《舊金山紀事報》</p><p>◎韓江鮮明、甚至時而暴烈的敘事筆法，足以喚醒再疲乏厭倦的讀者味蕾。――《獨立報》</p><p>一本省略、晦澀而耐人尋味的書……韓江的文風製造出迷霧般的神祕感。――《經濟學人》</p><p>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n韓江催眠般的《希臘語課》探問語言的邊界。――《海峽時報》</p>',10,0,'2026-03-17 18:06:04','2026-03-17 18:06:04','https://www.eslite.com/product/10012122452683089454001'),(2,'其中一句是謊言 (附作者手寫問候印簽扉頁)','金愛爛','9786267748244','新經典圖文傳播有限公司','2026-01-28',380,'文學','https://s.eslite.com/b2b/vendor/vendor176880848325320260119154124/mainCoverImage1_1589459.jpg','<table>\n <tbody><tr>\n  <td>\n  <p><b></b></p>\n  <p><b>「請用五句話介紹自己，不過，其中一句必須是謊言。」</b><b></b></p>\n  <p><b></b></p>\n  <p><b>★★★</b><b> </b><b>韓國當代文壇的代名詞‧蟬聯年度小說</b><b>No.1 </b><b>★★★</b><b></b></p>\n  <p><b>金愛爛</b><b></b></p>\n  <p><b>對現代社會最鮮明透徹的書寫</b><b></b></p>\n  <p><b>刻劃靈魂中微小卻至關重要的事物</b><b></b></p>\n  <p><b></b></p>\n  <p><br /></p>\n  <p><b>★</b><b> </b><b>諾貝爾文學獎</b><b> </b><b>韓江</b><b> </b><b>必讀推薦：</b><b>「只要提到金愛爛，我就會去讀。」</b><b></b></p>\n  <p><b>★</b><b> </b><b>金宥立（小說</b><b>/</b><b>詩</b><b> </b><b>製作人）：「三名高中生透過謊言而逐漸熟絡，在這個過程中，他們各自失去了珍貴的東西，卻不受自身的痛苦束縛，勇敢擁抱彼此的傷痛。一部感人至深的成長故事。」</b><b></b></p>\n  <p><b>★</b><b> </b><b>吳曉樂：「金愛爛擁有一種讓人嫉妒的書寫天賦，那就是讓讀者深信『天啊，她寫的是我』。」</b><b></b></p>\n  <p><b>★</b><b> </b><b>教保文庫作家評選年度小說之冠</b><b></b></p>\n  <p><b>★</b><b> Yes24</b><b>韓國最大網路書店年度選書</b><b></b></p>\n  <p><b>★</b><b> Aladin</b><b>書店年度選書</b><b></b></p>\n  <p><b>★</b><b> </b><b>光州</b><b>/</b><b>全南閱讀票選年度最佳圖書</b><b></b></p>\n  <p><b>★</b><b> </b><b>擊敗東野圭吾，上市即登上排行榜</b><b>No.1</b></p>\n  <p><b>★</b><b> </b><b>蟬聯銷售第一，長踞韓國書店暢銷榜</b><b></b></p>\n  <p><b>★</b><b> </b><b>吳曉樂（作家）、張慧慈（作家）、蔡宜芳（諮商心理師）、劉梓潔（作家）、韓麗珠（作家）　感動推薦</b><b></b></p>\n  <p><b>★</b><b> </b><b>特別收錄：作者手寫問候</b><b> </b><b>印簽扉頁</b><b></b></p>\n  <p><b></b></p>\n  <p><b></b></p>\n  <p>「請用五句話介紹自己，不過，其中一句必須是謊言。」導師親切地說。<span></span></p>\n  <p><br /></p>\n  <p>「我喜歡畫畫。」素莉開始回答。</p>\n  <p>「我小時候踩過釘子，弄傷了腳。」</p>\n  <p>「有時候，我早上會害怕睜開眼睛。」</p>\n  <p>「我曾經因為沒有抓住某人的手，失去了那個人……」</p>\n  <p><br /></p>\n  <p>當真與假的界線逐漸朦朧，</p>\n  <p>三名各自懷抱著祕密的少年少女，遇見了彼此：</p>\n  <p><b></b></p>\n  <p>少年志宇在母親驟逝後離家，為了能和寵物蜥蜴「龍植」一起生活，一邊到工地打工一邊偷偷畫漫畫上傳論壇，「創作」成了他在現實縫隙中勉強活下去的出口；</p>\n  <p>女孩素莉同樣失去母親，不同於別人的是，她的雙手擁有能夠感應死亡的能力，卻也沒能預見母親的離世；自那之後，她便緊握畫筆，不再與人碰觸；</p>\n  <p>少年宰雲的母親入獄、父親昏迷在醫院裡，心愛的黃金獵犬「團團」也接著離世，他在罪疚中痛苦掙扎，害怕那天晚上「真正的祕密」有一天會被揭開……</p>\n  <p><br /></p>\n  <p>他們背負著傷痛，在謊言與祕密之中沉浮。渴望真相，卻也畏懼真相所帶來的重量。</p>\n  <p>在面對羈絆、歉疚與活下去的茫然時，他們將做出怎樣的抉擇？</p>\n  <p><br /></p>\n  <p><br /></p>\n  <p><b>◆</b><b> </b><b>文壇偶像</b><b>X</b><b>各大文學獎肯定</b><b>X</b><b>諾貝爾呼聲，對韓國社會最精準的書寫者──金愛爛</b><b></b></p>\n  <p><br /></p>\n  <p>「大多數的成年人，一生中都會背負著類似的祕密與問題，即便不是什麼嚴重的錯誤，也難以啟齒。可我認為，傷痛並非是因為運氣糟，反而是人生的基本狀態，所有人都無法避免的根本價值。我們總是與失去相伴，會失去人際關係、失去財富，甚至那些看似擁有一切的人也會失去青春。我創作的故事並非出於某種特定的偏好，而是從人生的基本狀態和根本價值出發。我希望，這本書能讓每一個少年少女，都能在祕密與禁忌之中，安全地冒險。」──作者 金愛爛</p>\n  <p><br /></p>\n  <p>韓國當代最具代表性的小說家，金愛爛，22歲（2002年）初試啼聲，以描寫五個女子宿舍生活的短篇小說〈不敲門的家〉拿下文學大獎；2005年，出版短篇小說集《奔跑吧！爸爸》，成為韓國日報文學獎最年輕的獲獎者，被媒體稱為「韓國文壇最大的收穫之一」，並在書市創造史無前例的暢銷風潮，形成「金愛爛現象」；2013年，再以〈沉默的未來〉拿下國際知名的韓國李箱文學獎，再次寫下最年輕得主的紀錄。</p>\n  <p><br /></p>\n  <p>金愛爛以其獨特的敘事結構得名，讀者能在閱讀時體驗到每個角色的掙扎，隨著真相逐步揭開，也將讀者帶入深深的情緒之中。這種書寫特別觸動年輕人，讓她被評為是「最關心年輕人生活的作家」、「現代社會生態觀察員」。而身為一名小說家，金愛爛對於「作者該說什麼，以及要如何說」深入思考，在作品中展示小說結構與理解角色之間的關聯，正如同「畫筆必須沾取極少量的白色顏料，才能在人們眼中留下光芒」──表達靈魂微小卻至關重要的東西，也成為了金愛爛每個故事裡的訴求，她以細膩精準的文字，描繪出每個角色的靈魂，完成這個關於人在祕密、謊言與悲傷之中，仍然選擇彼此靠近的故事——真相並非總是光明美好，卻值得我們反覆閱讀回味。</p><p><br /></p><p><iframe data-testid=\"embed-iframe\" style=\"border-radius:12px\" src=\"https://open.spotify.com/embed/episode/5d2c7w2bu83jx9k4KApwFc?utm_source=generator\" width=\"100%\" height=\"152\" frameborder=\"0\" allowfullscreen=\"\" allow=\"autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture\" loading=\"lazy\"></iframe></p>\n  <p><b></b></p>\n  </td>\n </tr>\n</tbody></table><p><b>【迷誠品編輯推薦】<br /><br />標題｜向AI傾訴煩惱是好是壞？作家吳曉樂談韓國小說《其中一句是謊言》｜迷誠品Podcast<br />撰文｜迷誠品內容中心<br /></b><br />大部分時候我們將謊言視為負面、傷害他人，但在某些情況下，謊言將成為他人活下去的支撐，這就是謊言的複雜性，也是人類的複雜性。<br /> <br />韓國文學《其中一句是謊言》故事聚焦在三名少年少女，看他們如何面對生命與謊言的難題，「其中一句是謊言」來自老師在課堂上的遊戲，他們會用五句話介紹自己，但其中一句是謊言。<br /> <br />本集邀請作家吳曉樂與我們對談，透過收聽迷誠品 Podcast 或是閱讀此篇文章，我們將聊到本書作者金愛爛的書寫特色、青少年對AI傾訴心事是否樂觀看待、對被迫長大的青少年有什麼觀察，最後聽吳曉樂用五句話介紹自己。<br /><br /><a href=\"https://meet.eslite.com/tw/tc/videos/202603050001?utm_source=eslite_com&amp;utm_medium=link&amp;utm_campaign=2026_lie\" target=\"_blank\">☞點此進入迷誠品閱讀文章</a></p>',10,0,'2026-03-17 18:06:08','2026-03-17 18:06:08','https://www.eslite.com/product/10012017642683080532005'),(3,'這僅有一次的人生, 一定要讀蘇東坡: 不管你遇到了什麼, 一句蘇東坡就能療癒。','費勇','9786267192870','大是文化有限公司','2023-01-30',420,'文學','https://s.eslite.com/upload/product/o/2682321418009/20221229034848857728.jpg','<div>◎工作輾轉各處，無法安定？一生漂泊的蘇東坡，「應似飛鴻踏雪泥」。\n<br /> ◎人生的不公不義，是無法迴避的。「人生有味是清歡」，是蘇東坡的淡然。\n<br /> ◎如何活在當下？「詩酒趁年華」，被貶官三次的蘇東坡選擇這樣過人生。\n<br />     \n<br />北宋文豪蘇軾，21歲跟著父親蘇洵進京趕考，22歲就中進士。\n<br />一篇文章受到當時宰相歐陽修的賞識，年紀輕輕即進入權力核心。\n<br />   \n<br />26歲時，朝廷任命他為大理評事，開始了第一份工作，\n<br />之後在他66年的歲月裡，他至少在十餘個地方生活過。\n<br />長年的離家奔波，讓他有感而發寫下：「人生到處知何似？應似飛鴻踏雪泥。」\n<br />（人世間的遇合，是偶然而無常的，留下的痕跡都會消失，不用在意。）\n<br />\n<br />44歲，他遇上人生重要轉折「烏臺詩案」，\n<br />被人舉報他的詩譏諷朝廷，謗議新政，對皇上不敬，他因此入獄。\n<br /> 半年後被貶黃州，他卻灑脫寫下：「竹杖芒鞋輕勝馬，誰怕？一蓑煙雨任平生。」\n<br />（就算一輩子都在風雨裡，我也很坦然。）\n<br />\n<br />本書作者費勇是著名文化學者，他說蘇東坡的一生大起大落（三度被貶官），\n<br />但在他閃閃發光的每一刻，也有「也無風雨也無晴」的平靜，\n<br />他的一生都在「自我治癒」。不管現在的你遇到了什麼，一句蘇東坡就能療癒。\n<br />\n<br /> ◎一路得意，忘了求退之難？\n<br />大家都想升官發財，不喜歡降職清貧。\n<br /> 蘇東坡卻說：「賀下不賀上」。為什麼？\n<br />（做官的人降職或退隱值得慶賀，升遷反而不值得慶賀）\n<br />     \n<br />他雖然也曾感嘆：「何時忘卻營營？」（何時能夠忘掉現實裡那些鑽營忙碌啊？）\n<br />但就算不斷被小人陷害，他始終沒有選擇辭官，\n<br />他說：「何必擇所安，滔滔天下是。」\n<br />  （不管你逃到山裡隱居或出家，仍會面臨生計與人際交往，不如達觀面對。）\n<br />\n<br />◎晴朗是生活，風雨也是生活，活在當下\n<br />從烏臺詩案中死裡逃生的他，剛到黃州，就寫下兩句詩：\n<br />「長江繞郭知魚美，好竹連山覺筍香。」\n<br />（長江三面圍繞黃州，想到有鮮美的魚吃；看到漫山茂密的竹林，猶如聞到筍香。）\n<br />\n<br /> 後來又被貶到惠州，他說待在嶺南也不錯：\n<br /> 「日啖荔枝三百顆，不辭長作嶺南人。」\n<br />  （如果能每天吃三百顆荔枝，我願意永遠都做嶺南的人。）\n<br />      \n<br />  他用行動證明：把心放寬，看開看淡，波折的人生照樣過得有模有樣。\n<br />\n<br />◎豁達不是冷漠，而是一種深情\n<br /> 蘇東坡給人的印象，不外乎樂觀、豁達、幽默，有政治抱負，\n<br />  但其實他還很深情。曾寫下一首著名的〈江城子〉懷念妻子：\n<br />「十年生死兩茫茫。不思量，自難忘。」\n<br />（生死永隔，相互思念卻無法相見，即使不去想，那些美好的記憶仍難以忘懷。）\n<br />  提醒著我們要珍惜相伴身邊的那個人。\n<br />      \n<br />漂泊、衝突、煩惱、挫折……人人都會有，怎麼面對？\n<br />蘇東坡用三件事療癒了自己：\n<br />一張琴（業餘愛好），「散我不平氣，洗我不和心」（在琴聲裡，心變得平和）；    \n<br />一壺酒（美食），「吾醉後乘興作數十字……」（喝醉時，能寫出不同於平常的字）；\n<br />還有一個是……\n<br />                  \n<br />   人生有許多痛苦與挫折，只能靠自己療癒自己。\n<br />   還好，即使我們孤單一人，一句蘇東坡就能療癒。</div><p><br /></p><p><b>【迷誠品編輯推薦】<br /><br />標題｜《這僅有一次的人生，一定要讀蘇東坡》教我用豁達的態度治癒自己<br />撰文｜費勇</b><br /><br />蘇東坡作為古代名家，同為唐宋八大家，每個人在求學階段都有讀過他的作品，也知曉他堪稱坎坷的貶謫經歷。</p><p><a href=\"https://meet.eslite.com/tw/tc/article/202409060004?utm_source=eslite_com&amp;utm_medium=link&amp;utm_campaign=2024_su_dongpo\" target=\"_blank\">☞點此進入迷誠品閱讀文章</a><br /></p>',10,0,'2026-03-17 18:06:12','2026-03-17 18:06:12','https://www.eslite.com/product/1001191562682321418009'),(4,'在小山和小山之間: 故事大爆炸年度首獎之作','李停','9786267721834','悅知文化','2026-01-26',360,'文學','https://s.eslite.com/b2b/newItem/2026/01/12/8622_103339730_632_mainCoverImage1.jpg','<html><head></head><body><p style=\"text-align:center;\"><b>母親能給的愛，就是一次又一次</b><b></b></p><p style=\"text-align:center;\"><b>得體地退出我的生命。</b><b></b></p><p><b></b></p><p style=\"text-align:center;\"><b>◆</b></p><p style=\"text-align:center;\"><b>上市5</b><b>天即再刷，萬人流淚！</b></p><p style=\"text-align:center;\"><b>◆</b></p><p style=\"text-align:center;\"><b>★故事大爆炸2023</b><b>年度首獎★</b></p><p style=\"text-align:center;\"><b>★豆瓣當年年度圖書小說類TOP\n3</b><b>★</b></p><p style=\"text-align:center;\"><b>★已售出法國、俄羅斯、越南、印尼等海外版權★</b></p><p style=\"text-align:center;\"><b>★累計銷售突破60,000</b><b>冊★</b></p><p style=\"text-align:center;\"><b>◆</b></p><p style=\"text-align:center;\"><b>【特別收錄】給臺灣讀者的話</b></p><p style=\"text-align:center;\"><b>【燙金書衣】緋紅燙金工藝，高雅地呈現出山脈稜線</b></p><p style=\"text-align:center;\"><b>【裝幀設計】以8</b><b>幅全彩插畫，刻畫動人的母女情</b></p><p style=\"text-align:center;\"><b><br></b></p><p><b></b></p><p><b></b></p><p>「我的女兒，她要過跟我相反的生活。」<b></b></p><p>「媽媽還繼續著多年以來的習慣，對我的一切都不滿意。」</p><p><br></p><p><b></b></p><p><b>／從孕育生命那一刻起，</b><b></b></p><p><b>我們之間就長出了永恆的誤解與羈絆。／</b><b></b></p><p><b><br></b></p><p><b></b></p><p>媽媽獨自來到異國，與定居於此的待產女兒重啟久違的同居生活，在狹小的公寓裡，兩人因語言、文化、價值觀等差異而摩擦不斷，也在相處的過程毫不留情地揭開彼此生命中的傷口。母親為女兒隱忍一生的羞辱與心碎；女兒想逃離母親的愛，卻不得不面對童年陰影與婚姻危機……</p><p><br></p><p>人心裡隱祕、柔軟卻堅韌的東西被層層剖出，兩人也在生活的對峙中，無聲和解。本書巧妙地在母女視角之間輪流切換，以極具電影感的細節，描述女性成長過程的焦慮與自卑，以及親緣裡節制卻濃郁的情感。</p><p><br></p><p><b>她們橫隔著母女之間的山、時代之間的山、文化之間的山，</b></p><p><b>在不可避免的交鋒、爭吵、埋怨之中，</b><b></b></p><p><b>母親和女兒究竟要走過多久，才能真正理解對方？</b><b></b></p><p><br></p><p>「血脈相連的親近的人，卻在同一空間分享著不同的記憶。這種隔閡、誤解，該談的閉口不談，能談的只是日常皮毛事，用真心去猜真心、用真心去碰撞真心，甚至碰撞到傷痕累累……真心和真心之間的距離，有時很遠有時很近，但好在真心不會變，真心永遠是真心，即便有痛苦，但仍然是我心裡美好的事。</p><p>──作者 李停</p><p><br></p><p><b>【本書特色】</b><b></b></p><p><b>◆ </b>描繪最難解的矛盾與純粹的愛，她們時而是女兒，時而是母親，時而是自己。</p><p><b>◆ </b>從每個人都能切身體會的情感出發，精準捕捉現代東亞家庭的縮影。</p><p><br></p><p><b></b></p><p><b>【佳評如潮】</b><b></b></p><p>李欣倫（作家／中央大學中國文學系副教授）</p><p>宋文郁（寫作者）</p><p>張嘉真（作家）</p><p>毛尖（作家、影評人）</p><p>鄭執（作家、編劇）</p><p><b>──潸然推薦</b><b></b></p><p><b><br></b></p><p><b></b></p><p><b>◆ </b><b>李欣倫（作家／中央大學中國文學系副教授）──</b><b></b></p><p>本書說出了當代眾女性的心聲，文化差異、性別角力、代間差距等議題，全都在這本小說中精彩演繹。</p><p><br></p><p><b></b></p><p><b>◆ </b><b>宋文郁（寫作者）──</b><b></b></p><p>山與山之間的距離究竟有多遠？母與女之間，也如山一般──那些愛恨鑿出的溝渠，原本幾乎無法跨越。直到有一天，你也終於成為了山；在逐漸成為的過程中，才有了靠近的可能。</p><p>李停以母女視角雙線敘事，描繪兩代女性在婚姻、生育、國族等壓迫下的艱難處境，也帶我們看見：原來讓山成為山的，從來不只是矗立在兩座山之間的愛與恨，而是即使動彈不得，仍想再向彼此靠近一步的心。</p><p><br></p><p><b></b></p><p><b>◆ </b><b>張嘉真（作家）──</b><b></b></p><p>女兒對媽媽不經意流露的粗暴，像是不小心闖入陌生人家裡的客廳才能看見的那樣。母女問題是一個敞開的客廳。妳小心翼翼用珠簾擋著，卻一點也遮不住。妳怕別人說妳不懂歷史、不懂換位思考、不懂得去愛，妳更怕妳懂了的那一天起，妳想起妳曾經以為「可是我沒有想要」是聰明的回應。沒有人想要命運，可是命運它會一直來。這是一本關於命運的解答之書。</p><p><br></p><p><b>◆ </b><b>毛尖（作家、影評人）──</b><b></b></p><p>此書巧妙地用雙視點寫出了母女兩代的生育歷程和身心轉折。女兒視角的描述尤其動人，有日出而作的文化斡旋，有日落而息的兩性交戰，更有於無聲處聽了驚雷又見南山的平常人生。</p><p><br></p><p><b>◆ </b><b>鄭執（作家、編劇）──</b><b></b></p><p>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n身為男性，母女情始終是我難讀懂的世間情。然而，這篇小說讓我相信自己讀懂了。李停以沉著的敘事，巧妙的佈局，搬動了兩座山走向彼此。動人的相擁，並不需要真的張開懷抱。</p></body></html>',10,0,'2026-03-17 18:06:17','2026-03-17 18:06:17','https://www.eslite.com/product/10012122082683075462003'),(5,'矛盾','梁貴子','9786264091886','漫遊者文化事業股份有限公司','2026-01-05',420,'文學','https://s.eslite.com/b2b/vendor/vendor176640371115020251222194151/mainCoverImage1_1576455.jpg','<p>人生不論你組裝得再完美，<br />一旦拆開後，就只剩下矛盾。<br />願我們都在矛盾裡誠實地活。</p><p><br /></p><p><span style=\"font-size:0.875rem; display:inline !important;\">—台灣版典藏禮物書特殊裝幀</span></p><p>—擊凸加工針線效果傳達人的溫度</p><p><br /><br />✦ 世紀末年度暢銷小說，2020年揭開「無宣傳」逆襲的奇蹟篇章<br />✦ 長踞「教保文庫」韓國小說TOP 1，2025年度之書TOP2<br />✦ 銷售170萬+ 冊，掀起社群媒體金句分享熱潮<br /><br />◆<br /><br />「矛盾」是人生的真相。<br />所有的拉扯，不是系統錯亂，是你認真活著的證據。<br /><br />我是安真真，25歲，未婚，身材不高不矮，相貌雖然不是不堪入目，但也沒到令人驚艷的地步。<br />我自認讀了不少書，腦袋裡還是裝了一些東西，然後⋯⋯<br />就沒有然後了。<br />我的人生毫無深度，連一粒芝麻也容不下——<br />這樣活著，真的沒有問題嗎？<br />◆<br />每一個矛盾都對應一個選擇，<br />但生活從來都不是關於答案。<br />人生總會有這麼一天，覺得不能再這樣活下去。當那天突然到來，我開始回顧自己不算長的人生。<br />我的母親有個雙胞胎妹妹。她們在四月一日愚人節出生，也在四月一日同一天結婚，從此走上不同的人生之路。母親嫁給無拘無束、熱愛自由的男人，婚後才發現這男人是個酒鬼，還經常搞消失，如今已經下落不明五年。媽媽靠著在市場賣襪子、內衣過活，養大我和弟弟。<br />相反的，阿姨嫁給了菸酒不沾的建築師，一個無聊又完全可以預測的人。他每天準時下班回家，而且陪阿姨過所有的節日。阿姨是個很浪漫的人，喜歡使用「珍藏」和「永遠」這種詞彙，而母親最常掛在嘴邊的是「利益」和「計算」。<br />看著母親和阿姨天差地別的生活，我也不知不覺面臨了必須在兩個男人之間做出選擇的難題：羅英奎是計畫狂，人生的一切都在他的計畫中，包括我的反應、我們的回憶。相反的，金章宇嚮往自由，從來不做計畫，永遠跟著感覺走——他和我父親就像照鏡子一樣相像，可明明知道下場，我的心卻還是往金章宇傾斜……<br /><br />幸 vs. 不幸、愛vs.不愛……矛盾是世間萬物的真理；<br />理性 vs. 感性、自由 vs. 責任……沒有一條道路能保證任何事。<br /><br />矛和盾，是所有事物的兩面，永遠無法對齊。<br />我們不必與自己和解，只要誠實面對——至少活得像我們自己。<br /><br /><br />■韓國網友好評：<br />1. 聽朋友說這是她的「人生之書」，果真沒錯！<br />2. 閱讀時能感覺到作家對每一句話都下過功夫，讓人有被細心對待的感覺。<br />3.《矛盾》對我來說有太多值得銘記的句子，也讓我想更深入地討論書中的每一個角色。<br />4. 對於正在思考自己是什麼樣的人、想要什麼的人來說，這是能帶來極大慰藉與深刻洞見的作品。<br />5. 讀的時候，我一邊貼滿便利貼，一邊和書對話。中途甚至忍不住在心裡感嘆：「這根本是梁貴子老師的名言集！」一邊讀、一邊在內心鼓掌、一邊掉淚，也不斷得到安慰和省思。我甚至會想：明年再讀會不會有不同感受？如果在三十歲、四十歲時再重讀，又會不會有新的體會？<br />6. 雖然很想把《矛盾》推薦給二十多歲的女兒，但我知道她現在還聽不進去，只能期待有一天，她會自己找來讀。很慶幸自己即使到了五十歲，仍能遇見這本書，並學會更坦然地面對接下來的人生。<br />7. 因為看到它長期穩坐暢銷榜第一名，就決定再重讀一次，上次看已經是二十多年前了。<br />第一次讀的時候我才二十多歲，完全能代入安真真；如今再讀，反而能從她母親的視角去理解整個故事。即使時代變了，這本書依然能留在暢銷榜上，靠的就是文字本身的力量。<br /><br />■韓國網友感動共鳴：<br />－明知道這是虛構的小說，我卻仍完全沉浸其中，可能是因為人物都描寫得太生動，像是現實中曾經遇見過的人。<br />－「人生充滿矛盾」這句話我早就聽過無數次。剛開始讀時還納悶：「到底哪裡矛盾？」直到讀到最後才恍然大悟——啊，原來如此。<br />－人生沒有標準答案。即使看起來是正確的選擇，也可能在某些時候被說成是錯的；而這，正是人生的樣貌。所以，書名才叫《矛盾》。<br />－就像小說最後一句所說的：「人生不是一邊探究一邊活著，而是一邊活一邊探究。」只要努力活著，這一切終將成為屬於我的人生。<br />－正確答案既可能是對的，也可能是錯的；或許正因如此，這本書才能被讀者喜愛了這麼多年。也讓我忍不住想問：當25歲的真真到了母親的年紀時，她又會怎麼想呢？<br />－我會去想像，真真做出選擇之後，她的人生會走向哪個方向；也會去思考她的勇氣，還有我自己是否也能像她一樣，做出那樣的決定？<br />－我只能希望，真真此刻在一個更好的地方，能漂亮地、勇敢地與不幸搏鬥，不再孤單，依然閃閃發光。</p><p><br /></p><p><b>【迷誠品編輯推薦】<br /><br />標題｜韓國無宣傳暢銷小說《矛盾》，反覆叩問人生的不同選擇｜迷誠品Podcast<br />撰文｜迷誠品內容中心</b><br /><br />感性與理性、自由與責任，從來沒有完美的選擇，也沒有一個選擇能保證任何事，人生不論你組裝得再完美，一旦拆開後，就只剩下矛盾。<br /> <br />《矛盾》是韓國作家梁貴子的著作，2020年在韓國創下「無宣傳」的銷售奇蹟，故事主角安真真面臨兩個性格截然不同的男人（計畫狂 vs. 嚮往自由者）的選擇，並從母親與阿姨天差地別的人生中尋找答案；書中有許多流傳的金句，使讀者奉為「人生之書」。<br /> <br />本集邀請漫遊者文化行銷統籌駱漢琦和我們分享本書，透過收聽迷誠品 Podcast 或是閱讀此篇文章，我們將分享《矛盾》主角安真真面臨的抉擇、《矛盾》這本書的吸引人之處，為何説在矛盾中活著的人，才是真正面對人生的人。<br /> <br /><a href=\"https://meet.eslite.com/tw/tc/videos/202601220001?utm_source=eslite_com&amp;utm_medium=link&amp;utm_campaign=2026_contradiction\" target=\"_blank\">☞點此進入迷誠品閱讀文章</a></p><p><br /></p><p>EP522｜《矛盾》：在矛盾中活著的人，才是真正面對人生的人｜今天讀什麼</p><p><iframe data-testid=\"embed-iframe\" style=\"border-radius:12px\" src=\"https://open.spotify.com/embed/episode/7K9YhxRukNV6AJCujYNxB6?utm_source=generator\" width=\"100%\" height=\"152\" frameborder=\"0\" allowfullscreen=\"\" allow=\"autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture\" loading=\"lazy\"></iframe></p>',10,0,'2026-03-17 18:06:21','2026-03-17 18:06:21','https://www.eslite.com/product/10012122452683065209007'),(6,'海邊的房間','黃麗群','9786263965126','時報文化出版企業股份有限公司','2024-07-30',420,'文學','https://s.eslite.com/b2b/newItem/2024/07/19/137_101839046_769_mainCoverImage1.jpg','<p>幽冷剔透，刁鑽如刀<br />黃麗群短篇小說集  一輪復刻版<br /><br />「麗群正是這樣的，資質穠豔幽美，可是那美裡面暗暗滲著涼氣。她的文字溫煦如日，速如風雨。晴日靜好的午後，還覺得太平歲月溫暖快樂，一轉眼，不知哪來的烏雲罩頂，大雨傾盆而下。讀的人回過神來，重新整飭，自然有自己的一番了悟。那時，這朵謎一樣惘然幽異的奇花異草，就在讀者的心裡盛開蔓延了。」   ──柯裕棻<br /><br />「在一逕清爽又溫良的人情之常中，作者一句句都踩出了我們心底卑微的呻吟。人生本就苦多於樂，我們始終都在陰暗的世界裡行走，偶然看見一朵希望如花，就蠢蠢欲動伸手。<br />麗群的小說讓我們聽見另一種『為甚麼不』的疑問，為甚麼純情不可以難以下嚥？為甚麼絕望不可以無聊瑣碎？她的小說透露出的不急不徐，不標新立異，不大驚小怪，反成就了一種獨特主題。美好的破碎。」             ──郭強生<br /><br />寫小說需要這樣銳利的眼睛和冷靜的腦子，如果本性不是這麼敏銳纖細，大概無法冷調直書人世的種種浮華、怨毒和不堪。能夠細細將可怖的人世剖開來，既讓人看見那陰暗猥瑣，又讓人贊歎刀法精準漂亮的，就是真才氣了。<br />好的小說家的文筆有時華美，有時驚悚，總能鑽進讀者的氣血經脈裡。就像〈海邊的房間〉裡那一根根針炙進女體的長針。或像〈入夢者〉裡的那台電腦，〈貓病〉中的一雙手，〈貞女如玉〉中的某個夜晚，那樣怪誕卻又理所當然。因為它們都是埋伏在我們現實生活中的機關，一不小心觸動，我們人人都難保不成了這個社會中的變態與瘋子。<br />但在黃麗群的筆下，這一切又都如此溫柔，沒有變形醜怪堆疊的字眼，因為平靜抒情才更顯得恐怖荒謬。<br /><br />黃麗群短篇小說集《海邊的房間》，今年適逢出版十二周年。堪稱教科書等級的這本小說，十多年來不知影響了多少小說創作者。收錄十三個精采的短篇，篇篇字句精煉，重看多少遍都挑不出瑕疵，依然令人興味盎然、沉醉其中，時報以經典復刻面貌重現，並加收新版後記，一窺女作家多年來的創作心路歷程。<br /><br /><br /></p>',10,0,'2026-03-17 18:06:24','2026-03-17 18:06:24','https://www.eslite.com/product/10012010632682600065009'),(7,'老師不敢教的國學常識: 課本外的文壇八卦、黑暗朝堂、追愛火葬場……把古人剝光光, 一探赤裸裸的人性真相!','黃方妤','9786267813492','麥田出版社','2026-02-26',430,'文學','https://s.eslite.com/b2b/newItem/2026/02/11/15138_143327816_163_mainCoverImage1.jpg','<p>真愛無敵還是片刻歡愉？織女竟是背叛愛情的仙女？\n<br />白居易成酸民、陶淵明變渣爹——國文課本外的才是真實人生，\n<br />那些老師不敢教的國學常識，黃老師講給你聽！\n<br />\n<br />＝本書特色＝\n<br />◆以「國學八卦週刊」重寫經典\n<br />將古文人物轉化為有血有淚、有笑有崩潰的真實人類。用通俗、幽默的敘事，讓讀者笑著理解歷史、重新認識人性。\n<br />◆跨年齡閱讀設計，兼具深度與啟發\n<br />每篇附三層延伸討論——小學的情緒教育、國中的價值討論、高中的批判思考，讓「國文課」成為思考人生的練習。\n<br />◆史料考據 × 現代語感，雙軌並行\n<br />以史籍為據，搭配當代語言重新演繹，可作為有趣的課堂教材，也能作為輕讀散文與文化讀物。\n<br />\n<br />當古人下凡——他們比你想的更人性\n<br />\n<br />你以為國學是討論仁義禮制的道德課？不，國學裡的字字句句其實都是展現人性的現場。\n<br />謝道韞拿刀護孫成戰神、韓愈懼高哭成八代文宗界的巨嬰……原來古代聖賢，比你想的還「人」。\n<br />跟著黃老師翻開課本，用最爆笑也最誠實的語氣，講出古人最真實的樣子。\n<br />\n<br />社會秘辛\n<br />打破古文課本的神聖濾鏡，揭露文人背後的血與淚。陶淵明不只是「歸園田居」的詩人，更是五個孩子餓到發抖的社會版渣爹；白居易一首酸詩逼死舞姬關盼盼，成為古代酸民始祖；韓愈懼高登山寫遺書，謝道韞以刀護外孫血戰叛軍。這裡沒有「高風亮節」，只有掙扎、恐懼與反抗——那些教科書不敢說的真相，全在此處翻盤。\n<br />\n<br />血脈糾葛\n<br />孔孟的「休妻」、朱自清的「慈父」、妲己與周文王的親情悲劇、岳飛與秦檜的婚姻對照……以最熟悉的家庭倫理為鏡，重新理解「聖父聖母」形象背後的故事，也重新定義「家」的意義。愛與責任、忠與欺瞞、父權與犧牲，全在這些古代家事中重演，所謂的孝與忠，從來不只是一種模樣。\n<br />\n<br />熱戀現場\n<br />古人談戀愛，一樣修羅場。沈復筆下的〈兒時記趣〉其實暗藏亂倫醜聞；漢武帝與李夫人兄妹的愛恨糾纏，比宮鬥劇更荒謬；牛郎織女的愛情故事藏著背叛；徐志摩的浪漫，是渣得優雅。用最甜的筆寫最酸的愛，將神話與情史都拆解成真實的慾望與孤寂。愛，從來不是古人獨得的悲劇，而是千年不變的人性考題。\n<br />\n<br />喋血朝堂\n<br />文人與權力的愛恨糾葛，能讓友情走向毀滅？劉禹錫與柳宗元的兄弟情義，最終成了權力犧牲品；項羽的浪漫悲壯，其實是毀滅的瘋狂；介之推、稽康，用血肉為理想殉道……政治不只是歷史事件，更是人心的煉獄，原來那些詩與忠義的背後，藏著的不是高貴的理想，而是孤絕的心情。\n<br />\n<br />醫療趣聞\n<br />古人的養生觀堪稱地獄？柳宗元憂鬱到成為水逆代言人、何晏是第一位「醫美整形先驅」、沈復的童年創傷幾乎成了生理悲劇？重訪古代的「健康迷思」，看文人如何以身試藥、以命換文，從古代偏方到現代焦慮，這些故事其實都在問：為了「完美」，人可以瘋狂到什麼境地？\n<br />\n<br />古文，不只是語文，而是一種觀看的方式\n<br />\n<br />本書的最大野心，是把「國學」從道德至上的神壇上請下來。當我們不再只是背誦「歸去來兮」「燕子樓」「詠絮才女」這些符號，而能理解這些故事中所謂的「風骨」與「氣節」，並非完美的姿態，而是在恐懼與掙扎中，依然選擇誠實活著——古文不再只是文體，而是生命的見證。\n<br />\n<br />各界讚聲推薦（依姓氏筆畫排序）\n<br />\n<br />宋怡慧／作家、丹鳳高中圖書館主任\n<br />李慈欣／作家、「李慢慢的玩轉—故事課」版主\n<br />周偉航／時事評論員\n<br />明渺／小說家、編劇\n<br />痛風老饕／美食Youtuber\n<br />綠君麻麻／作家、閱讀推廣人</p>',10,0,'2026-03-17 18:06:28','2026-03-17 18:06:28','https://www.eslite.com/product/10012013192683093097003'),(8,'眾神之島','光風','9786263840652','蓋亞文化有限公司','2024-01-31',300,'文學','https://s.eslite.com/b2b/newItem/2024/01/22/295_110228672_688_mainCoverImage1.jpg','<p><br /><br />★獲國藝會獎勵、桃城文學獎小說組首獎、竹塹文學獎<br />★Books From Taiwan推薦選書得主<br />★文策院潛力改編文本得主<br />★文化部中小學生讀物選介得主<br /><br /><br /><br />我們生活在這麼一座「眾神之島」上，日常中總有無數的神聖時刻，或是徬徨無助時的禱求心安，或是神明遶境、廟會等信仰盛事的近在身旁，或是家宅歲時祭儀的傳承與感謝。<br /><br />善於捕捉人類心底的隱約「微光」，並融合「台味幽默」，光風以台灣民間信仰為主題，描繪出地基主、城隍爺、神農大帝、九庄媽、雷神和風神等神祇與台灣這塊土地的連結。有世間百態的眾生群像；有對信仰本質的探索；有人情、關係與生命的修復和維繫；也有祈求神蹟，卻發現救贖與自癒往往就在一線之隔的領悟。<br /><br />在民俗、神明、宗教的標籤之前，《眾神之島》更是一部細數台灣生活景象的日常故事集，講最平凡的人，最俗常的事，還有最樸素的盼望。<br />神在人間，身在此地，俗世的凡塵和煙火氣，都是島嶼的日常天光。</p>',10,0,'2026-03-17 18:06:32','2026-03-17 18:06:32','https://www.eslite.com/product/10012046692682510073002'),(9,'把日子慢慢變好','黃山料','9786263585003','三采文化股份有限公司','2024-11-01',420,'文學','https://s.eslite.com/b2b/newItem/2025/03/24/8087_162817825_31_mainCoverImage1.jpg','<p>你想要和怎樣的自己，<br />共度餘生？<br /><br />要去愛一個<br />能「把日子慢慢變好」的對象，<br />而不是磕磕碰碰，擾亂你生活的人。<br /><br />――黃山料長達八年的日記――<br />最誠實的自我對話，深掘潛意識的祕密<br /> <br />【國外暢銷佳績/得獎紀錄】<br />★蟬連四年 誠品「年度暢銷冠軍」<br />★總銷量破30萬本 華文暢銷作家<br /><br />【內容簡介】<br /> <br />-----------------------------------------------<br />不是要找一個「一輩子不會吵架的對象」，<br />而是要找到「吵了架也還願意走一輩子的對象」。<br />-----------------------------------------------<br /> <br />本書以一段挫敗的愛情為開端，<br />你的情緒，想告訴你什麼？<br />你的潛意識，如何影響你的命運？<br /> <br />作者多年前發現自己內心有兩種聲音、兩個身分、兩種人格。<br />其一，是本能的我、本我<br />（無助的小孩）<br />其二，是客觀且理智的我<br />（具備思維、洞察力的少年）<br /><br />透過身體裡「兩種人格」的互相探問，練習「覺察情緒」，進而提升「個體黃山料」在人際關係中的生存能力。內在的「少年」協助「本我」進行自我覺察、與自身情緒連結。建立健全的三觀———愛情觀、價值觀、人生觀。<br /> <br />明白「情緒」：找出情緒的來源、隨時確保和自己的情緒做連結。<br />明白「自我」：分析自己的感受，才能釐清自己嚮往的人生藍圖。<br />明白「愛情」：相愛是本能的吸引，但幸福與否，卻是理智的選擇。<br /> <br />★諮商心理師專文推薦★<br />──胡展誥・陳志恆<br /> <br />本書分享了深陷負面情緒時，可以如何自救，藉由體內「另一個人格」哲學般的引導，了解負面情緒從何而來？如何化解？而終於能「看清局勢、為人生做最好的選擇」。<br /><br />【為什麼我沒有安全感？】<br />先成為能帶給別人幸福的人，<br />才有本事留住能讓你幸福的人。<br /><br />【為何我控制不了我的情緒？】<br />可以表達你的憤怒，<br />但不要帶著憤怒表達。<br /><br />【如何培養真正的自信？】<br />我用客觀的事實來評價自己，<br />而非用他人的主觀看法定義自己。<br /> <br />【該和怎樣的伴侶，共度餘生？】<br />正因為伴侶能夠最深度的參與彼此「建構自我」的過程，所以，「你要選擇和怎樣的人共度餘生？」其實是在選擇「你想要跟怎樣的自己共度餘生？」<br /> <br />【讓你看見更深層的黃山料】<br />作者藉由多年的自問自答，剖析自己的心理狀態、探討「情緒・潛意識・命運」，三者間的關聯。與讀者一同趨向五種人生的自由———情緒的自由、人際關係的自由、事業的自由、財富的自由，及自我認可。<br /> <br />適合自己的選擇，就是最好的選擇；適合自己的生活，就是最好的生活<br /> <br />把情緒好好安放，<br />好好過日子，一切自有安排。<br /> <br />▏<br /> <br /> <br /> <br />▏<br /> <br /> <br /> <br />▏<br />願意主動解決問題的兩個人，就永遠也不會走散；願意擁抱彼此情緒的兩個人，就永遠也不會錯過。世上沒有真愛，只有願意互相理解的兩個人。<br /> <br />【書封設計亮點】<br />本次書封以兩個相鄰的圓圈代表作者內心的兩種聲音。<br />白色圓圈代表破碎的「我」，深色圓圈代表沉穩、智慧的「少年」，兩個人格互相對話、探索，藉此整理人生。<br />另外，封面紙質特別選用「大地之戀」，將精心挑選的麥稈與紙張結合，以紙張為「地」，讓麥稈的纖維於其中綻放，營造溫潤的手感及視覺效果。</p><p><br /></p><p><b><br /></b></p><p><b><br /></b></p><p><b>【迷誠品編輯推薦】<br /><br />標題｜黃山料新作，從探索自我的對話和做出選擇的過程《把日子慢慢變好》<br />撰文｜黃山料<br /></b><br />當一位「情緒穩定」的人看似容易，但其實不然。身處紛紛擾擾社會的我們，生活中總會遇到許多不可預料的突發意外，或是必須面臨難以跨越的變化。這些時候，不得不從中選擇一個當下的最佳決定，而情緒也在途中不斷面臨崩潰。<br /></p><p><a href=\"https://meet.eslite.com/tw/tc/article/202412190001?utm_source=eslite_com&amp;utm_medium=link&amp;utm_campaign=2024_life_well\" target=\"_blank\">☞點此進入迷誠品閱讀文章</a></p>',10,0,'2026-03-17 18:06:36','2026-03-17 18:06:36','https://www.eslite.com/product/10012014082682657441009'),(10,'石頭的思考: 鍾國強詩集','鍾國強','9786263148673','木馬文化事業有限公司','2025-10-08',400,'文學','https://s.eslite.com/b2b/vendor/vendor175862536736720250923190246/mainCoverImage1_1528355.jpg','<html><head></head><body><p>兩岸三地詩人　于堅、唐捐、飲江、楊佳嫻、鴻鴻、蘇紹連　一致推薦<br>●<br>當代詩一般都追求短平快，乖戾漸成風格。這種寫法的問題是，詩容易便宜。鍾國強的詩很慢。他試圖觸及語言的肌理。神經質的，精確，深究。「一種流動向善的文字」。文質彬彬。這似乎是香港詩人的一種傳統，對三十年代新詩追求的那種雅緻白話的一種深入。<br>——于堅（詩人）<br>●<br>石頭軟化下來時<br>便想天<br>天在底下<br>倒影上面的地獄<br><br>「詩要回應時代。詩要有人文關懷。這一直是我寫詩所堅持的。這也可能是我創作至今其中一個仍未改變的抱負。要如何回應？要如何關懷？這先不要問詩，而要問自己。只有內化為自己的感志，則遇目所察，切身所感，化而為詩，自有恰如其分的回應與關懷。」<br>——鍾國強<br><br>鍾國強為香港重要詩人，創作逾三十年，詩歌主題著重城市書寫、日常生活，筆調寫實，意象親人。書寫香港與世事變遷，溫和隱約，深意留予知者；寫人心不古，亦帶自嘲與開闊；記錄時代大事與凡人死生，收斂深沉。<br>本書共分「雨城」、「離家」、「麥皮」、「廚餘」、「春日」、「海島」、「繁花」七輯；從社會的宏觀，到親族的近觀，寫人、及物，再由小島擴寫世界，並以青春傷逝、家人悼亡，為歷經抗爭與疫情磨難的人們留下真摯的銘記。</p></body></html>',10,0,'2026-03-17 18:06:40','2026-03-17 18:06:40','https://www.eslite.com/product/10012043902683007927006'),(11,'臺灣草葉集: 跟著黃春明走讀身旁野花雜草','黃春明','9786264183666','遠流出版事業股份有限公司','2025-09-26',420,'文學','https://s.eslite.com/b2b/vendor/vendor175758314377720250911173225/mainCoverImage1_1518869.jpg','<p><iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/D12nOjow5rg?si=S-P2pmes8fGiVOp3\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen=\"\"></iframe></p><p>文學大師的三位一體創作<br />博物散文x植物寫生x手稿筆書<br /> <br />　　有聽過「一樟、二虹、三埔薑仔、四拔仔柴走」嗎？這是古早孩子選擇酷炫玩具的標準。哪些葉子能作「粿葉仔」？現今的紅龜粿為何讓人沒食欲……？<br />　　國際著名小說家黃春明，從小用腳讀地理，教室在天地之間，也因此他很擅長博物觀察和人文采風。這本書是他耗時多年對身邊野花雜草的探查、側繪、訪談耆老、研究、紀錄和書寫的成果。<br />　　全書分成「草葉」、「瓜果」、「花樹」等三大篇目，黃春明以獨特的說故事口吻，生動引導我們去觀看身邊似乎微末卻有大作用的植物，並搭配令人驚豔的植物寫生和田野筆記，包括古老葉、蓮蕉葉、霍香薊、牛震棕、空仔樹、烏桕……等等，並融入自己的生命故事與創作靈感。<br />　　於是，我們知道了名作〈魚〉的靈感由何而生。</p>',10,0,'2026-03-17 18:06:45','2026-03-17 18:06:45','https://www.eslite.com/product/10012010302682998609007'),(12,'花菱夫妻的退魔帖 4: 松印再現','白川紺子','9786263587793','三采文化股份有限公司','2025-10-17',400,'文學','https://s.eslite.com/b2b/vendor/vendor175879439064220250925175952/mainCoverImage1_1530059.jpg','<html><head></head><body><p>銷售破百萬冊《後宮之烏》、《朱華姬的親衛》奇幻羅曼史女王白川紺子。<br>時光回溯至大正三年的關鍵轉折，<br>面對疑影漸深燈火教的過往，花菱夫妻能否看穿真相？<br> <br>從淡路島回到東京的鈴子和孝冬，對淡路之君有了不一樣的體悟。<br>透過絡繹不絕的驅魔委託，花菱家與鴻氏燈火教的連結越加深厚。<br>大正三年×松印大人×姻緣鎖鏈，而另一位有千里眼能力的鴻八千代，卻在此時默默接近花菱家⋯⋯<br> <br><br>【國外暢銷佳績/得獎紀錄】<br>★日本推理作家協會會員、文學評論家‧細谷正充嚴選 「2022年最佳娛樂小說」<br>★日本全系列銷售100,000冊<br> <br>//日本讀者五星熱評//<br>．充滿臨場感的季節、美食和祭典描寫，帶著我們跟花菱夫妻一起迎來了新的劇情轉折。——（44歲，女性）<br>．孝冬和鈴子的相處越來越自然，彼此眼神交流就能心意相通。——（18歲，女性）<br>．終於！最重要的主線劇情有了驚人進展，連帶鈴子的大哥也有戲份了，太期待了吧。——（29歲，女性）<br>．看完之後鴻氏和燈火教的謎團越來越深了，真好奇作者接下去會怎麼寫！——（32歲，男性）<br> <br><br>【內容簡介】<br>「那些入魔的亡靈很可憐，誰都無法讓他們安息，淡路之君卻有能力拯救他們。總有一天妳會明白這個道理……」<br>鴻八千代的這句話，是種未來暗示嗎？<br> <br>暑氣未消的八月，仍忙於處理驅魔案件的花菱夫妻，雖然在淡路島上沒能尋得淡路之君的真相，但他們逐漸不排斥驅魔委託。<br> <br>某日，貴族院的議員祕書找上門，因為榆子爵家中玄關出現了渾身是血的婦人鬼魂。<br>因此得知鴻氏的夫人八千代是燈火教創辦人的女兒，和鈴子一樣是千里眼！<br>而八千代更不時偶遇或刻意接近鈴子，讓花菱夫妻對她充滿戒心。<br> <br>過程中得知了在六年前（大正三年），鴻氏和燈火教創辦人久津見徹底決裂；同一年，鈴子的淺草貧民窟家人被人殺害、孝冬的大哥實秋自殺！<br>此時出現的一張舊照片，竟讓鴻氏露出從未示人的冷漠……<br> <br>此時，花菱夫妻接到鈴子家人請託，一起勸說哥哥嘉忠去相親，也請他們探查女方家。<br>鈴子思及當初被淡路之君選上才和孝冬結婚的自己，愛與依戀是怎麼慢慢出現的呢？孝冬感受到了嗎？<br> <br>案件裡的種種線索交織，盛暑之下的悲傷鬼魂，最終能否得到救贖？<br> <br><br>【人物簡介】<br>◎淡路之君：以鬼為食的上臈冤魂，花菱一族的先祖。其職責是撫慰那些曾經含恨流放到淡路島的貴人冤魂。<br>◎孝冬：花菱男爵家次子，現任當家，其家系為神職華族。經手生意五花八門，同時還要替淡路之君尋找鬼魂。<br>◎鈴子：瀧川侯爵家的么女，為侯爵和瀧川家女傭所生，在淺草的貧民區長大。曾被喻為「千里眼少女」，現年十七歲。<br> <br>花菱夫妻親族<br>◎雪子、朝子：雙胞胎，鈴子同父異母的姊姊，千津的女兒。<br>◎嘉忠、嘉見：已故嫡妻的兒子嘉忠，為瀧川家接班人。嘉見為雪子和朝子的親弟。<br>◎千津：瀧川侯爵的小妾，為雪子、朝子、嘉見的生母。<br>◎由良：孝冬的傭人。<br>◎鷹嬸：鈴子的侍女。<br>◎阿若：由良的青梅竹馬。<br>◎虎吉：曾經和銀六、丁姨、鈴子共同生活的老人。<br>◎丁姨：曾經和銀六一起照顧鈴子的女性，是鈴子母親的朋友。<br>◎銀六：鈴子喪母後，曾經照顧鈴子的男性。</p></body></html>',10,0,'2026-03-17 18:06:49','2026-03-17 18:06:49','https://www.eslite.com/product/10012014082683008337002'),(13,'對方辯友, 請給我你的心','御喬兒','9786267710609','城邦原創股份有限公司','2025-10-02',330,'文學','https://s.eslite.com/b2b/newItem/2025/09/22/15138_180426114_643_mainCoverImage1.jpg','<p><strong>2024POPO原創小說大賞 愛情組 優選<br />新生代創作才女․御喬兒<br />暌違五年閃耀回歸，譜寫最純粹的青春物語</strong></p><p><br /><strong>故事節奏明快，角色刻畫入微且討喜，<br />是一部閱讀時，臉上會不自覺出現微笑的優秀作品。——評審大力讚賞<br /><br />-`♥´- 收錄浪漫加筆番外〈不一樣的成長，一樣的我們〉、〈想讓妳被全世界看見〉</strong><br /><br />⌁⌁⌁⌁⌁⌁❤︎⌁⌁⌁⌁⌁⌁<br /><br /><strong>愛是恆久的辯題，不變的是他們澄澈的真心。</strong><br /><br />在兩校辯論社聯合舉辦的迎新中，<br />郝周因玩遊戲輸了，必須接受懲罰，<br />組員們慫恿她在示範賽中撩卓明辯論社的社長莫全，<br />於是——<br /><br /><strong>「對方辯友，你的愛情裡會包括我嗎？」<br />「目前沒有，但妳可以試著改變看看。」</strong><br /><br />郝周明白，莫全會這麼回答，<br />是為了不讓她下不了臺，為了活絡氣氛，<br />但她的心，卻還是不受控地加速跳動。<br /><br />一連串的因緣巧合，讓郝周有了和莫全拉近距離的機會。<br />在和莫全的相處之下，她發現自己對他產生了不一樣的感覺，<br />與此同時，她卻也察覺到，在他人眼裡完美無缺的莫全，<br />總帶著一股淡淡的神祕感，不讓任何人走進他的心。<br /><br />直到那夜，一場誤會讓她窺見他面具底下的傷痕，<br />她終於明白，莫全埋藏在心底的祕密是什麼。<br />而在他坦然面對她的那刻，<br />她也暗暗下定決心，不再隱藏自己的心意……&nbsp;</p>',10,0,'2026-03-17 18:06:54','2026-03-17 18:06:54','https://www.eslite.com/product/10012013192683002534001'),(14,'洄瀾紀事: 花蓮時光記事簿','陳克華','9786269996421','斑馬線文庫有限公司','2025-10-16',700,'文學','https://s.eslite.com/b2b/newItem/2025/09/19/8141_085902248_859_mainCoverImage1.jpg','<html><head></head><body><p>《洄瀾紀事》是一部獻給花蓮的深情書寫，也是一次文字與圖像的雙重創作。洄瀾，是花蓮的古稱，也是詩人陳克華的出生地。本書以詩與散文為經，作者親繪的彩色畫作為緯，共同織成一幅關於故鄉的完整圖景。<br>在文字裡，花蓮的山海被轉化為會呼吸、有靈魂的存在。從群山到縱谷，從海口到小鎮，詩人以凝視與回望，捕捉土地上的美麗與滄桑。在畫筆下，印象則化作線條與色彩，帶領讀者進入另一種視覺的詩意。<br>本書並非單純的地方紀錄，而是把花蓮放進生命與時代的脈絡中加以凝視。它既是旅行者的眼，也是歸鄉人的心。透過一首首詩、一次次的反覆，讀者看見的不只是地理風景，而是人與土地之間永難割捨的情感。<br>《洄瀾紀事》動人的地方，在於它讓故鄉既具體又抽象：它是山川，是大海，是街角的日常；同時，它也是記憶、是歸屬、是難以命名的鄉愁。陳克華用文字與畫筆告訴我們：即使漂泊，心中總有一個「洄瀾」作為靈魂的港口。<br>這是一本可以閱讀、可以凝視、也值得珍藏的作品。對花蓮人而言，它是土地的溫柔紀錄；對非花蓮人而言，它是一面照見自己根源與情感的鏡子。<br><br></p></body></html>',10,0,'2026-03-17 18:07:05','2026-03-17 18:07:05','https://www.eslite.com/product/10012030392683003676007'),(15,'星光流轉的夜: 我的讀者之書 2 (附唐諾經典引文選輯)','唐諾','9786267465820','本事出版','2025-10-13',780,'文學','https://s.eslite.com/b2b/vendor/vendor175887024823920250926150407/mainCoverImage1_1530470.jpg','<p>買就送《唐諾經典引文選輯》，物超所值，立馬下單！<br /><br />「這是我做最久的工作，也還持續，為著書和其書寫者而寫，而了不起的書和了不起的書寫者還有這麼多沒寫，也許這個工作是做不完的。」──唐諾<br /><br />唐諾這本談經典作家與經典作品的讀者之書，原名《在咖啡館遇見14個作家》，<br />十五年後以《星光流轉之夜》重新出版，<br />讀來就像剛完成的著作一樣。歷久彌新，不是嗎？<br /><br />想像一下，當螢火蟲被放進挖空的甘蔗裡，神奇的事就發生了，<br />這麼簡單的組合，就能讓一個個微弱短瞬的光點活下去……<br />這本書的一篇篇文字不過是一截截挖空的甘蔗而已，<br />裡面有14位書寫者、14部經典作品，就好像14隻螢火蟲，<br />點亮我們被限定的視野，引領我們仰望文學星空……<br /><br />海明威的《渡河入林》<br />柯斯勒的《正午的黑暗》<br />康拉德的《如鏡的大海》<br />契訶夫的《發現契訶夫》<br />波特萊爾的《人造天堂》<br />納博科夫的《普寧》<br />福克納的《八月之光》<br />果戈理的《迪坎卡近鄉夜話》<br />波赫士的《書鏡中人》<br />葛林的《一個燒毀的麻風病例》<br />艾可的《波多里諾》<br />朱天文的《巫言》<br />安東尼‧路易士的《基甸的號角》<br />吉拉爾的《替罪羊》<br />這本書自我設定的位置是進入，而不是褒貶點評；<br />這本書尋求的是可能性，以替代只此一種的答案，<br />因此，這是一本閱讀者的書，而不是一本評論者的書，<br />這本書給自己最艱難的工作正是，如何在廣漠如冰原的世界中召喚同類，<br />並且讓書中提到的每一本書都能找到讀它的人……<br />由唐諾陪伴我們，一起閱讀，享受閱讀，體驗閱讀的美好。</p>',10,0,'2026-03-17 18:07:15','2026-03-17 18:07:15','https://www.eslite.com/product/10012117772683010432009'),(16,'自己的命運自己寫 (隨書贈: 命運書籤1款,3款隨機附送)','克麗絲汀．佩林','9786267728246','堡壘文化','2025-10-15',460,'文學','https://s.eslite.com/b2b/newItem/2025/10/09/8425_172257607_473_mainCoverImage1.jpg','<p>紐時暢銷作家克麗絲汀．佩林最新力作<br />全美公共圖書館館員票選Library Reads 2025年4月推薦好書<br />《今日美國》USA TODAY 2025年8月暢銷書<br />《每天破一起謀殺案》作者 G.T. 卡柏盛讚推薦<br /><br />───｜隨書贈｜───<br />命運書籤1款（共3款，隨機附送）<br /><br />◇◇◇<br /><br />「那隻鳥回來了。」<br />預言再現？！<br />挖掘不完的過去是阻力還是助力？該執著還是放下？<br />陰謀ⅹ惡意ⅹ正義ⅹ宿命的混亂交織，小鎮塵封已久的祕密即將被揭開！<br /><br />◇◇◇<br /><br />剛破案沒多久的安妮隨即又碰上另一樁命案，還有新的預言。<br />過往如幽魂般揮之不去，緊跟著安妮與諾爾城堡鎮的所有人。<br /><br /><br />　　安妮．亞當斯破解姑婆法蘭西絲的命案後，依照姑婆的遺囑，繼承了格雷夫史當莊園，正式成為莊園的女主人，然而，生活並沒有變得更順利，對安妮來說，不論是過大的莊園，或是諾爾城堡鎮，她都覺得自己格格不入。<br /><br />　　某天，安妮突然碰上占卜師佩奧妮．蓮恩，這位曾經預言法蘭西絲姑婆命運的占卜師，想要請安妮調查奧莉薇亞．格雷夫史當的車禍案件。突如其來的要求讓安妮摸不著頭緒，更可怕的還在後頭：佩奧妮．蓮恩在請安妮調查車禍案件不久，竟成為一具冰冷屍體，還躺在格雷夫史當莊園中、安妮的眼皮底下！<br /><br />　　安妮也因此不得不展開調查，而那也表示她得再次借助姑婆的日記，探尋深埋已久的過往──格雷夫史當家族三人喪命的那場車禍真相。過去與現在的線索也在安妮的解謎過程中，變得混亂不已，難以釐清。安妮還一起參與了法蘭西絲姑婆的瘋狂年少時期！<br /><br />　　隨著更多關於車禍的線索被挖出以及第二具屍體的出現，安妮也深陷危機之中：兇手不但可隨意進出莊園，還熟知小鎮的地形、路徑，彷彿連安妮的行蹤也一清二楚，讓安妮的一舉一動變得可疑，甚至被警方設為命案嫌疑人。而鎮上原先看似友善、值得信任的朋友，也開始讓安妮起了疑心，連安妮的媽媽也變得怪裡怪氣的？！安妮這次能順利破案，改寫命運嗎？<br /><br /><br /></p>',10,0,'2026-03-17 18:07:22','2026-03-17 18:07:22','https://www.eslite.com/product/10012043902683011718003'),(17,'馬爾泰手記 (里爾克逝世百年德文直譯紀念版)','萊納．瑪利亞．里爾克','9786263148802','木馬文化事業有限公司','2025-10-15',500,'文學','https://s.eslite.com/b2b/vendor/vendor175923962532020250930214024/mainCoverImage1_1531511.jpg','<html><head></head><body><p>「今天誰還會在乎一場好好安排的死亡？沒有人。期望擁有自己的『死』的人，會愈來愈罕見。過一陣子，期望擁有自己的『生』的人，也會同樣罕見。」<br><br>一個人漂泊無依<br>如何自孤獨、病與死<br>創造與上帝，以及愛<br>湧出最深刻的力量？<br><br>在來自沒落貴族家庭的丹麥青年馬爾泰．勞里茲．布里格眼裡，巴黎這座城市並非取之不盡的流動饗宴，而是瀰漫貧苦與死亡氣息的灰暗之地。二十八歲，一無所成，沒人認識，鎮日恐懼。不時，舊日回憶攫住他的思緒，領他想及至親的死亡、母族宅邸撞見的幽靈，以及與親戚阿貝娜相處的甜蜜時光……在極致的孤獨之中，馬爾泰承受一切，他將坐下，日以繼夜寫作，為了自心中迸發出一行詩的第一個字。<br><br>《馬爾泰手記》為德語詩人萊納．瑪利亞．里爾克以七十一個片段寫成的半自傳式小說，探討一個人如何在最深刻的孤寂當中尋索童年的意義，直視自身無以名狀的恐懼，領悟與上帝的距離，習得愛所必將擔負的重量。<br><br>—<br><br>「要是人們過早寫詩，那些詩可以說是輕如鴻毛。人們應該等待，窮盡一生去收集意義與甜美滋味，花上盡可能長久的一生，他或許可以寫出十行好詩。在一個罕見的時刻，一行詩的第一個字會在他們的內心裡迸發出來、傾巢而出。」<br><br>——《馬爾泰手記》</p></body></html>',10,0,'2026-03-17 18:07:25','2026-03-17 18:07:25','https://www.eslite.com/product/10012043902683011704006'),(18,'時間迴旋','羅伯特．查爾斯．威爾森','9789862627358','貓頭鷹出版社','2025-09-11',550,'文學','https://s.eslite.com/b2b/newItem/2025/09/03/15138_104237433_679_mainCoverImage1.jpg','<p>有一天，他們眼看星星都熄滅了……\n<br />\n<br />◎2006年雨果獎最佳長篇小說\n<br />◎2009年日本星雲獎最佳海外長篇小說\n<br />◎史蒂芬金盛讚，影視傳言不斷的科幻大作\n<br />\n<br />「威爾森是個棒到不行的說故事高手，而且閱讀他的作品不需要任何背景知識。……這裡有豐富的想像力，還有生動的人物與靈魂。」──史蒂芬金強力推薦\n<br />\n<br />　　在一個十月的夜裡，群星忽然綻放光芒，然後同時熄滅。那一年泰勒十二歲，與他最好的朋友雙胞胎黛安、傑森一起目睹了這一幕，他們的人生與整個世界的命運從此改變。一張不知名的黑網遮蓋了地球，黑網之外，整個宇宙的時間正以驚人的速度前進：短短五十年後，太陽即將迎來死亡。\n<br />\n<br />　　在末日的陰影下，泰勒與雙胞胎漸漸長大，走上完全不同的道路。傑森成為頂尖科學家，用先進科技展開探索；黛安歸向宗教，在神學中尋找心靈慰藉；泰勒選擇成為濟世救人的醫生，卻不知道這在世界毀滅時還有什麼意義。\n<br />\n<br />　　那張黑網允許人造物體通過，卻阻擋了隕石與流星。很快地人類計劃改造火星，快速飛越的時間使火星地球化能在短期內成功，並將未來與希望寄託在火星的人類後代上。不過當發射計畫取得碩大的成功、殖民火星似乎成功的同時，火星也被黑網包圍……\n<br />\n<br />在每一天都可能是最後一天的絕望中，該如何找回心靈的勇氣？</p>',10,0,'2026-03-17 18:07:30','2026-03-17 18:07:30','https://www.eslite.com/product/10012013192682985322001'),(19,'王思迅人生講座套書: 易經白話講座+金剛經白話講座 (2冊合售)','王思迅','9786267752388','如果出版','2025-09-10',1400,'人文史哲','https://s.eslite.com/b2b/vendor/vendor175677865673820250902100416/mainCoverImage1_1510373.jpg','<html><head></head><body><p>本套書共二冊，《易經白話講座——64卦，卦卦讓你找到內在真實的力量》＋《金剛經白話講座：放下的人生修行》<br><br>在變化不定的人生中，你需要修行的智慧<br>讓「提升生命智慧的講者」王思迅，以《易經》教你轉念，以《金剛經》教你放下。<br><br><br>■《易經白話講座——64卦，卦卦讓你找到內在真實的力量》<br><br>《易經》看似複雜，其實只教我們一件事：<br>面對人生無可避免的起伏變化，如何從自己身上找到力量？<br><br>一本幫助我們化解內在偏執，轉念面對外在挑戰的《易經》使用手冊<br><br>面對人生的轉折，你知道該如何度過，如何面對嗎？<br>你是否清楚知道現在面臨的處境是上天想給你什麼樣的功課？<br>面對困難，如果你還想用舊有的習性去面對，那結果只會是巨大的生命浪費，而不是成長。<br><br>《易經》成書於一個苦難的時代，而《易經》正是對應苦難而生的智慧之書。若能理解《易經》六十四卦，就可以借用古人智慧看盡人間事理，理解生命起伏。遇到人生逆境時，會知道如何脫困而出，處於順境之際也能善加把握，不讓自己耽溺徘徊，失去提升的機會。<br><br>台灣最大音頻課程平台「孜孜線上」銷售第一名師，被學生譽為「提升生命智慧的講者」王思迅，以淺顯易懂的方式，詳細解說卦義及每卦背後的故事，教你如何透過《易經》挖掘自己的內在真實，與生命相互印證。<br><br>＊詳細講解《易經》六十四卦卦辭、爻辭的現代意義<br>＊從甲骨文及商周時代的歷史脈絡切入，回到源頭瞭解卦的本義<br>＊講解貼近生活，只需要基本國學根柢就能對卦義有切身體會<br>＊具體說明「意識卦」占卜法，讓你能藉由占卜瞭解自身所面臨的功課<br><br>六十四個形象生動的卦，就像六十四則寓意深遠的故事<br>《易經》記述的是古人的生命體會與歷史經驗，因此六十四卦就像六十四則寓言故事，也像六十四則對人生的提醒。例如渙卦，是藉由商代盤庚遷都的故事告訴我們，比起離散更重要的關鍵是學習凝聚。又例如明夷卦講的是商朝三賢人微子、比干及箕子勸誡紂王不成反遭禍的故事。卜到明夷卦一般都認為是個凶卦，但《易經》真正要告訴我們的是，人在明夷之中，最重要的不是成敗，而是內在的轉化。如果把成敗當成首要，那就完全看錯重點，也顛倒了吉凶。<br><br>學習《易經》的方法不是讀它，而是在日常生活中，頻繁地使用它<br>《易經》不光是本卜卦之書，但學《易經》一定要學卜卦，因為學會卜卦之後，《易經》讀起來就會變得很簡單。讀不懂《易經》，往往是因為不知道如何把《易經》的內容對應生活，而卜卦恰好可以解決這個問題。卜卦是一種與《易經》對話的方式，它能讓《易經》的文字活過來，每一句話都像是人生導師對我們最真切的提醒。本書收錄詳細的「意識卦」占卜教學，初學者也能輕鬆上手。<br><br>《易經》不是直接預測吉凶，「轉」才是《易經》的關鍵<br>天下並沒有全部都是吉的事，也沒有全然的凶。吉中會有凶險，凶中也可以得到吉象。凶是無法完全避免的，但是我們可以好好應對凶，從中學得許多教導。《易經》不是要我們「趨吉避凶」，而是要我們知道該用什麼角度去面對難題。不要困在任何一卦之中，而是要學習在心念一轉之下，可以從這一卦走向另一卦。人世的「變」，這是外在的吉凶，當我們內心有「轉」的力量，就不用害怕外在吉凶。<br><br>學習《易經》就是學會如何面對困境，學習如何更好地調整自己<br>我們之所以會遇到某困難，常是我們的內心有偏頗、有習性，有失衡的地方。如果我們內心平衡了，困難不一定會發生，或者，這件事並不會顯得這麼困難。卜卦告訴我們的答案，都是針對我們內心的偏執提出建言。如果認真把它當成人生的功課，我們就能恢復原有的平衡，困難也能得到解決。使用《易經》，就是要讓它改善我們做人做事的方法，要讓它提升我們的智慧與技能，讓我們變成更好的人。<br><br>如何把充滿變動與欲求的心，安住在簡單純粹的永恆形式之中，而且依然充滿創造力，生生不息，既超越矛盾與煩惱，又得到自在與寧靜。這就是《易經》最終要教導我們的功課。<br><br>■《金剛經白話講座：放下的人生修行》<br><br>看見內心，就能放下，走向自己真實的生命<br><br>《金剛經》講的是心，<br>是佛陀告訴我們如何正確運用自己的心，<br>放下執著的般若智慧<br><br>如果你開始在意該怎樣使用時間，開始想過好這一生，<br>想讓生命有意義、有價值，讓自己成為自己喜歡的樣子，<br>你就一定需要《金剛經》<br><br>《易經白話講座》暢銷書作者王思迅，逐字逐句，與我們分享佛陀的體悟<br><br><br>•《金剛經》是引領人生修行的寶貴經典<br>生命中總有一個時刻，我們會開始真心希望自己變得更好，真心希望自己的生命變得更有意義，並且願意在這件事情上付出努力，這時我們就已開始踏上了人生修行的旅途。<br>在我們提升自我的道路上，《金剛經》能提供我們最簡便、最直接，也最有效的方法。<br><br>•正確地觀看我們自己的心，就是般若智慧<br>我們的心，喜歡認定事物是這樣的，或那樣的。這個認定，會逐漸強烈，變成難以改變的傾向，然後控制我們的頭腦與身體，讓我們依循這個認定而去行為與反應。<br>如果我們能夠從這個認定的傾向中掙脫出來，那我們就能脫困，不會被控制，也能得到自由。透過自我覺察，知道自己的本心，放下自己原有的傾向，這種能力，就是我們內心智慧的顯現，就是般若智慧。<br><br>•放下，就能斷除執念，走向自己真實的生命<br>《金剛經》告訴我們，只要能放下執著，我們不但可以不隨因果業力而流轉，同時也可以體會到生命真實的意義。當我們慢慢學會「放下」，我們的世界就會越來越明澈，越來越清楚，我們的人生道路也會越來越明確，越來越篤定。最後，我們會知道自己應該過怎樣的生活，成為怎樣的人，在怎樣的事情上努力，並在「宗教性」的實踐上，圓滿我們的一生。<br><br>•《金剛經》給我們的是究竟圓滿的智慧<br>用置身事物之上的角度觀看自己、觀看他人、觀看環境、觀看時空的變化，也觀看自己思維中的一切。觀看之後再如實地放下，這就是《金剛經》要告訴 我們的智慧。它能讓我們對周遭世界多一分包容，也讓我們多一分洞見，反觀自照，成為更好的自己。這就是智慧之上的智慧，究竟圓滿的智慧。</p></body></html>',10,0,'2026-03-17 18:08:04','2026-03-17 18:08:04','https://www.eslite.com/product/10012117772682988580002'),(20,'正是時候讀莊子限量精裝套書 (暢銷經典版/附金句書卡,1組4張/3冊合售)','蔡璧名','9786264442305','時報文化出版企業股份有限公司','2026-02-10',2500,'人文史哲','https://s.eslite.com/b2b/vendor/vendor176836298147720260114115621/mainCoverImage1_1587031.jpg','<p>★《正是時候讀莊子》十周年暢銷經典版，全新開本（18開）。<br />★封面採用蒝織紙，觸感溫暖細緻；書盒特殊加工，設計典雅，值得收藏。<br />★隨書贈送金句書卡（8 x 12 cm），一組四張。(書卡與《莊子，從心開始【增訂紀念版】》限量精裝套書同款)<br /><br />時局板蕩，曖昧天光，半部《論語》治天下，半部《莊子》治心身，正是時候，好好讀莊子。<br />讀莊子前，心隨境轉。你在風浪之間，載浮載沉。	<br />學莊子後，境隨心轉。風浪在你的腳下，任你乘御遨遊。<br /><br />正是時候讀莊子【暢銷經典版】壹：莊子的姿勢、意識與感情<br />《莊子》隱身在經典群中，已閃爍千年，因他提出一套人人可以執簡御繁的療癒、強化心身的方法。原來自己的心，才是最值得征服的戰場。原來心不止可以煩、可以亂、可以傷，還可以自在飛翔。原來心情好壞，也是種可以自主的選擇。原來內心安定，才是迎戰亂局最有力量的武器。原來讓身邊的人學會安心，是送給情人最好的禮物。原來日常生活中的走、站、坐、臥，只要選對姿勢，效果將遠勝每週額外運動數小時。原來只要掌握「深情而不滯於情」的用情原則，便可無傷、悠遊於情場。原來人生的方向，比行進的速度來得重要。原來命途中的逆境，可以不是噩運，而是可供強化生命的機緣，是上天落下最珍貴的禮物，若能好好把握、珍惜，將是比如意順遂更值得紀念的風景。<br /><br />正是時候讀莊子【暢銷經典版】貳：莊子的人情、御變與安適<br />人間世中，因為莊子，我一直聽到有一個聲音，喚我回頭。<br />回頭，將習慣照看外在世界的探照燈，返回投照自身。<br />於是，照見的不是人間世的驟雨疾風，而是在雨裡風中欣喜於嚼出前所未嘗的生命況味。逆境中不會耽溺於沮喪，而能日漸欣然於際遇難得。照見的不是人間世的挫敗、蒙冤或受辱，而是在挫敗中發現自我從中才可能得緣成長，在蒙冤受辱中發現自我還可以更加推擴的同理心。功成不會亦不敢自滿，明白該感謝眾多人士的成全。<br />放下成見，從紛擾中抽身而出、等距照看，從對立的兩端騰升到足以明照一切的天空。隨時留那麼點注意力在一己心身──從一天一刻凝聚精神，到時時刻刻凝聚精神。以強化己心能耐為一生最重要的抱負、最核心的價值。<br /><br />正是時候讀莊子【暢銷經典版】參：莊子的遊心、養身、學愛與自由<br />莊子說，形是柴薪，心神如火──何傷薪盡？依舊火傳！唯有能夠自主的心靈，方得自在、自由。<br />當心身的安適，不再倚賴際遇的安穩，在變易的世界裡打著不易的拳，在風波難息的日子裡守著必需日益康強的心。珍愛寸陰，珍愛緣遇，時刻陶養一顆持平安定的亮著的心，寄寓在挺拔安舒輕靈的身，本此觀照一己、情人、親朋、家國、天地，堅持在心平身輕中盡分盡心盡力。<br /><br /></p><p><br /></p>',10,0,'2026-03-17 18:08:08','2026-03-17 18:08:08','https://www.eslite.com/product/10012010632683078566005'),(21,'我可能錯了: 森林智者的最後一堂人生課','比約恩．納提科．林德布勞/ 卡洛琳．班克勒/ 納維德．莫迪里','9789861344454','先覺出版股份有限公司','2023-02-01',450,'人文史哲','https://s.eslite.com/upload/product/o/2682324108006/20230414063258082389.jpg','<div><p><b>17</b><b>年的森林寺院修行、返鄉後的憂鬱巨浪、與漸凍症並肩走向死亡的日子，</b><b></b></p><p><b>這句話，成了他一生的金言，</b><b></b></p><p><b>也將</b><b>帶你擺脫焦慮風暴、生命備受鼓舞！</b><b></b></p><p><b></b></p><p><b>※</b><b>榮獲各大書店</b><b>2023</b><b>年度選書、</b><b>2024</b><b>年度暢銷總冠軍！</b><b></b></p><p><b>※</b><b>有聲書於</b><b>2025</b><b>年上市後，旋即登上</b><b>Readmoo</b><b>、</b><b>Kobo</b><b>、博客來有聲書暢銷冠軍。</b><b></b></p><p><b>※</b>心能量管理中心執行長 <b>許瑞云</b>醫師、主持人 <b>曾寶儀</b>、靈性導師 <b>阿迪亞香提</b>──專文推薦</p><p>　身心靈導師 <b>賴佩霞</b>博士──好評推薦<b></b></p><p><b>※</b>封面圖《崇敬》（Adoración），是當今古巴重量級且身價最高的藝術家<b>托馬斯．桑切斯</b>所繪，諾貝爾文學獎得主馬奎斯也是托馬斯的忠實粉絲。</p><p><b></b></p><p><b>30</b><b>國</b><b>讀者感動淚推：</b></p><p>‧如果我一生只讀一本書，我想就是這本了。</p><p>‧這是一本當痛苦、焦慮還沒有離開我的心時，我會想再拿出來重讀的書。</p><p>‧即使不是佛教徒，它也是一本你會想一遍又一遍閱讀的書，可以撫慰內心的疲憊。</p><p><br /></p><p>※※※※※※※※※※※※※※※※※※※※</p><p><b>全球銷量破百萬冊！</b></p><p><b>瑞典每20</b><b>個人就有1</b><b>個人看過這本書！</b><b></b></p><p><b>一句簡單又神奇的箴言，</b><b></b></p><p><b>為你在困頓中找到撫慰與前進的勇氣！</b><b></b></p><p>※※※※※※※※※※※※※※※※※※※※</p><p><b></b></p><p><br /></p><p>2022年1月，經濟學家比約恩．納提科．林德布勞的辭世，讓全瑞典人落淚哀悼。《我可能錯了》是比約恩人生的最後一本書，在2020年一出版就造成轟動，成為暢銷書冠軍。</p><p>26歲事業有成的比約恩，在即將成為跨國大企業最年輕的財務長時，選擇拋下一切到泰國森林展開17年的出家生活。在森林寺院中，他被授予了稱號Natthiko──意思是「在智慧中成長的人」。</p><p>「我可能錯了」這句話，正是比約恩在寺院中汲取到最關鍵的智慧，幫他挺過17年後再回瑞典時的憂鬱風暴，以及罹患漸凍症逐漸走向死亡的日子。</p><p>在這本讀者給予「一輩子的床頭書」「每一頁都會畫重點的書」等好評如潮的書中，並不是關於宗教，也不是要告訴你如何過生活，更不是要你接受一套新的信仰。它是要幫助你活得更愉快、更自由，而且以清晰明智的方式與自己的思想和情感連結。</p><p><b></b></p><p><b>★書店推薦：每個公司都需要放一本。</b></p><p><b>★《閱讀前哨站》瓦基：2023</b><b>年最喜歡的書。</b></p><p><b>★曾寶儀Podcast</b><b>多次推薦：2023</b><b>年看過最好的書。</b></p><p><b>★周志建心理師回味再三的旅行書</b></p><p><b>★《張修修的不正常人生》：雖然很薄，但是威力驚人。</b></p><p><b>★2023</b><b>金石堂年度十大影響力好書</b></p><p><b>★2023</b><b>博客來紙本、電子新書Top1</b></p><p><b>★2024</b><b>博客來紙本、電子總榜Top1</b></p><p><b>★2024</b><b>電子書Readmoo</b><b>、Kobo</b><b>、HyRead Top1</b></p><p><b>★2020</b><b>年，榮獲瑞典Adlibris</b><b>書店年度最佳非文學著作、Storytel</b><b>大獎年度最佳非文學著作</b></p><p><b>★2021</b><b>年，有聲書榮獲瑞典「年度之聲」大獎</b></p><p><b>★2022</b><b>年，榮獲瑞典Nextory</b><b>電子書獎、韓國Yes24</b><b>書店讀者票選「年度之書」</b></p><p><b>★售出英、西、法、德、韓等30</b><b>國版權</b></p><p><b></b></p><p><b>當你需要安慰和勇氣時，比約恩溫暖的智慧會讓你跳脫固著的焦慮，找到內心的平靜──</b></p><p>◆在這十七年整日的精神修練中，我最珍視的一點就是：我對自己的每個念頭，再也不相信了。這是我的超能力。最棒的一點在於：這是所有人的超能力。</p><p>◆我不會鼓勵任何人進行正面思考。完全不鼓勵。我個人並不相信正面思考有特別大的力量。我一直覺得正面思考是比較膚淺表象的。</p><p>◆覺得別人很討厭，是人之常情。如果你想讓一個人好相處，行為舉止也不會讓你太反彈，其實只有一個小祕訣：學會喜歡他們本來的樣子。</p><p>◆有位來自奧克拉荷馬州的比丘，他討厭我整整四年，從未斷過。事後回顧起來，我需要有人討厭我，這樣才能認清：總是想討所有人喜歡，是多麼沒意義。</p><p>◆下次，當你感覺到衝突開始悄悄醞釀、你和一個人的關係演變到快破裂的時候，只要用任何你喜歡的語言，真誠與篤定地對自己重複這句箴言三次，你的擔憂就會雲消霧散──我可能錯了。我可能錯了。我可能錯了。</p><p>◆帶有「應該」這個詞的種種念頭，讓我變得委屈、沉悶和孤獨。如果你能意識到這種情況有時也會發生在自己身上，不妨就試試這個手部的動作──先是用力握緊拳頭，然後鬆開成張開的手掌。它很簡單，但它貼切地展示了我們如何能放下自己太執著的事。</p><p>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n◆焦慮是我見識過的最嚴格與最好的精神導師。</p><p><br /></p><p><b>【迷誠品編輯推薦】<br /><br />標題｜面對人生迷茫，勇敢跳出！YouTuber 藍亦明必看人生書單與旅遊選書｜迷誠品YouTube<br />撰文｜迷誠品內容中心</b><br /><br />在人生的不同階段，離開舒適圈往往是每個人必須面臨的挑戰，這並非易事。尤其當感到迷茫時，要改變原本的人生軌跡更需要勇氣。能夠察覺自身的倦怠，並敢於放下安逸的環境重新出發，本身就是一個值得敬佩的選擇。<br /><br />在迷誠品YouTube單元《誰在誠品》最新一集中，邀請到 Youtuber 藍亦明，透過他的親身經歷分享給身處迷茫的大家一些推薦書單，同時也挑選一本未來拍攝企劃會用到的旅遊書。<br /><br /><a href=\"https://meet.eslite.com/tw/tc/videos/202510140001?utm_source=eslite_com&amp;utm_medium=link&amp;utm_campaign=2025_lanyimingyoyo\" target=\"_blank\">☞點此進入迷誠品閱讀文章</a></p></div><div><font size=\"2\"><br /></font></div><div><p><strong>【迷誠品編輯推薦】</strong><strong><br /><br /></strong><strong>標題｜別讓吵架折磨彼此，適時聽從內心的提醒《我可能錯了》，爭贏是多麼沒意義</strong><strong><br />撰文｜許瑞云</strong><br /><br />生活中要面對的人事物太多，內心能乘載的情緒太少，我們總是讓自己長時間處於相同情緒的死胡同中，而忘了其實還有更多的情緒在隊伍的後方等待著自己。<br />總是害怕被人討厭、總是希望能爭贏，但也許我們不必這樣為難自己。<br /><br /><a href=\"https://meet.eslite.com/tw/tc/article/202302150001?utm_source=eslite_com&amp;utm_medium=link&amp;utm_campaign=2023maybe_wrong\">☞點此進入迷誠品閱讀文章</a></p><p><br /><br />【歡迎收聽｜迷誠品Podcast】《我可能錯了》森林智者的最後一堂人生課｜今天讀什麼</p></div><div><p><iframe src=\"https://open.spotify.com/embed/episode/74ObXjnBotwSckhCkVpVdK?utm_source=generator\" width=\"100%\" height=\"152\" frameborder=\"0\" allowfullscreen=\"\" allow=\"autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture\" loading=\"lazy\"></iframe></p><p><br /></p><p><br /></p></div><div><font size=\"2\"><iframe width=\"560 \" height=\"315 \" src=\"https://www.youtube.com/embed/4WMEvWhHJr8 \" title=\"YouTube video player \" frameborder=\"0 \" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share \" allowfullscreen=\"\"></iframe><br /><strong><br /></strong><strong><br /></strong></font></div><div><iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/pwC-dHYVfjA\" frameborder=\"0\" allow=\"accelerometer;autoplay;encrypted-media;gyroscope;picture-in-picture\" allowfullscreen=\"\" style=\"font-size: small; color: var(--es-gray-800); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, &quot;Helvetica Neue&quot;, Roboto, Arial, &quot;Noto Sans&quot;, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;, PingFangTC, &quot;Microsoft JhengHei&quot;, sans-serif;\"></iframe><br /></div><p><br /></p><p><b>【迷誠品編輯推薦】<br /><br />標題｜2023下半年誠品書店TOP10出爐！擺脫社群焦慮，從閱讀找回內心平靜<br />撰文｜迷誠品內容中心</b><br /> <br />透過2023下半年誠品書店10大暢銷書榜，一起翻閱那些可能錯過的遺珠，也一同感受閱讀迷人的魔力，讓我們抽離現實的喧囂，沉澱心靈的塵埃，重新點燃內心的寧靜之光。<br /></p><p><a href=\"https://meet.eslite.com/tw/tc/article/202311150002?utm_source=eslite_com&amp;utm_medium=link&amp;utm_campaign=2023eslitebookstore_top10\" target=\"_blank\">☞點此進入迷誠品閱讀文章</a><br /></p><p><br /></p><p><b>【迷誠品編輯推薦】<br /><br />標題｜【2023誠品閱讀職人大賞】入圍名單揭曉！以職人專業視角，挖掘差點錯過的好書<br />撰文｜ 迷誠品內容中心</b><br /><br />隨著時間的推移，轉眼間來到2023年倒數的日子，回顧這一整年的歷程，周遭的人事物都悄悄有了變化，但唯一不變的是對閱讀的真心依舊存在。<br />近期釋出的2023年度「誠品閱讀職人大賞」4大獎項入圍名單，是匯聚千位誠品書店職人共同提名票選，以他們長年培養的專業視角與閱讀觀點，推薦年度最具代表性的圖書與作家，讓我們除了暢銷書榜外，還有更多元的選書指南可以參考。</p><p><a href=\"https://meet.eslite.com/tw/tc/article/202312270001?utm_source=eslite_com&amp;utm_medium=link&amp;utm_campaign=2024craftsman_list\" target=\"_blank\">☞點此進入迷誠品閱讀文章</a><br /></p>',10,0,'2026-03-17 18:08:12','2026-03-17 18:08:12','https://www.eslite.com/product/1001124182682324108006'),(22,'金剛經白話講座: 放下的人生修行','王思迅','9786267752111','如果出版','2025-07-28',600,'人文史哲','https://s.eslite.com/b2b/vendor/vendor175255691112320250715132151/mainCoverImage1_1475941.jpg','<p>看見內心，就能放下，走向自己真實的生命<br /><br />《金剛經》講的是心，<br />是佛陀告訴我們如何正確運用自己的心，<br />放下執著的般若智慧<br /><br />如果你開始在意該怎樣使用時間，開始想過好這一生，<br />想讓生命有意義、有價值，讓自己成為自己喜歡的樣子，<br />你就一定需要《金剛經》<br /><br />《易經白話講座》暢銷書作者王思迅新作，逐字逐句，與我們分享佛陀的體悟<br /><br /><br />•《金剛經》是引領人生修行的寶貴經典<br />生命中總有一個時刻，我們會開始真心希望自己變得更好，真心希望自己的生命變得更有意義，並且願意在這件事情上付出努力，這時我們就已開始踏上了人生修行的旅途。<br />在我們提升自我的道路上，《金剛經》能提供我們最簡便、最直接，也最有效的方法。<br /><br />•正確地觀看我們自己的心，就是般若智慧<br />我們的心，喜歡認定事物是這樣的，或那樣的。這個認定，會逐漸強烈，變成難以改變的傾向，然後控制我們的頭腦與身體，讓我們依循這個認定而去行為與反應。<br />如果我們能夠從這個認定的傾向中掙脫出來，那我們就能脫困，不會被控制，也能得到自由。透過自我覺察，知道自己的本心，放下自己原有的傾向，這種能力，就是我們內心智慧的顯現，就是般若智慧。<br /><br />•放下，就能斷除執念，走向自己真實的生命<br />《金剛經》告訴我們，只要能放下執著，我們不但可以不隨因果業力而流轉，同時也可以體會到生命真實的意義。當我們慢慢學會「放下」，我們的世界就會越來越明澈，越來越清楚，我們的人生道路也會越來越明確，越來越篤定。最後，我們會知道自己應該過怎樣的生活，成為怎樣的人，在怎樣的事情上努力，並在「宗教性」的實踐上，圓滿我們的一生。<br /><br />•《金剛經》給我們的是究竟圓滿的智慧<br />用置身事物之上的角度觀看自己、觀看他人、觀看環境、觀看時空的變化，也觀看自己思維中的一切。觀看之後再如實地放下，這就是《金剛經》要告訴 我們的智慧。它能讓我們對周遭世界多一分包容，也讓我們多一分洞見，反觀自照，成為更好的自己。這就是智慧之上的智慧，究竟圓滿的智慧。</p><p><br /></p><p><b>EP481｜王思迅與《金剛經白話講座》：不信佛，也能與金剛經結緣｜今天讀什麼</b></p><p><iframe data-testid=\"embed-iframe\" style=\"border-radius:12px\" src=\"https://open.spotify.com/embed/episode/588mERJJGRx5G9dtPHiOnK?utm_source=generator\" width=\"100%\" height=\"152\" frameborder=\"0\" allowfullscreen=\"\" allow=\"autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture\" loading=\"lazy\"></iframe></p>',10,0,'2026-03-17 18:08:22','2026-03-17 18:08:22','https://www.eslite.com/product/10012117772682949728009'),(23,'簡明台灣人四百年史 (圖文精華版)','史明','9789578018273','前衛出版社','2017-11-01',500,'人文史哲','https://s.eslite.com/Upload/Product/201710/o/636440854303727500.jpg','<div><b>◎史明親自改寫，親筆繪畫，認識台灣史最佳入門。\n<br>◎第一本站在被統治的台灣大眾立場的台灣史。\n<br>◎原著百萬字精華濃縮，再收錄一百餘幅史明親繪漫畫。\n<br>◎本書另收錄史明首次曝光的文章〈謝雪紅的慘境〉。\n</b><br>\n<br>1.	史明親自改寫的《台灣人四百年史》濃縮本，更附上史明手繪的一百餘幅漫畫，圖文相輔，認識台灣史的最佳入門。\n<br>\n<br>2.	跳脫歷代官方史書的統治者觀點，第一本站在被統治的台灣大眾的立場，詳述台灣人祖先遭受的重重壓迫與剝削，以及所掀起的一波波可歌可泣的起義革命。\n<br>\n<br>3.	擺脫封建落伍的血統羈絆，第一本採用現代思潮的民族觀點，解析台灣人祖先歷經四百年的反抗與開拓，因著共同的政治命運與經濟利益，如何一步步形成全新的台灣民族。\n<br>\n<br>4.	正氣十足的史家筆法，歷史上的三腳仔、半山、靠山等趨炎附勢之徒，難逃不假辭色的嚴詞批判，就算對林獻堂、蔣渭水、謝雪紅等抗日要角，同樣有相當深刻犀利的褒貶。\n<br>\n<br><br>《台灣人四百年史》，自1962年日文版出版以來，至2014年最新漢文檢定版，已擴增為堂堂三大冊，一千九百餘頁。這部不朽鉅著，是第一本站在被殖民、被剝削、被壓榨、被屠殺的台灣人立場，寫出「台灣民族」的歷史發展及「台灣人意識」的形成過程的著作，截然不同於一般的台灣史書籍，具有強烈的批判性及實踐性，因而問世時間越久，越是確立其無與倫比的經典地位。\n<br><br>鑒於這部名著內容過於廣博詳盡，許多有心接觸者無法深入堂奧，史明曾親自將四百年史改寫濃縮為《台灣不是中國的一部分》（1992），並動筆把四百年史圖像化，畫成一百餘幅漫畫的《漫畫台灣人四百年史》（1994）。多年來，這兩書深受讀者歡迎，被視為建構台灣史觀的最佳入門。\n<br><br>值此兩書再版之際，本社徵得史明同意，將兩書合為一冊，圖文相輔，咸信更能深化台灣史的理解。此外，本書再選粹《台灣人四百年史》中深具實踐力道的段落，共計兩萬餘字。這些新增文字，一方面橫的剖析台灣的社會結構，究明台灣各階層面對既有體制懷有何種心態與傾向，另一方面縱的研究歷代台灣人反抗外來殖民統治的具體經過，探究反抗為何失敗，反抗者犯了何種缺失等問題。\n<br><br>不管是初步的台灣史讀者或是近來風起雲湧的反體制運動者，皆可從本書汲取史明研究台灣歷史得出的深刻智慧，做為認識台灣現實或是改變台灣現實不可或缺的知識基礎。\n<br></div>',10,0,'2026-03-17 18:08:26','2026-03-17 18:08:26','https://www.eslite.com/product/1001116222632167'),(24,'新譯楞嚴經 (第3版)','賴永海/ 楊維中/ 注譯','9789571477664','三民書局股份有限公司','2024-04-17',410,'人文史哲','https://s.eslite.com/b2b/vendor/vendor171211693486520240403120218/mainCoverImage1_1240175.jpg','<p>「欲知佛境界，當讀華嚴；欲知佛智慧，要讀楞嚴。」《楞嚴經》是一部大乘佛教的單譯經，素有佛教全書之稱。經中說明宇宙原理、人生真相，展示世界、眾生業果相續的主要原因，以及教導眾生返妄歸真、覺悟成佛的方法；尤其經中有關觀世音菩薩的說法，在佛教信眾之中，影響至為深遠。本書以文學及佛學角度譯注《楞嚴經》，為坊間所少見，研讀佛教經典者切不可錯過。</p>',10,0,'2026-03-17 18:08:31','2026-03-17 18:08:31','https://www.eslite.com/product/10012010162682552936006'),(25,'快樂來自八正道: 斷除渴愛與無明, 活出自在、喜樂與平衡','德寶法師','9786267785188','橡實文化','2025-12-17',450,'人文史哲','https://s.eslite.com/b2b/vendor/vendor176485448249420251204212122/mainCoverImage1_1566055.jpg','<html><head></head><body><p>對自己的快樂負起責任！<br>若要踏上這趟旅程，需要向內連結自己的心。<br><br>德寶法師以平易近人的表達方式，<br>從禪修實踐的角度解說八正道。<br><br>唯有認出真正的快樂，行於中道，<br>才能獲得心的安穩與智慧，徹底解脫人生的痛苦。<br><br>真正的快樂來自斷除「渴愛」，但要單憑意志力來消滅渴愛並不可行，因此，佛陀有更好的作法，亦即「漸次修習八正道」。<br><br>佛陀以幫助人們開發初階正見（第一步）與正思惟（第二步）來展開教學。這些心理技巧幫助我們分辨道德與不道德的思想與行為，以及分辨善行與傷害、糾纏我們的行為。<br><br>當我們修習正確心態時，便可開始將逐步提升的知見用在正語（第三步）、正業（第四步）與正命（第五步）上，這些實際的善戒行將使我們的心趨向調柔、無礙、喜悅與淨信。由於惡行的干擾開始消退，「定」乃得以生起。<br><br>定有三個步驟。第一是正精進（第六步），它將心集中在解脫道的其餘各步上，這種精進在禪坐妄念紛飛時尤其需要。其次是正念（第七步），要想擁有正念，必須在每一剎那都有一些善定才行，這樣心才能持續接觸變化的諸境。正定（第八步）允許我們把心無間斷地集中在一個對象或觀念上，因為它是清淨心，無貪與無瞋，所以能帶給我們深入觀察實相所需的心理強度。<br><br>雖然佛陀的八正道是由一連串相續的階段組成，但它的運作更像螺旋狀，每一步都深化與加強其他各步。在螺旋之道的每一個轉折，你都對自己的身、口、意行更加負責。<br><br>本書的精華，在於作者將八正道從初學到開悟前的所有相關重點，都以禪修實踐的角度解說，不僅告訴你，快樂的內在生活「八正道」是什麼而已，更重要的是教你如何將八正道實際運用在日常生活的各個面向。<br><br>此外，作者以深厚的佛教學養和豐富的禪修指導經驗，對於每個道支可能產生的誤解或偏見，都加以精闢解說辯證。對資深佛教學者而言，作者融合南傳教理的詮釋和貼近現代人的思考方式，令人耳目一新。<br><br>◎八正道的精髓<br>．正見──使我們了解因果，知道不善行將導致苦果，善行將導致樂果。<br><br>．正思惟──能幫助我們檢視日常生活中不健康的思惟模式，以放捨、慈愛與悲憫等善念，斷除執著、瞋恨與殘酷等惡念。<br><br>．正語──幫助我們斷除妄語、兩舌、惡口與綺語等說話的壞習慣，以真實、向上提升、和善且中肯的語言，帶來和諧的快樂。<br><br>．正業──教我們遵守符合道德原則的五戒，避免殘酷與暴力循環，並且布施與悲憫他人，享受符合道德原則的快樂。<br><br>．正命──指從事不會妨礙心靈成長或造成他人傷害的工作，帶來利益自他的快樂。<br><br>．正精進──用於防止未生的惡法、斷除已生的惡法、修習未生的善法、維持已生的善法上，為我們帶來斷惡修善的快樂。<br><br>．正念──是時時刻刻注意當下，保持覺知，以內在的慧眼發現一切事物與眾生皆依因緣而存在，沒有什麼可執著或憎惡。<br><br>．正定──幫助我們突破這些對象的表象，清楚認知它們的無常、苦與無我，那麼我們的貪、瞋、癡煩惱都將永遠消失，達到覺悟的究竟快樂。<br><br>【各界推薦】<br>．德寶法師有著迷人的語調與平易近人的表達方式，當他鮮活地呈現佛陀的覺悟地圖──八正道時，很難不令人喜歡。──《香巴拉太陽報》（Shambhala Sun）<br><br>．有「老師之師」美譽的德寶法師，深入佛陀最深奧的教法──八正道，以簡明的語言提供修習正念的具體忠告。──《那普拉評論》（NAPRA Review）<br><br>．法師使用一種美好而豐富多元的說故事風格來闡明他的教法。它反映出一個獻身於解脫之道的行者的溫柔與慈悲。──《求索之心》（Inquiring Mind）<br><br>．德寶法師擅長以適合當代人的語氣，表達他在教法上清晰聰敏的洞察，本書是深入淺出的佛教讀物典範。──《三輪：佛教評論》（Tricycle: The Buddhist Review）<br><br>．這是一本以一種直接與令人信服的方式撰寫而成的佛教入門書，充滿放諸四海皆準的智慧。──《前言雜誌》（Foreword Magazine）<br><br>．對真正有志於安樂之道者來說，德寶法師的美妙新書是實用且貼切的指導。──雪倫．薩爾茲堡（Sharon Salzberg），著有《慈愛：革命性的喜悅藝術》（Lovingkindness: The Revolutionary Art of Happiness）<br><br>．清晰且簡單明瞭，讀者只會覺得過快樂的生活竟是如此可行且實際。──約瑟夫．葛斯汀（Joseph Goldstein），著有《觀禪──解脫的修行》（Insight Meditation: The Practice of Freedom）<br><br>（原書名：《快樂來自八正道》）</p></body></html>',10,0,'2026-03-17 18:08:34','2026-03-17 18:08:34','https://www.eslite.com/product/10012117772683052811008'),(26,'你怎麼能不愛台灣棒球? 台灣棒球完全保存MOOK','有理編輯部','9786267811498','有理文化有限公司','2026-03-04',480,'人文史哲','https://s.eslite.com/b2b/vendor/vendor177073342123020260210222341/mainCoverImage1_1602395.jpg','<p>比賽會結束，但我們對棒球的愛不會<br /> <br />上半場、中場休息、下半場，都是屬於你我的棒球人生。<br /><br />★第一本從球迷視角回望台灣百年棒球文化的Mook<br />★百年棒球史 × 正港的台灣棒球文化 × 跨世代球迷記憶，一次收錄！<br /><br />這不是一本只談歷史、比賽勝負的棒球書，而是一場從百年前開打、至今仍在延長賽的台灣棒球夢。從少年站上紅土的棒球夢想，到球迷在看台上吶喊應援的聲音；從九○年代職棒的狂熱與低谷，到今天重新湧入球場的人潮──我們為什麼會如此熱愛棒球？<br /><br />本期《故事別冊》將台灣百年棒球文化以一場「棒球比賽」為結構，全書分成上半場、中場休息與下半場，以球迷最熟悉的節奏，重新走進台灣棒球的百年現場：<br /><br />●上半場：從仰慕棒球英雄的台灣少年出發，看這些少年們，如何一棒接一棒，將對棒球的熱愛傳遞下去，為這場百年比賽揭開序幕；而那些耳熟能詳的多聲道棒球術語，其中又隱藏著哪些台灣棒球的混血身世 <br /><br />●中場休息：從台北市立棒球場的第一場中職比賽說起，看棒球如何成為台灣人生活中不可或缺的一部分；隨著網路時代的來臨，PTT鄉民構築出自台灣土地長出來的棒球宇宙，凝聚了一整個世代棒球迷的共同記憶；而那些陪伴許多人成長的漫畫、歌曲、應援口號，如何拼貼出屬於九○年代的棒球記憶？<br /><br />●下半場：走過五次簽賭風暴的台灣棒球如何重新再站起來？讓我們將場景交給如今正在棒球產業中努力的人們──球員周思齊、會長蔡其昌、應援團長勛雞，他們既是熱愛棒球的球迷，也是親身投入棒球產業的行動者；去球場看球賽向來是台灣人重要的休閒娛樂，如今，進球場變成一件更「忙」的事──不只要跟著啦啦隊熱情應援，還要注重球場穿搭、品嘗球場美食，台灣棒球賽的熱情與活力，讓來球場看球如同來到遊樂場；而台灣棒球能談的遠不只如此，還有把數據與熱血放在同一張桌上的運動科學，以及仍在努力被看見的台灣女子棒球。<br /><br />這是一本寫給老球迷的回憶Mook，也是一封給新球迷的入坑指南。只要還有球員在場上、只要還有球迷願意走進球場、為球賽熱情應援──台灣棒球，就永遠是一場尚未結束的比賽。<br /><br />扎根台灣土壤的棒球，是一種跨越世代的情感連結<br />無論你的球迷資歷或年齡世代，都能從中找到共鳴點，<br /> <br />所以，你怎麼能不愛台灣棒球？<br /><br />本書特色<br />●<b>一本書，看懂台灣百年棒球</b>●<br />\n本書從球迷的角度出發，將台灣百年棒球史，拆解成一場完整的比賽節奏：從日治時期的啟蒙、戰後的集體榮耀，到職棒時代的高峰與低谷，再到今日球場的重新熱鬧，用最貼近生活的方式，帶你一次讀懂台灣棒球。 <br />\n&nbsp;<br />\n<b>●不只歷史，更是你熟悉的棒球日常●<br />\n</b>收錄棒球術語、應援文化、戰歌、漫畫、球場美食與時尚風格，從觀眾席到球場中央，從比賽到生活，完整呈現棒球如何成為台灣人的日常娛樂與文化記憶。就算不是死忠球迷，也能輕鬆讀懂、快速入坑。 <br />\n&nbsp;<br />\n<b>●關鍵人物 × 熱門話題，一次到位●</b><br />\n專訪球員、中職會長、球評、應援團長與Podcast主持人，從不同視角理解棒球的現在與未來；同時直面中職的巔峰與低谷，誠實記錄那些改變台灣棒球走向的重要時刻；以及近年來正夯的運動科學、女子棒球議題。 <br />\n&nbsp;<br />\n<b>●給不同世代台灣棒球迷的完全保存Mook● <br />\n</b>無論是從三級棒球、業餘成棒、中職元年、國際賽就開始看球的老球迷──抑或是才剛開始喜歡棒球的新球迷，這本《你怎麼能不愛台灣棒球？》，都是你重新認識、再次愛上台灣棒球的入門指南。</p>',10,0,'2026-03-17 18:08:38','2026-03-17 18:08:38','https://www.eslite.com/product/10012043902683096342001'),(27,'90天靈修旅程: 活出美好 幫助你活出生命完全潛力!! (第2版)','約爾．歐斯汀','9789866202391','保羅文化出版有限公司','2023-01-10',400,'人文史哲','https://s.eslite.com/upload/product/o/2682321781004/20221230035902720441.jpg','<div>★ 源自蟬聯紐約時報暢銷榜第一名兩百餘週的《活出美好》！\r<br/>\r<br/>\r<br/>紐約時報暢銷排行第１名作者約爾．歐斯汀，邀請讀者以90天的靈程，淚發出無限的內在潛力！\r<br/> \r<br/>在《活出美好》一書中，約爾．歐斯汀使我們確認，要活出潛力是我們都可以辦得到的。他提到：「要擴大我們的視界，要了解我們所思所言的力量，並且要扭轉逆境，使其成為讓自己成長的機會。」\r<br/> \r<br/>在本書裡，作者幫助我們去擁抱上帝要我們享受的生活。透過作者90天激發性的思維、極具啟發性的信息，以及助益匪淺的的聖經節，將幫助我們堅定信心，信靠上帝，相信別人，也對自己有信心。藉著應用這些真理，我們將能夠超越一切障礙，進而活出健康、豐盛，並活在得勝之中。</div>',10,0,'2026-03-17 18:08:43','2026-03-17 18:08:43','https://www.eslite.com/product/1001137972682321781004'),(28,'狂野之旅: 外商在中國的25年, 從錢進中國到排外閉鎖的經濟簡史','楊思安','9786269284757','八旗文化','2026-02-04',450,'人文史哲','https://s.eslite.com/b2b/vendor/vendor176889714007120260120161900/mainCoverImage1_1590528.jpg','<html><head></head><body><p>全球唯一中文版，特別收錄寫給台灣讀者新序<br>★<br>中國的改革開放，只是一場戲<br>在他們眼中，外商不過是「會走路的錢包」！<br>踢爆「瑞幸咖啡」財報造假事件推手，長居25年寫下的中國現代經濟發展簡史<br>★<br>中國如何在短短四十餘年間，從一個貧困國家蛻變為全球第二大經濟體？<br>這場經濟奇蹟如今又是如何走向終結？<br>為何伴隨暴富而來的不是文明與開放，<br>而是愈加黑暗、限制愈深的社會與法治？<br>「事實證明，這一切不過是假象。」<br><br>「2008年的這場奧運讓我明白，中國從未發生體制上的轉變，1979年後所實行的資本主義，終究只是實驗一場，而且一旦被判定無用，便會馬上棄置不用。中共向資本家敞開大門賺夠了之後，就開始從國際事務中抽身。」——楊思安<br><br>為解讀中國經濟是如何急速崛起與目前正驟然衰落的軌跡，作者楊思安將我們帶回中國經濟改革的起點：從鄧小平接掌政權，1979年開始全面推行經濟與社會的連串改革，施行「對內改革、對外開放」、「解放思想、實事求是」等政策，將瀕臨死亡的中國經濟向西方資金與技術敞開大門之時說起。<br><br>楊思安在1985年初到北京，於當時中國文化部旗下外文出版社的《人民畫報》（China Pictorial）中，出任「外國專家」一職。當時的中國還是一個相當貧窮和思想落後的國家，政府機關體制極其呆板，工作毫無章法而效率低下，行動處處受限，就連結婚和出門旅遊這種事情都需要上級書面許可。在親眼目睹社會層級分明，低下階層人民所遭受的不公平待遇後，她對中國的社會主義徹底幻滅，進而意識到當時在北京的外國人，不過是動物園裡的奇珍異獸，各種特殊待遇只是把他們當成會走路的錢包。<br><br>後來與中國人結婚的楊思安，在中國生活與經商長達25年，親身經歷了中國經濟崛起的各個狂飆時期。本書以每十年的發展為分水嶺，從轟轟烈烈的1980年代一直寫到當今的經濟低迷，以獨立調查人員的敏銳筆觸記錄當中具標誌性的事件並揭露種種弊端，如：開放初期外資的洶湧而入與各地淘金熱、中國一些著名私營企業的崛起與衰落、紅色資本與紅色精英如何以權勢搜括鉅額財富、各種離奇中式騙局、荒誕的房地產泡沫與中國特有的山寨奇觀等，各種亂象的犀利程度使人不寒而慄。<br><br>在這本結合了深入觀察與精闢剖析中國現代經濟的《狂野之旅》中，見證這個國家如何由改革、崛起、腐敗到現今的衰竭，她追溯當中歷程並得出結論：所有曾經的承諾與變革，皆是幻象一場，中國正重返毛時代的貧困與孤立。共產中國只顧求生，虛與委蛇，西方卻深信不疑。隨著習近平崛起，資本主義實驗宣告終結。<br><br>「多年之後我才幡然醒悟，身為這場精裝大戲中的一角，我有多無知無畏。」——楊思安<br><br>作者訪談：「中國洋媳婦楊思安：中國改革開放只是演给外商的一場戲」（美國之音）<br>（https://www.voachinese.com/a/anne-stevenson-yang-s-wild-ride-in-china-20241001/7805892.html）</p></body></html>',10,0,'2026-03-17 18:08:49','2026-03-17 18:08:49','https://www.eslite.com/product/10012043902683082299005'),(29,'集章日本: 1940年臺灣商人蔡桑的旅行手帳','林雨新/ 陳力航','9786267727690','前衛出版社','2026-02-04',550,'人文史哲','https://s.eslite.com/b2b/newItem/2026/01/26/8985_182142704_831_mainCoverImage1.jpg','<html><head></head><body><table>\n <tbody><tr>\n  <td>\n  <p><b>——————————————</b></p>\n  <p><b>古早古早以前的打卡、限時動態<span></span></b></p>\n  <p><b>300</b><b>枚戳章的スタンプ蒐集日記</b><b></b></p>\n  <p><b>——————————————</b></p>\n  <p><b></b></p>\n  <p><b>★穿越時空，跟著大稻埕的蔡桑同遊日本——集章趣！</b></p>\n  <p><b>★七公尺長的スタンプ手帳，重回戰前的摩登時代！</b><b></b></p>\n  <p><b>★神社、車站、旅館、港口戳章齊聚──最豐富的戰前日本旅行集章錄！</b></p>\n  <p><b></b></p>\n  <p>門司\n  博多 雲仙 熊本\n  鹿兒島 宮崎 別府\n  下關 廣島 出雲\n  天橋立 大阪 京都\n  奈良 伊勢 名古屋\n  長野 日光 東京\n  目黑雅叙園 淺草 泉岳寺\n  鐮倉 熱海 神戶\n  臺灣神社</p>\n  <p><b></b></p>\n  <p><b>【本書案內】</b><b></b></p>\n  <p><b></b></p>\n  <p><b>蔡さん！何許人也！</b><b></b></p>\n  <p><b>翻開他的手帳，來場懷舊夢幻的</b><b>戳章紀行</b><b>！</b><b></b></p>\n  <p><b></b></p>\n  <p>1940年（昭和十五年），日本舉國歡騰慶祝「皇紀二千六百年」，全國上下沉浸在熱鬧的祭典氛圍中。在這歷史交會的時刻，一位來自臺北大稻埕的商人──蔡海坪（蔡桑），隨「臺灣總督府專賣局煙草內地視察團」踏上了為期一個月的東瀛紀行\n  。</p>\n  <p>這本罕見的「スタンプ蒐集日記」，是蔡桑留給後世最驚豔的時光禮物。他是非凡的集章旅人，將旅途中的點滴仔細封存，手帳中不僅蓋滿了各式印記，更貼入了行李吊牌、觀光門票、報紙剪報，甚至是餐廳的菜單。</p>\n  <p>藏品之外，本書另輔以詳盡的歷史背景導讀與視察團解說。它不只是一部個人蒐集日記，更是見證日治時期臺灣商人跨海視察的珍貴史料。翻開本書，您將與蔡桑一同穿越八十五年的時空，重回戰前昭和的日本，細細品味這趟夢幻的摩登紀行。</p>\n  <p><b></b></p>\n  <p><b>★各界好評推薦★</b></p>\n  <p><b>工頭堅</b><b>｜知名日本歷史旅遊YouTuber</b><b>旅行長</b></p>\n  <p><b>王可樂｜王可樂日語創辦人</b></p>\n  <p><b>呂紹理｜國立臺灣大學歷史學系教授</b></p>\n  <p><b>蔡錦堂</b><b>｜臺灣師範大學臺灣史研究所兼任教授</b></p>\n  <p><b>簡嫚書</b><b>｜演員</b></p>\n  <p><b>鍾淑敏｜中央研究院臺灣史研究所研究員兼所長</b></p>\n  <p><br></p>\n  </td>\n </tr>\n</tbody></table></body></html>',10,0,'2026-03-17 18:08:54','2026-03-17 18:08:54','https://www.eslite.com/product/10012012142683086469008'),(30,'球魂的軌跡: 日本野球誕生物語','朱宥任','9786267727652','前衛出版社','2026-02-04',500,'人文史哲','https://s.eslite.com/b2b/newItem/2026/01/26/8985_180936272_301_mainCoverImage1.jpg','<html><head></head><body><table>\n <tbody><tr>\n  <td>\n  <p><b>「為什麼日本棒球總是特別熱血？」<span></span></b></p>\n  <p><b>日本野球的前世今生，臺日球魂的歷史交會……<span></span></b></p>\n  <p><b>追尋在汗水淚水中，躍動激昂、閃耀不滅的意志神魂<span></span></b></p>\n  <p><b>一段民族熱血轟出的棒球傳奇，正式<span>Play Ball！</span></b></p>\n  <p><br></p>\n  <p>\n  </p><p><b>⚾</b><b>︎</b><b>棒球如何傳入日本？誰把<span>Baseball翻譯成「野球」？</span></b></p>\n  <p><b>⚾</b><b>︎</b><b>日本最早成立的「職棒隊伍」是哪一支？<span></span></b></p>\n  <h2><span>⚾</span><span>︎</span><span>奧義！「切支丹伴天連式魔球」的祕密……</span></h2>\n  <h2><span>⚾</span><span>︎</span><span>打球打到差點暴動？早稻田與慶應熱戰傳奇<span></span></span></h2>\n  <h2><span>⚾</span><span>︎</span><span>野球瘋過頭！「野球害毒論」正反大辯論<span></span></span></h2>\n  <h2><span>⚾</span><span>︎</span><span>只花四個月建成的「甲子園」為何成為高校野球聖地？<span></span></span></h2>\n  <h2><span>⚾</span><span>︎</span><span>日本野球的發展，竟然和鐵路事業有關？<span></span></span></h2>\n  <h2><span>⚾</span><span>︎</span><span>「野球王」貝比魯斯<span>v.s.澤村榮治的世紀對戰</span></span></h2>\n  <h2><span>⚾</span><span>︎</span><span>悲痛鎮魂……二戰後的日本野球如何重生？</span></h2>\n  \n  <p><br></p>\n  <p>日本野球的起源眾說紛紜，大致可追溯至1870年代「美國教師教導學生打棒球」的共同記憶。但有趣的是，日本野球的發展，似乎一開始就註定走上與美國不同的道路──特重品格、追求鍛鍊、強調榮譽，形成抗拒追求商業利益的精神性格。</p>\n  <p><br></p>\n  <p>是什麼樣的時代背景和文化脈絡，讓「熱血」成為日本野球的代名詞，培養出風靡全球的超級球員？臺灣棒球又如何受到日本野球的影響成為「國球」？「嘉農」吳明捷和其他赴日的臺灣球員到底有多強？只有了解日本、深入日臺野球的宿命連結，才能更明白日本野球的運動哲學。</p>\n  <p><br></p>\n  <p>作家、歷史研究者與棒球愛好者朱宥任，以淺顯易懂、生動活潑的筆觸，將豐富的日本野球史料與相關研究成果，重新梳理、編織為一本熱情動人的日本野球誕生記，並把文字與數據化為穿越時空、宛如親臨現場的賽事轉播。</p>\n  <p><br></p>\n  <p>不管你是一日球迷還是資深老粉，讓這本書帶你隨時加入朝聖日本野球聖地與名將生命史的野球之旅！</p>\n  <p><br></p>\n  <p><br></p>\n  <p><b>【專文推薦】<span></span></b></p>\n  <p>曾文誠／知名棒球評論家<span></span></p>\n  <p><br></p>\n  <p><b>【列名應援】<span></span></b></p>\n  <p>周思齊／前中信兄弟球員<span></span></p>\n  <p>蕭莉綾／山羊兄弟管理<span></span></p>\n  <p>李艾純／體育主播、《<span>MOMO瘋運動》製作人</span></p>\n  <p>王啟恩／《<span>Hito大聯盟》主持人</span></p>\n  <p>李秉昇／《<span>Hito大聯盟》主持人、主播</span></p>\n  <p>鄭凱駿／中華職棒數據網站「野球革命<span>Rebas」營運長</span></p>\n  <p>Danny &amp;阿<span>Yueh／《鍵盤球探》主持人</span></p>\n  <p>謝仕淵／成大歷史系副教授、棒球歷史學者<span></span></p>\n  <p>徐展元／體育主播<span></span></p>\n  <p>張瀞仁／作家、前運動經紀人<span></span></p>\n  <p>張尤金／棒球作家<span></span></p>\n  </td>\n </tr>\n</tbody></table></body></html>',10,0,'2026-03-17 18:09:00','2026-03-17 18:09:00','https://www.eslite.com/product/10012012142683086468001'),(31,'我有一个夢Guá ū tsi̍t-ê bāng (台文版)','馬丁．路德．金恩','9786267811412','有理文化有限公司','2026-01-21',270,'人文史哲','https://s.eslite.com/b2b/vendor/vendor176768741637920260106161655/mainCoverImage1_1582122.jpg','<p>朋友啊，請聽我講一句：這个絕望的深坑，咱就莫繼續浸咧內底。<br />就按呢，準做紲落來的路是轉彎踅角，我嘛是袂放捒我所向望的。我的這个向望，就深深釘根佇美國夢內底。<br /><br />「我有一個夢！」這句名言出自美國民權運動領袖馬丁．路德．金恩博士的著名演說，日後成為全球追求自由、平等與公義的永恆象徵。本書首次將這份經典演說，以台文完整翻譯，並附上英文原文，及華文譯文作為對照。<br /><br />透過經典著作的在地化，以及台灣插畫家對於經典內容的描繪，本書使金恩博士對於種族平等、非暴力抵抗和人類尊嚴的普世價值，與台灣人民在歷史上對民主自由的追求產生共鳴。人人都應享有平等的權利與尊嚴；它也鼓勵我們，即使在最艱困的時刻，也要堅持非暴力的信念，為建立一個更美好的社會而奮鬥。</p><p><br /></p><p>本書特色<br /><span style=\"font-size:0.875rem; display:inline !important;\">● 以台文譯介人類史上重要思想著作：首次以台文翻譯《我有一個夢》，讓這份對全球民主影響深遠的演講稿，能以台灣本土語言進行閱讀、學習與討論。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">● 思想與語言的雙重傳承：透過翻譯重要政治哲學著作，展現台語作為一種能夠承載複雜思想與概念的書寫語言，有助於其復振與推廣。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">● 普世價值的在地共鳴：宣言中的核心理念，如人民自決、反抗暴政與追求自由，與台灣人民在歷史上爭取民主與主體性的奮鬥經驗相互呼應。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">● 台灣插畫家的視覺詮釋：邀請台灣創作者為內頁繪製插圖，引導讀者以不同感官路徑進入文本，開啟更具層次與趣味性的思考。</span></p>',10,0,'2026-03-17 18:09:04','2026-03-17 18:09:04','https://www.eslite.com/product/10012043902683072794008'),(32,'怪奇邪教檔案錄: 或許我們都是追隨者 揭開全球30個邪教對人類的心理操弄','J. W. 奧克','9786267747568','馬可孛羅文化事業股份有限公司','2026-02-07',460,'人文史哲','https://s.eslite.com/b2b/newItem/2026/01/30/15138_200537577_114_mainCoverImage1.jpg','<p>必讀之作。——《出版人週刊》（Publishers Weekly）\n<br />\n<br /> \n<br />\n<br />奇異歷史專家暨愛倫坡獎獎得主  J. W. 奧克的震撼之作，\n<br />\n<br />一本收錄歷史上最臭名昭著、最大膽、最危險的三十個邪教組織的\n<br />\n<br />百科全書式著作\n<br />\n<br /> \n<br />\n<br />聰明正常的人怎麼可能會陷入極端邪教？\n<br />\n<br />或許是因為……\n<br />\n<br /> \n<br />\n<br />「人們加入的是社群，而不是邪教。」\n<br />\n<br /> \n<br />\n<br />「邪教」是個令人害怕的詞彙，就像「恐怖分子」、「痲瘋病」一樣，即使是在邪教中的人也不喜歡這個單詞。字典的定義也幾乎無法捕捉到這個詞對人所激起的恐懼和厭惡。\n<br />\n<br />許多邪教成員遇到的可怕結局往往是長期被洗腦的最後一步。從一個漫長的蜜月期開始，逐漸變得孤立和受到控制，最終所有逃生路線都被阻擋後，只會有悲劇發生。\n<br />\n<br />有些人會意識到不妙，並離開團體。但大部分在其中的人則意識得太遲，甚至有些人永遠沒有意識到自己已經進入了一個奇怪的宗教。\n<br />\n<br />事實上，你我都有可能是「邪教」的追隨者。\n<br />\n<br />儘管邪教可能帶來的恐懼、奇怪和危險，但「加入邪教」可能是一個人可以做的最人性化的\n<br />\n<br />事情之一。因為，我們都想屬於比自己更偉大的事物、被志同道合的人接受，我們也都想過上比現在更好的生活。\n<br />\n<br />因此，或許不是有意識地，但我們可能加入了一個新的團體，並認為會有更好的生活在等著我們，而這就是異端／虛假教派所提供的好處——友誼、對某一事業的奉獻、穩定和庇護。\n<br />\n<br />本書舉出歷史上和全球最臭名昭著的三十個邪教為例子，揭開他們魅力背後的對人類的心理操弄，以及如何設法在他們的信仰中捕捉到心靈脆弱的人。\n<br />\n<br />本書作者J. W. 奧克即將向各位揭開邪教的可怕吸引力，其中的信仰、歸屬感的絕望和信任的悲劇。\n<br />\n<br /> \n<br />\n<br />誠摯推薦\n<br />\n<br />邱炫元│政治大學社會學系副教授\n<br />\n<br />Hazel│《時間的女兒》Podcaster\n<br />\n<br />Yolanda│真實犯罪播客「罪癖Crimophilia」主持人\n<br />\n<br />榮忠豪│《暗黑森林》Podcast節目</p>',10,0,'2026-03-17 18:09:08','2026-03-17 18:09:08','https://www.eslite.com/product/10012013192683082092002'),(33,'搭建你的心靈療癒小屋: 你的心就是你的家, 找回內心平靜, 從十三個空間開啟的自助冥想練習 (彩繪版)','潔西卡．波士頓','9786267852279','日出出版','2026-01-28',520,'人文史哲','https://s.eslite.com/b2b/vendor/vendor176874517379120260118220616/mainCoverImage1_1589105.jpg','<p>問自己一個簡單的問題：<br />如果你此刻的感覺是一間房子，它看起來是什麼樣子？<br /><br />這是一本為初學者設計的冥想指南，邀請你踏上一段內在探索的旅程，將心靈視為一座「房子」──「你的家」。認知催眠治療師潔西卡．波士頓將透過你我熟悉的居家意象，搭配溫暖細膩的插圖，引導你進入不同的冥想概念、提示與身心練習。<br /><br />在這座心靈小屋中，每個空間都象徵著一種心理面向：「大門代表界限」「閣樓代表回憶」「臥室代表慈悲」──<br /><br />▌大門是家的第一道防線，只允許得到你同意、懂得尊重你（及對等互惠）的人入內。<br /><br />▌閣樓是儲藏你人生閱歷的寶庫──那裡是一個由回憶和情緒交織而成的宇宙。<br /><br />▌書房是把熱情和自律轉化成潛能的空間，這裡不光讓你揮灑熱情，更是需要你每天實踐自律的空間。<br /><br />▌浴室為你提供一段沉澱的時光，重整心緒的空間，讓你能不受干擾地反芻與吸收新的想法。<br /><br />▌廚房是提煉直覺、聽從本能的指示、運用創造力，將平凡的日常素材轉化為出色成品的空間。<br /><br />透過這些探索，你在這個「家」的各個空間中做了仔細的觀察，完成了練習，與自己討論與反思，還留下凝聚了能量的信物。你將修補裂縫、重新點燃內在的光芒，並清理那些不再適合的人事物。這本書幫助你將內在之家轉化為安全而充滿慈悲的庇護空間，重新連結真實的自我，讓所有空間再次和諧共鳴。<br /><br />書中的引導冥想練習包含：<br />▲身體動作與感官覺察<br />▲情緒釋放的呼吸法<br />▲漸進式放鬆技巧<br />▲部分整合練習<br />▲正念與扎根儀式<br />▲未來自我視覺化<br />▲圖像與情緒的次感官探索<br /><br />透過這些自助實作練習，將一步步帶領你回到自我療癒的心靈小屋，找到安定、接納與完整。<br /><br />如果你的身心靈可以隨時感覺像在家一樣，那不是很棒嗎？</p>',10,0,'2026-03-17 18:09:17','2026-03-17 18:09:17','https://www.eslite.com/product/10012117772683080703009'),(34,'生命中的一切: 漫畫西蒙波娃','茱莉亞．貝恩哈德/ 茱莉亞．科比克','9786267835098','衛城出版','2026-01-28',680,'人文史哲','https://s.eslite.com/b2b/vendor/vendor176837911120520260114162512/mainCoverImage1_1587329.jpg','<p>她讓哲學走出書本，讓女人走進歷史，<br />在她的生命裡，思想與愛她都毫不妥協。<br /><br />她的文字震撼時代，成就了一代女性主義經典，<br />但光環背後，是孤獨、愛與自由交錯的戰場。<br /><br />貝爾記者在按下門鈴之前，緊張得喘不過氣。在門的另一端，是轟動法國社會、開創當代女性主義的思想家，西蒙．波娃。她聽聞西蒙．波娃的各種事蹟，查找過無數輿論批評，卻沒想過在門的另一頭等她的，卻是一名寂寞的老太太。<br /><br />出身巴黎沒落家庭的西蒙．波娃，自青少年時期起便自覺格格不入。不同於她的同儕，她不願做個家庭主婦，當時的社會卻不看好女性讀書學習，被困在傳統思想中的她，只好不斷探詢生命存在的意義。在索邦求學、與沙特並肩切磋的經歷，幾乎改變了西蒙．波娃的一生。1949年，她以《第二性》正面拆解「女人」的社會建構，激起歐洲輿論海嘯。此後，她投身政治與女性主義運動，從阿爾及利亞獨立到法國墮胎合法化，處處可見她的身影。<br /><br />然而，在這些傳奇的背後，卻是長年的孤獨與自我懷疑。西蒙．波娃在愛與思想之中拉扯，因飽受批評而困頓。她渴望思想的純粹，也渴望被理解的溫度；她寫下《第二性》揭露女性的處境，卻在私人書信中坦白自己仍無法完全擺脫依附的痛苦。隨著貝爾記者的訪談，我們可以看到一個偉大思想家曾經的掙扎與依戀──正是這份渴望，成就了一代思想家。<br /><br />她的一生，不是為了成為誰的偶像，而是為了讓所有女人都能成為自己。</p>',10,0,'2026-03-17 18:09:21','2026-03-17 18:09:21','https://www.eslite.com/product/10012043902683078520007'),(35,'周博教你高效閱讀做筆記: 一本搞懂如何讀得快、記得牢、寫得順!','周博 (周柏均)','9786267816080','畢方文化有限公司','2026-01-30',570,'人文史哲','https://s.eslite.com/b2b/newItem/2026/01/19/8141_165419164_433_mainCoverImage1.jpg','<html><head></head><body><p>教育界、產業界、公益單位，各界好評推薦<br>黃國書：社團法人知書文教公益協會理事長 / 西屯扶輪社社長<br>沈奕勳：板橋達特楊眼科院長（兒童近視控制專業）<br>林信德：奇美醫院復健部（兒童發展遲緩專業）<br>徐澤華：三本藝術人文事業有限公司董事長/知識創新扶輪社社長<br>馮昌國：hohoka好好教兒童財商/創業啟蒙教育創辦人<br>張瑞昌：軒然股份有限公司(越南)董事長 <br>.劉駿豪：得勝者文教創辦人<br>黃譯鋒：臺南市補習教育聯合會理事長<br><br>高效閱讀╳結構化筆記╳AI輔助學習<br>用對方法，讓學習不再需要用蠻力！<br><br>原本的我，習慣被動接受書籍知識，也不習慣複習筆記；直到遇見周老師之後，我學會進行主動式輸出，並適度做複習式筆記，以提升學習效率，進而讓大腦能夠形成長期記憶。其中，最令我嘆為觀止的，是課堂上周老師分享搭配AI工具的運用，讓原本枯燥乏味、難以理解的知識，轉化為富有故事性、條理分明且容易吸收的重點整理。<br>臺南一中學生 高振維<br><br>從前我一直以為學業成績等同於讀書時間，或習慣在書本上做上滿滿的筆記。上了第一志願之後，除了學業艱深外，又多了數不盡的報告與社團活動要規劃，沒有方法的讀書方式會事倍功半。周博老師啟發了我如何在有限的時間下最有效率地吸收知識，以及有架構的整理筆記，並配合一些AI等工具，讓讀書不再是一場盲打亂衝的硬仗！<br>臺南一中學生會長 王士誠<br><br>對我來說，讀書最大的問題不是讀不完，而是會一直關注時間。因為事情多，我特別在意安排與節奏，常常反覆看時間，反而更難專心。把時間交給番茄鐘之後，我能更安心投入讀書，這個方法到現在仍然在用。<br>臺南一中學生 彭宥鈞<br><br>從臺南一中到現在就讀成大電機系，我深刻體會到：聰明只是入場券，執行力與方法才是走得遠的關鍵。這正是老師當年輔導我時，給我最大的啟發。這本書不僅僅是教你讀書，更是教你如何管理自己。書中提到的高效閱讀與筆記技巧，正是當年老師手把手教我的觀念。<br>國立成功大學電機工程學系 楊晉維<br><br>《周博教你高校閱讀做筆記》新書座談會(更多詳細資訊請參閱畢方文化粉絲專頁）<br>臺中場<br>時間：2026年3月8日（星期日）PM2：30~3：30<br>地點：誠品書店臺中市政店（臺中市西屯區市政路480號5樓）<br>台南場<br>時間：2026年3月21日（星期六）PM4：30~6：00<br>地點：台南政大書城（台南市中西區西門路二段120號B1）<br><br></p></body></html>',10,0,'2026-03-17 18:09:25','2026-03-17 18:09:25','https://www.eslite.com/product/10012030392683082021002'),(36,'紀律長贏: 揭開清大校務基金操盤人風險控管與穩定獲利的策略','林哲群','9786264177443','遠見天下文化出版股份有限公司','2026-01-30',450,'商業財經','https://s.eslite.com/b2b/newItem/2026/01/15/9033_165009091_121_mainCoverImage1.jpg','<p><b>台灣第一本由大學基金操盤人</b></p><p><b>親自揭露「法人如何用紀律賺錢」的投資實戰書</b></p><p><b></b></p><p>這是一位操盤人橫跨十二年、在高度限制與市場風暴中淬鍊出的投資實戰全紀錄，林哲群，身為清華大學校務基金操盤人，從 2012 年起接手僅有 5,000 萬元的基金，在沒有制度、流程與先例可循的情況下，重新設計治理架構、風控機制與投資流程。</p><p>他不是在華爾街操作，而是在最受法規束縛的公立教育體系中，<b>用紀律和架構把一個基金做大</b>。十多年後，基金規模突破 48多億元，成為支持校務發展、研究投入與人才培育的重要財務來源。</p><p>他的成功不是靠押對一次行情，而是靠<b>在市場恐慌時仍能做正確的事：</b></p><p>面對 2015 年股災、2020 年疫情熔斷、2022 年升息衝擊，他用資產配置、再平衡與風險控管穿越波動，證明「穩健不是保守，而是能活下來的策略」。</p><p>同時，林哲群告訴讀者，清華基金能活下來、變大、被信任，靠的不是天才的判斷，而是靠一套讓人性退出、讓制度進場的架構。</p><p>在書中，他首次公開法人投資者的操作框架與決策心法：</p><p>．如何讓制度取代人性<br /><span style=\"font-size:0.875rem; display:inline !important;\">．如何在恐慌時仍能買進<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">．如何在看似安全時逐步降低風險<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">．如何用再平衡拉回策略軌道<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">．如何判斷風險比報酬重要的時刻</span></p><p>讀者將看見一位操盤人如何用紀律對抗市場噪音，並以<b>存活能力，而非收益欲望</b>作為投資的出發點。</p><p>更重要的是，他並不把這些策略鎖在法人領域，而是將其拆解為一般人也能落地的方法：</p><p>1. 用配置，而不是預測行情：建立能承受波動的資產配置。<br /><span style=\"font-size:0.875rem; display:inline !important;\">2. 用流程，而不是情緒反應：把投資變成流程，而不是心情。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">3. 用複利時間，打造資產成長：讓時間，而不是情緒，決定勝負。</span></p><p>林哲群認為：</p><p>投資不是追逐速度，而是鍛鍊節奏。<br /><span style=\"font-size:0.875rem; display:inline !important;\">能穿越周期的人，才配得上長期報酬。</span></p><p>這不是一本「教你賺快錢」的書，而是一本教你在金融市場中<b>穩定獲利、長期存活</b>的書。</p><p><b>專文推薦</b></p><p>國立清華大學校長　高為元<br /><span style=\"font-size:0.875rem; display:inline !important;\">玉山金控董事長　黃男州</span></p><p><b>專家推薦</b></p><p>「《紀律長贏》以清華永續基金為例，說明投資真正的關鍵不在判斷市場，而在建立可承受波動、可被傳承的治理架構。它提醒讀者：責任優先於報酬，時間才是最重要的盟友。適合重視永續、風險控管與長期價值的讀者。」<br /><span style=\"font-size:0.875rem; display:inline !important;\">——陳力俊，中研院院士、國立清華大學前校長</span></p><p>「這是一個發生在清華，十年同心、磨成一劍的故事。踏出正確的第一步至關重要；『厚德可以載物，自律能夠永續。概念如何落實為制度、價值如何與價格取捨』，是機構與個人發展基金的指引。」<br /><span style=\"font-size:0.875rem; display:inline !important;\">——賀陳弘，國立清華大學前校長、啟動基金者</span></p><p>「把校務基金當教材，這本書教你的不是賺快錢，而是怎麼在市場亂流中活得久、走得遠。」<br /><span style=\"font-size:0.875rem; display:inline !important;\">——游庭皓，財經直播主</span></p><p>「《紀律長贏》不只是清華校務基金過去10年的成果回顧，還是一套合理、簡單、易懂的思維心法，讓人理解『紀律』的重要性，並讓『時間』做你最好的朋友。」<br /><span style=\"font-size:0.875rem; display:inline !important;\">——楊士範，關鍵評論網共同創辦人</span></p><p>「本書詳述清大校務基金的法人投資原則和經驗，並提供投資人易於理解和執行的方法，是少數能同時談論法人和個人投資的實務之作，深具參考價值。」<br /><span style=\"font-size:0.875rem; display:inline !important;\">——劉炳麟，逢甲大學校務基金操盤人</span></p>',10,0,'2026-03-17 18:10:09','2026-03-17 18:10:09','https://www.eslite.com/product/10012030542683076169000'),(37,'99%的人輸在不會表達: 話說對了, 事就成了。公司裡該怎麼說話? 麻煩就沒了。','李勁','9789579164337','大是文化有限公司','2018-06-28',340,'商業財經','https://s.eslite.com/b2b/newItem/2025/06/20/1935_164448031_516_mainCoverImage1.jpg','<div>中國亞馬遜暢銷書，上榜長銷21個月<br /><br />◎不想被人呼來喚去，要怎麼不留痕跡的設界線？<br />◎你的建議被打槍，怎麼繞圈子說服？反駁上司，怎麼說不惹毛人？<br />◎忘了對方名字、說了蠢話、見了面會尷尬……這些場面你怎麼化解？<br />◎「不知道、你問別人吧、我不行耶、這麼一點事也……、完了完了……」<br />職場裡有八句話會害慘你，你要怎麼換個說法？<br />   <br />作者李勁是資深企劃編輯，工作就是花大把時間跟人說話，<br />逼得他必須熱衷於心理學與人際交往。他用自己的人生經驗終於搞懂： <br />一個人的成功，15％取決於專業知識，剩下的85％來自人際溝通，<br />但99％的人輸在不會表達。<br />       <br /> 他在書中詳細解釋各種說話技巧，涵蓋職場、商務談判、開會，以及與<br /> 家人、朋友、伴侶之間的溝通，你將學會：<br /> 如何能話說三分，但分量十足；何時該主動充分表達，否則冤沉海底。<br />             <br />◎你的內涵與能力，不能輸在不會表達。●放大音量，膽子會跟著大起來。對方主要是想聽內容，你是誰其實並不那麼重要。所以，與其擔心講錯話而小聲說，倒不如專注於自己應該說些什麼。●先練習眼神接觸，而非說話技術。這個微妙的動作會讓對方感受到：你是放鬆的，是有自信的，精神是集中的。不習慣眼神接觸怎麼辦？先找家人或朋友練習。◎先閱人，然後說到對方心裡去。●說話速度加快或變慢，洩露哪種心思變化：心有不滿的人，說話速度會不自覺放慢；那說話速度突然變快？聲音突然變小呢？對方如果誇張的點頭，別以為他非常贊同，其實他是聽不下去了……。●從他的話題，聽出他的為人：有人喜愛聊自己、有人則老愛探人隱私，這分別代表何種性格？愛談金錢和愛談學問的人，差別在哪裡？◎話說三分，點到為止更有分量。●提出異議但不惹毛對方的方式：先不要馬上說出反對意見，只要你表現出很猶豫、很遲疑、很為難，對方反而會主動讓你說出自己的想法。●要懂得讚美人。但是，讚美的話說太長，就矯情了：最好的讚美是傳遞別人說過的話：「她說你做事超有紀律，非常欣賞你。」讚美之詞不能太長，怎麼用四個字、三個字，甚至兩個字就讓對方開心？◎公司裡，怎麼說話的？●會做不如會說，所以，以下這些事你要主動說：及時告知主管自己的工作進度，該承擔的責任不推託、不該承擔的責任不沉默，還有，當同事當眾批評你時，怎麼辦？作者還要告訴你，在職場裡有八句話會害慘你，像是：「這個阿，我可不行」、「不知道，你問別人吧」、「真笨，我都說三次了」…….。無論是職場老鳥或菜鳥，這些話都會影響你的發展，你得換個說法。◎聯合推薦世紀奧美公關創辦人／丁菱娟知名講師、作家、主持人／謝文憲亞洲第一激勵達人／鄭匡宇／</div>',10,0,'2026-03-17 18:10:14','2026-03-17 18:10:14','https://www.eslite.com/product/1001191562686239'),(38,'做自己的生命設計師: 史丹佛最夯的生涯規畫課, 用設計思考重擬問題, 打造全新生命藍圖','比爾．柏內特/ 戴夫．埃文斯','9789862137505','大塊文化出版股份有限公司','2016-10-28',320,'商業財經','https://s.eslite.com/Upload/Product/201610/o/636126356186748750.jpg','<div><div style=\"text-align:center;\"><iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/763zGFj3CWw\" frameborder=\"0\" allowfullscreen=\"\"></iframe></div><div style=\"text-align:center;\"><b>自己的人生，自己設計！&nbsp;</b></div>\n<div style=\"text-align:center;\"><br /></div><div style=\"text-align:left;\">終於，有一本書要教我們如何打造人生，更貼切的說法是「設計」人生。&nbsp;</div><div style=\"text-align:left;\">任何年齡、任何人生階段都適用──&nbsp;</div>\n<div style=\"text-align:left;\"><br /></div><div style=\"text-align:left;\">◆歷經15年實證的課程（8年在柏克萊，7年在史丹佛）&nbsp;</div><div style=\"text-align:left;\">本書精鍊自史丹佛設計學院知名的生涯規畫課程，由兩名教授共同撰寫。歷經十幾年的實證，此課程的生命設計模式對於個人的改變相當有效，大幅降低焦慮感以及有關職涯、生命的錯誤迷思，能更有效地達到職業目標。作者教學經驗豐富，深知激勵人心的祕訣，將設計與生命觀點的共通性緊密串連。&nbsp;</div>\n<div style=\"text-align:left;\"><br /></div><div style=\"text-align:left;\">◆適用於各年齡層人士&nbsp;</div><div style=\"text-align:left;\">課程內容經過濃縮，適用於不同的生命情境，簡易、實行度高。不論是對二十、四十、六十歲的人，剛踏入社會、轉換跑道、中年轉職或屆臨退休的人士，在生命的不同階段都有啟發性跟實用性。&nbsp;</div>\n<div style=\"text-align:left;\"><br /></div><div style=\"text-align:left;\">◆輕鬆解決一生中最重要的課題&nbsp;</div><div style=\"text-align:left;\">在人的一生中，職涯成功與否、生命快不快樂，都是重要課題。然而，針對此課題，以及面臨生命走向的重大決定時，我們的教育系統幾乎沒提供相關的工具。本書用「設計思考」回答人生最具挑戰性的問題：「我這一生要做什麼？」展現在史丹佛開創、於矽谷發揚光大，嶄新又富創意的生命設計過程。&nbsp;</div>\n<div style=\"text-align:left;\"><br /></div><div style=\"text-align:left;\">◆矽谷頂尖設計團隊&nbsp;</div><div style=\"text-align:left;\">本書作者的設計作品包含蘋果「老鼠」、第一台消費性筆電、雷射印表機、星際大戰動作人物等。比爾是史丹佛設計系的執行主任，也是蘋果Powerbook的行銷主管。戴夫則是史丹佛生命設計實驗室的共同主任，也是全世界最大的跨國性互動娛樂軟體公司「美商藝電」（Electronic Arts）的創辦人之一。&nbsp;</div>\n<div style=\"text-align:left;\"><br /></div><div style=\"text-align:left;\">◎設計師也熱愛問題&nbsp;</div>\n<div style=\"text-align:left;\"><br /></div><div style=\"text-align:left;\">‧如何才能找到喜歡的工作？甚至是熱愛的工作？&nbsp;</div><div style=\"text-align:left;\">‧如何才能打造讓我過著美好生活的事業？&nbsp;</div><div style=\"text-align:left;\">‧如何平衡事業與家庭？&nbsp;</div><div style=\"text-align:left;\">‧如何改變世界？&nbsp;</div><div style=\"text-align:left;\">‧怎樣才能瘦到爆、性感，並且有錢到天怒人怨？&nbsp;</div>\n<div style=\"text-align:left;\"><br /></div><div style=\"text-align:left;\">◎生命設計的五種心態&nbsp;</div><div style=\"text-align:left;\">‧好奇心&nbsp;</div><div style=\"text-align:left;\">‧行動導向&nbsp;</div><div style=\"text-align:left;\">‧重擬問題&nbsp;</div><div style=\"text-align:left;\">‧覺察&nbsp;</div><div style=\"text-align:left;\">‧通力合作&nbsp;</div>\n<div style=\"text-align:left;\"><br /></div><div style=\"text-align:left;\">設計師靠著「設計思考」（design thinking）解決問題，帶來我們今日的世界。看一看辦公室，看一看家裡，手上那台平板、那支手機、坐著的那張椅子，生活中每一樣東西都源自設計，而每一個設計的起點，都是設計師或設計團隊想解決的問題。&nbsp;</div>\n<div style=\"text-align:left;\"><br /></div><div style=\"text-align:left;\">本書作者比爾‧柏內特（Bill Burnett）與戴夫‧埃文斯（Dave Evans）讓我們瞭解，如何透過設計思考，創造出有意義又快樂的人生。不管是誰，身處何方，現在或先前的工作是什麼，目前多老或多年輕，都可以藉著那些帶來世上美妙科技、產品、空間的設計思考，打造專屬於自己的事業與生活，活出圓滿、有趣、創意無限、生產力十足、永遠有驚喜等在前方的人生。</div></div><p><br /></p><p>職涯教練Grace如何看待職業倦怠？先從從拆解現況開始！｜今天讀什麼<br /></p><p><iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/La5Rq-o2hfs?si=Z-qH_yHecYTvLZJY\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen=\"\"></iframe><br /></p><p><br /></p><p><b>【迷誠品編輯推薦】<br /><br />標題｜職業倦怠怎麼辦？職涯教練Grace用2本書帶你找到原因與解方<br />撰文｜迷誠品內容中心</b><br /><br />大多人長期執行一項工作或任務，若沒有不斷產生新挑戰，或是出現許多問題需要處理，長期下來會逐漸失去工作的興趣，也開始想逃避、跳脫所處環境，這項行為稱之為職業倦怠。<br /> <br />那是什麼原因導致職業倦怠的呢？遇到職業倦怠又該如何消除內心的煩悶感，才不會在急於消除職業倦怠的狀況下做出錯誤的抉擇？此次邀請BetweenGos公司的創辦人Grace，同時也是職涯教練的她，用兩本書帶領我們認識職業倦怠的成因和調適妙方。<br /></p><p><a href=\"https://meet.eslite.com/videos/202407090001?utm_source=eslite_com&amp;utm_medium=link&amp;utm_campaign=2024_burnout\" target=\"_blank\">☞點此進入迷誠品閱讀文章</a><br /></p>',10,0,'2026-03-17 18:10:19','2026-03-17 18:10:19','https://www.eslite.com/product/1001129722549253'),(39,'財富傳承規劃新思維: 房產．保險．信託 實戰篇','朱家棟','9786269966295','Fun學創意生活廣場','2026-01-07',520,'商業財經','https://s.eslite.com/b2b/newItem/2025/12/08/19909_180502352_695_mainCoverImage1.jpg','<html><head></head><body><p>房地合一新制來了！別讓房產變遺憾！ ── 90%家庭傳承錯誤，導致十倍、百倍奉還！<br>「有愛無礙」的傳承祕笈！房產、保單、信託，用錯比不用更慘！<br>你的財富要留愛還是留債？從迷思到實戰，零基礎搞懂傳承三大工具<br><br>資深財富規劃專家朱家棟 老師歷經無數家庭諮詢、數百張案例推敲，傾注近一年心血，繼第一本書《遺產&amp;贈與稅的節稅新思維》後，隆重推出全新力作——《財富傳承規劃新思維—房產・保險・信託實戰篇》。<br><br>真正的財富傳承，不是有錢人的專利，而是每個家庭都必須面對的功課。本書正為了解決這個核心需求而誕生，專注於提供大眾最需要、卻最欠缺的傳承工具知識。<br><br>本書看點：💡解決家庭三大核心傳承痛點<br><br>1. 房地合一新制＋遺贈稅規劃<br>•	決策指南： 房產傳承，哪種方式最節稅、移轉速度最快？<br>•	比較分析： 自己買賣、贈與、繼承，如何評估利弊得失？<br>•	創造負債好處多： 如何透過正確創造負債做好完全資產規劃？<br>2. 保單如何晉升傳家工具？<br>•	配置解密： 要保人、被保人、受益人的最佳配置策略。<br>•	資產保護： 如何運用保單的特性，避免資產被強制執行。<br>•	金流安排： 如何利用保單，為家人安排行為能力喪失後的穩定金流。<br>3. 信託工具的多角度應用？<br>•	需求判斷： 到底哪些情況需要啟動信託？<br>•	情境設計： 買房、交稅、分財產、照顧年邁父母的信託規劃範例。<br>•	破除迷思： 將複雜的信託變成「人人看得懂、用得起」的家庭工具。<br><br>這是一本真正能用的「照表操課」工具書，用清晰的操作流程與實際表單，帶您深究家庭最常遇到的稅務盲點與個案的錯誤經驗，提供可以直接上手操作的資產配置建議。您不需要具備法律或稅務背景，也能有效避免高達90%的家庭傳承錯誤。<br><br>朱老師深信，傳承不是財務規模的問題，是家庭關係的問題。而本書提供的工具，正是讓家庭更平安、更有準備、更能彼此理解的關鍵。<br><br>誠摯推薦給： <br>♦ 想替父母做傳承規劃的人<br>♦ 擔心子女財務不穩、需要保護安排的家庭<br>♦ 正在買房、持有房產的人 <br>♦ 手上有保單、但不知道受益人如何設定的人 <br>♦ 想用信託保護家人、卻不知道從哪開始的人 <br>♦ 任何想讓家人更有保障的人<br><br>讓這本實戰工具篇，成為您家族傳承道路上的明燈，把愛，用最不會造成傷害的方式傳下去。</p></body></html>',10,0,'2026-03-17 18:10:28','2026-03-17 18:10:28','https://www.eslite.com/product/10012089252683055541001'),(40,'工作者的AI共智模式: 讓AI成為第二專長, 加速專業升級, 重塑競爭優勢','伊森．莫里克','9786267713662','天下雜誌股份有限公司','2026-03-12',500,'商業財經','https://s.eslite.com/b2b/newItem/2026/03/04/8141_084028906_846_mainCoverImage1.jpg','<html><head></head><body><p>AI即將全面接管任務的時代，人類工作者領先的關鍵<br>不在於使用的工具，而在協作的深度。<br><br>生成式AI滿三歲，你還只用AI翻譯、寫email、改履歷嗎？<br>一人獨角獸時代，你會成為擅長AI的CEO，還是被取代的人類工作者？<br>AI已經能寫程式、做簡報、發想創業計畫、甚至參與決策，當大家還在討論AI會如何取代人力，真正的領先者已經開始構建一套可持續升級的AI協作思考系統。<br><br>建立跨工具、跨情境、可持續升級的AI底層思維框架，<br>不論工具如何翻新，都能站上浪尖超速進步，不被淹沒。<br>本書作者伊森．莫里克是賓州大學華頓商學院教授，也是《時代》雜誌（TIME）評選AI百大最具影響力人物之一。他不僅是研究創新的學者，更是最前線的實踐者，2022年就開始在課堂與研究室中與學生深度實測AI的各種極限。他經營的電子報《One Useful Thing》與AI研究室，早已成為美國政府與全球企業領袖理解AI的首選指標。<br>莫里克同時理解商業競爭的現實，也深刻掌握學習與成長的本質，因此他能跳脫純技術視角，從「真正在職場存活並升級」的角度，告訴我們如何把這項顛覆性技術，轉化成最強隊友，用過去不可能的速度，提升實力與判斷力。<br>莫里克不談對AI的盲目樂觀與過度恐慌，選擇關注AI已經帶來的實務改變。即使全球在此刻停止開發模型，AI也早已深刻改變我們的工作、學習、與思考方式。莫里克認為，我們能否進步的關鍵，就在於不害怕AI、不低估AI，而是快速學會與這個像「外星智慧」的超級通用技術共事、共創。<br>掌握AI時代生存與升級的關鍵框架：<br>	認識「外星共同智慧」：AI不是傳統軟體，而是一種更接近人類、甚至像「外星心智」的對話夥伴。<br>	摸索「鋸齒狀前緣」： 揭開AI能力的隱形城牆，學習辨識哪些任務AI擅長，哪些會出錯，精準分工，創造最大成果。<br>	實踐「共同智慧」四原則： 從「事事邀請AI參與」到「假設現在的AI是最爛版本」，建立一套永不過時的協作準則。<br>	轉職「半人馬」與「半機器人」：掌握兩種最高效的工作模式，何時該與AI劃清界線，何時該深度融合？<br>	引爆「自動化創意」：AI是強大的連結機器，善用它的隨機性，打破思維慣性，產生超越人類平均水準的創新提案。<br>	重新定義工作（任務vs. 職位）：學習將工作拆解為不同任務，將時間留給高價值決策。<br>	利用AI進行「刻意練習」：讓AI成為你的專業教練，提供即時回饋與高強度訓練，縮短從新手到專家的漫長路徑。<br>	洞見「四種未來劇本」：從技術停滯到超級AI的誕生，提前為各種可能的科技走向作好心理與策略準備。<br>在這個陌生卻無法回頭的AI時代，找到人類真正不可取代的位置與能力。<br>這本書將是你面對快速變動的未來時，最清晰的能力升級指南。<br><br>國際媒體與領域專家 一致強力推薦<br>程世嘉　iKala共同創辦人暨董事長 <br>安琪拉・達克沃斯（Angela Duckworth），《恆毅力》作者<br>艾瑞克・霍維茲（Eric Horvitz），微軟首席科學家<br>里德・霍夫曼（Reid Hoffman），LinkedIn 與 Inflection AI 共同創辦人<br>丹尼爾・品克（Daniel H. Pink），暢銷作者<br>吉姆・M・席特林（Jim M. Citrin），高階獵才公司史賓沙（Spencer Stuart）執行長<br><br>「一部紮實易懂的解析之作。」<br>——《華爾街日報》（The Wall Street Journal）<br>「一本犀利又帶著幽默感的指南，教你如何充分運用生成式AI。莫里克身體力行，實踐他所主張的『邀請AI一起上桌』，並親自做了許多實驗，探索AI的創造力與解題能力。」<br>——安德魯・希爾（Andrew Hill），《金融時報》（The Financial Times）<br>「帶你穿越AI迷宮的重要指南；內容權威、可信，毫無艱澀的科技術語。」<br>——《科克斯書評》（Kirkus）<br>「生成式 AI有了一位『先知』，他的名字叫伊森・莫里克。幸運的是，這位先知寫出了一本清晰、精煉、極度實用的指南，帶領我們理解這場急速發生的革命。這是我所知道，關於生成式AI的原理、應用與倫理，最出色的一本書。」<br>——安琪拉・達克沃斯（Angela Duckworth），《恆毅力》作者<br>「莫里克一直走在探索AI能力的第一線。他清楚而精準地引導讀者理解AI的最新進展，並提供深具洞見的分析。這本書內容全面，是認識當前趨勢與未來發展的重要資源。我推薦給所有想深化對AI理解的人。」<br>——艾瑞克・霍維茲（Eric Horvitz），微軟首席科學家<br>「在當今AI意見紛雜、充滿雜音的時代，莫里克以理性、前瞻、實證的觀點脫穎而出，成為理解AI對工作與教育影響的最重要聲音。任何想獲得實用知識、理解即將到來巨大變革的人，都應該現在就讀這本洞見深刻的書。」<br>——里德・霍夫曼（Reid Hoffman），LinkedIn 與 Inflection AI 共同創辦人<br>「精彩捕捉了人類與AI關係正在快速演變的本質。莫里克以清晰的解說與具體案例，展示我們如何運用這項驚人的技術力量，打造更聰明、更具人性的未來。」<br>——丹尼爾・品克（Daniel H. Pink），暢銷作者<br>「一趟改變領導者思維的旅程，也是所有掌舵者必讀的重磅新書。莫里克的洞察能幫助企業 CEO與領導者，充分發揮AI作為組織能力放大器的巨大力量。精彩、權威、極具教育性。」<br>——吉姆・M・席特林（Jim M. Citrin），高階獵才公司史賓沙（Spencer Stuart）執行長<br></p></body></html>',10,0,'2026-03-17 18:10:32','2026-03-17 18:10:32','https://www.eslite.com/product/10012030392683104427003'),(41,'說故事的力量: 解決問題、發揮影響力的最佳工具, 微軟、NASA、華府智庫爭相學習 (長銷25周年紀念版)','安奈特．西蒙斯','9786267624562','樂金文化','2026-01-09',450,'商業財經','https://s.eslite.com/b2b/vendor/vendor176656391340920251224161155/mainCoverImage1_1577773.jpg','<html><head></head><body><p>本書簡介<br>【長銷25周年紀念版】<br>第一本將故事運用在商業場域的作品<br>世界級故事大師安奈特．西蒙斯成名作<br>微軟、NASA、花旗銀行、時代雜誌、華府智庫爭相學習<br>一本你需要的書，也是一本全世界迫切需要的書！<br><br>　　很多商業書都告訴我們，只要有具體的事實、數據，就能說服別人。<br>　　但其實不然。<br>　　不相信嗎？<br>　　看看賈伯斯怎麼說：「世上最強大的人，是說故事的人。」<br><br>　　──道理只能贏得辯論，故事卻能收服人心！──<br><br>　　本書作者安奈特．西蒙斯，是首位將「故事」概念運用於商務世界的先鋒，告訴我們如果想成功激勵、說服、影響他人，解決問題，有件很重要卻一直被忽略的事：說故事。<br><br>    說故事是一種思維，也是一種技巧。<br><br>　　◎為何「說故事」是解決問題、發揮影響力的最佳工具？<br>　　故事是人類歷史上最古老的影響力工具，也是最有說服力的溝通技術。<br>　　一個好故事，打動的是人心，分享的是經驗，讓人不自覺被牽動。<br>　　這是任何數據或具體事情無法取代的，<br>　　更重要的是，它是每個人都學得會的技能！<br><br>　　◎怎麼「說」故事？<br>　　作者認為，任何尋求影響他人的人，首先都必須找到屬於自己的故事，然後學會如何成功的說出故事。她開創性的提出商界溝通中常用的六種故事，並詳細闡述在何種情況下、如何講述這些故事。<br><br>　　說服別人之前，必須先設想別人怎麼看你！人們會想，「你是誰？」「你為什麼在這裡跟我說話？」<br>　　如果要影響初次見面的人，你必須學會說關於這兩個問題的故事：<br><br>　　「我是誰？」故事：告訴聽眾，哪些經歷造就今天的你。<br>　　「我為什麼在這裡」故事：開誠布公，向聽眾坦承自己的意圖。<br><br>　　這兩個故事，重點在於「取得信任」。要影響陌生人，你需要說「取得信任」的故事。<br>　　如果你想影響身邊的人，例如同事或下屬或朋友，另外四種故事：<br><br>　　「願景」故事：激發人們對未來的憧憬，克服當下的挫折和沮喪。<br>　　「教誨」故事：啟發他人思考如何以最佳方式做一件事。<br>　　「現行價值」故事：展現你的價值觀，而不是告訴他人應該怎麼做。<br>　　「我知道你在想什麼」故事：消除疑慮，取得信任。<br><br>　　以上四種故事，重點在於「激勵、啟發與引發共鳴」。要影響周遭的人，你需要說「引發共鳴」的故事。<br><br>　　◎你的六種故事在哪裡？<br>某種意義上，故事就在你的生活之中。你每天都在講故事。<br>本書舉出超過一百個包括成功影響人心的故事案例，無論你是一個尋求創投資金的新創業者，試圖談成一筆生意的業務，主持公司改組方案的專案經理，或是為公共議題發聲的主導人，你都必須說出一個好故事。透過這些案例，搭配你的生活或工作，找出屬於自己的六種故事。<br><br>最後作者提醒……<br>說故事，但不是假故事，為說好故事而捏造事實，最終會失去人心。<br><br>把故事說好，將讓你的聽眾與你的訴求、觀念、情感產生共鳴，最後得到任何你想達成的結果。<br>透過故事，我們不僅可以影響別人，你也將成為一位更有效率的溝通者。<br>最終，最好的故事取勝。</p></body></html>',10,0,'2026-03-17 18:10:37','2026-03-17 18:10:37','https://www.eslite.com/product/10012125242683066401004'),(42,'這輩子賺多少才夠?: 行動清單×10張表格逆轉勝! 成為自己的富一代','Will 黃士豪','9786263583238','三采文化股份有限公司','2024-04-26',480,'商業財經','https://s.eslite.com/b2b/newItem/2024/04/12/177_161037071_896_mainCoverImage1.jpg','<p><iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/p3avR17dyaM?si=LG4met50wUDDQPYm\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen=\"\"></iframe></p><p><br /></p><p>你和富的距離差了個行動！<br />幫助十萬人財富增長的教練黃士豪<br />以理性財務思維 打造脫貧致富體質<br /><br />▂▃▄別讓現在決定你的未來▄▃▂<br />從負債3000萬到資產破億的CEO<br />打造人生全拿的FIRE財務系統<br />【QR Code致富下載】<br />行動清單×10張表格<br /> <br /><br />只靠一份薪水過活的人<br />和玩六合彩的賭徒沒兩樣<br /><br />這是你的煩惱嗎？<br />‧顧不了現在更遑論未來？<br />‧收入不錯卻也在燃燒⽣命？<br />‧想追夢但被現實壓得追不動？<br />‧想早點退休，再拚幾年就好？<br />‧為了孩子的未來，卻錯過他的現在？<br /> <br /> <br />▊你跟錢的關係，還好嗎？<br />想像一下你跟父母、朋友、兄弟姐妹、另一半的關係，關係的建立來自於每一次接觸，你對他們做了什麼，他們對你做了什麼。<br />跟錢的關係也一樣。每次碰到錢，你都做了些什麼？想到錢，你的情緒如何？你如何與別人談論錢？<br />這就是你跟錢的關係！<br /> <br />▊理想生活需要多少錢？<br />大多數人都為了追求理想生活而努力工作，但被問：「你理想的生活需要多少錢？」大家就沉默了。<br />到底你的理想生活是什麼樣子？需要多少錢？可能因為答不出來，解答就變成「別想那麼多，先好好工作再說」的鴕鳥心態。<br />用目前退休人口的平均開銷，每個月2萬元來看，假設35年後退休，退休後還有20年壽命，通貨膨脹率3%，那麼退休時每個月超過5萬收入，也未必能過上現在2萬元的生活品質。<br />這本書將推翻所有你學過的金錢知識，重新定義財富的價值，擺脫對「有錢」的過度執著、對「窮困」的過度恐懼，讓你跟金錢的關係逐步恢復到健康狀態。<br />●這個世界的財富規則，不是努力存錢就好！<br />●別管你會什麼，更重要的是你想要達到什麼！<br />●你希望用錢換到什麼？你又用什麼來換錢？<br /> <br />黃士豪，GoodWhale共同創辦人暨執行長，當家人欠債三千萬，他只能帶刀上門找黑道，剁手宣誓必定還清。從理債到理財，他學會理性計算的系統化投資法，讓身價破億。<br /> <br />┏･━･━･━･━･━･━･━･┓<br />這一本書能幫你逆轉財務思維<br />行動清單×10張表格<br />月存3000，邁向FIRE！<br />┗･━･━･━･━･━･━･━･┛<br /> <br />逆向從「想要的人生」啟動<br />夢想倉庫→人生願景→拆解財務目標→財富增長策略→追蹤財務儀表板<br /><br />逼死英雄好漢的不是負債總額，而是每個月的入不敷出……<br />黃士豪：「你不只擁有生而自由的人權，還擁有生而財富自由的基本權利！」<br /> <br /> <br />▊重建FIRE財務系統四步驟<br />透過書中的練習，一步一步，開始形塑出「理想生活」的願景畫面，便是啟動財富人生的一刻。<br />1、不要怕做夢，寫下來<br />2、從人生願景回推財務目標<br />3、量化財務現況與財務目標<br />4、拆解目標，訂定財富增長策略<br /> <br />絕非高空喊話，黃士豪首次揭露幫助過十萬人的財富增長計畫，從體檢你的財務現況，到搞定主動收入結構，槓桿你的被動收入，選擇長期複利投資……，當你可以用喜歡的工作帶來收入，理解這個世界分配金錢的邏輯，財富自由就不遠了。<br /> <br />I Will be good<br />夢想和你的距離並不遠<br />準備好，就拚下去！<br /> <br />★致富下載★<br />獨家設計實踐表單<br />行動清單+10張表格<br />夢想倉庫願景收斂、財務目標拆解、滾動預算與實際損益表、生存底線統計…<br />Let’s do it<br /></p><p><br /></p><p>【歡迎收聽｜迷誠品Podcast】EP351｜建立個人財務系統，搞懂《這輩子賺多少才夠》｜今天讀什麼<br /><br /><iframe src=\"https://open.spotify.com/embed/episode/4NWz2MQ64OiFFjPyjevcwu?utm_source=generator\" width=\"100%\" height=\"152\" frameborder=\"0\" allowfullscreen=\"\" allow=\"autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture\" loading=\"lazy\"></iframe><br /></p>',10,0,'2026-03-17 18:10:41','2026-03-17 18:10:41','https://www.eslite.com/product/10012014082682554385000'),(43,'財商: 不費力才會贏','吳淡如','9786264440547','時報文化出版企業股份有限公司','2026-01-20',450,'商業財經','https://s.eslite.com/b2b/vendor/vendor176732734082420260102121541/mainCoverImage1_1580705.jpg','<p>從財商 R.I.C.H出發<br />走向複利人生<br /><br />理財，像種一棵生命樹。<br /><br />Ｒ──重構思維（Reframe）<br />你得先知道，這棵樹要怎樣才能真正長高，才能在風雨來時，有地方遮蔭。心態是根，根不穩，樹就會倒。<br /><br />Ｉ──收入（Income）<br />你種出來的果實，不是用來一口氣吃光。一部分要拿來養自己，一部分要留起來，為冬天做準備。你的果實要能夠保存，也要知道放在哪裡，才不會被偷走。<br /><br />Ｃ──放大資本（Capital）<br />當你有了一籃健康的果實，就該學會「種出果實的種子」，讓每一顆果實，都有可能長出一棵新的樹。<br /><br />Ｈ──收穫人生（Harvest）<br />當你的林子越來越大，你終於不用追著錢跑。你可以選擇自己想過的生活節奏，有時間、有選擇，也有餘裕去看風景。這才是理財最終的意義。<br /><br />理財，不只是財務的成長，更是生命的修行。<br />從心出發，從根開始。<br />慢慢種，總有一天，你會在自己的樹蔭下乘涼。<br /></p>',10,0,'2026-03-17 18:10:45','2026-03-17 18:10:45','https://www.eslite.com/product/10012010632683071132009'),(44,'說到賣得動: 把專業說成生意的商業表達力','竺宥璋','9786264441711','時報文化出版企業股份有限公司','2026-01-27',380,'商業財經','https://s.eslite.com/b2b/vendor/vendor176775632804820260107112528/mainCoverImage1_1582470.jpg','<p>業績治百病！<br /><br />「商業表達不是形象管理，而是生意本身。」<br /><br />你是否有這樣的困擾？<br />有很好的商品或服務，但客戶不買單；<br />覺得自己講得很清楚，對方卻表示「我再想想」；<br />想經營個人品牌，但不懂怎麼說出自己的價值；<br />面對客戶質疑，不知道如何說服；不擅長推銷自己，又不想靠話術硬賣……<br /><br />問題不在你的能力，而在於你的表達，還沒轉換成「能促成決策的高價值語言」！<br /><br />在一人公司、微型創業、賣內容、賣服務的時代，<br />真正拉開差距的，除了努力和專業，是你能用高價值表達引導顧客買單<br />這是為一人公司、創業者以及任何需要推廣自身專業的人所寫的書。<br />在沒有業務、缺乏團隊甚至自己兼任客服的情況下，你說的每句話，都是成交的關鍵。<br />書中不談花俏話術，而是以一套清楚好用的商業表達系統，幫助你：<br /><br />　✅讓人用你期待的方式記住你（被看見）<br />　✅讓客戶知道你能解決什麼問題的價值說法（被理解）<br />　✅洞察需求，讓客戶自己說服自己（推動決策）<br />　✅有結構的說法比任何證照都具說服力（被信任）<br />　✅不靠硬推銷，也能成交（被選擇）<br /><br /><br />本書特色<br />商業表達力如同擴大器，能放大你的專業和價值<br />1.教你在高度同質化的市場中，把差異與價值說清楚，提升被選擇的機會。<br />2.利用KISS高價值表達三角形，讓客戶聽得到、聽得懂、聽得進你的重點。<br />3.提供自我介紹、洞察需求、價值表達、締結成交等四大關鍵場景的實用表達模組。大量示範舉例和練習，帶你摸清商業世界通用的表達方式，快速上手。<br />4.聆聽與讚美也是表達的一環，能幫你建立信任、強化關係，促成長期合作。<br />5.拆解影響決策的心理與情緒關鍵，臨門一腳的四趨提問法，push對方做出你期待的選擇。<br />（你是否願意／你還想忍受多久／你是否想成為／你打算什麼時候）<br /></p>',10,0,'2026-03-17 18:10:49','2026-03-17 18:10:49','https://www.eslite.com/product/10012010632683073559002'),(45,'從0到1: 打開世界運作的未知祕密, 在意想不到之處發現價值 (經典簽名版)','彼得．提爾/ 布雷克．馬斯特','9786267713679','天下雜誌股份有限公司','2026-02-04',450,'商業財經','https://s.eslite.com/b2b/newItem/2026/01/26/8141_113109732_633_mainCoverImage1.jpg','<html><head></head><body><p><b>史丹佛大學改變未來的一堂課</b></p><p><b>矽谷傳奇創業家、PayPal創辦人 彼得‧提爾 第一手分享</b></p><p><br></p><p>複製別人的模式比創新事物容易。</p><p>做大家都知道怎麼做的事、提供更多熟悉的東西，這是由1到n。</p><p>但是，創新是由0到1。創新獨一無二，\n創新的時機與開創出的結果也是新鮮奇特的。</p><p>這本書就是揭開由0到1創新的秘密。</p><p><br></p><p>彼得‧提爾（Peter\nThiel）是PayPal和Palantir共同創辦人，臉書第一位外部投資人，率先注資Yelp、LinkedIn、SpaceX、Spotify、Airbnb等新創企業。他念哲學與法律，卻在科技、創投世界大放異彩；成立提爾獎學金，鼓勵年輕人休學創業，激發自己的潛力。</p><p>提爾獨特的邏輯與眼光，帶你在意想不到之處發現價值。</p><p><br></p><p>這不是一般的商業書。看了這本書，你會學到：</p><p>‧「精實創業」（lean\nstartup）錯在哪裡；</p><p>‧莎士比亞和馬克思如何預言衝突；</p><p>‧「非理性繁榮」（irrational\nexuberance）在什麼時候是理性的；</p><p>‧機器為什麼是人類的朋友，而不是敵人；</p><p>‧托爾斯泰給新創事業什麼啟示；</p><p>‧嬉皮式的思考與恐怖分子有什麼類似之處；</p><p>‧美國人為什麼誤解中國；</p><p>‧特斯拉如何吸引李奧納多‧狄卡皮歐；</p><p>‧比爾蓋茲為何從科技業退休；</p><p>‧「破壞」（disruption）有什麼問題；</p><p>‧嬰兒潮世代給我們什麼錯覺； </p><p>‧哪些話我們以為是愛因斯坦說的，其實不是；</p><p>‧矽谷休閒裝扮背後代表的意義是什麼；</p><p>‧為什麼「失敗很好」的想法是錯誤的。</p><p><br></p><p><b>想要成功，你必須在一切發生之前研究結局。</b></p><p><b>你必須質疑你的構想，從零開始重新思考。</b></p><p>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p><b>從0到1，為自己創造無限機會與價值！</b></p><p><b><br></b></p><p>當一個有冒險精神的人願意寫書，就買來看。如果寫書的是彼得‧提爾，就看兩遍。但是保險起見，請看三遍。因為這本書絕對是經典之作。<br>《黑天鵝效應》作者 塔雷伯（Nassim Nicholas Taleb）<br><br>這本書傳達前所未見、耳目一新的觀念，教導如何在世界上創造價值。<br>Meta執行長 馬克‧祖克伯格（Mark Zuckerberg）<br><br>彼得‧提爾打造多家異軍突起的公司，《從0到1》說明他到底是如何做到的。<br>特斯拉汽車（Tesla）執行長 伊隆‧馬斯克（Elon Musk）<br><br>《從0到1》是大企業要不斷改進提升的重要手冊，才起步的新創事業也同樣適用。翻開閱讀，接受彼得‧提爾的挑戰，開創超乎期待的事業。<br>前奇異公司(GE)董事長 傑夫‧伊梅特（Jeff Immelt）<br><br>《從0到1》是每個想要創業與正在創業的人，都必須優先閱讀的一本書。不可錯過。<br>a16z共同創辦人 馬克‧安德森（Marc Andreessen） <br> <br>這本書是每個人都必讀的第一本、也是最後一本商業著作。在充滿零的世界，這本書是唯一的一。<br>著名科幻小說家 尼爾‧史蒂芬森（Neal Stephenson）<br><br>彼得‧提爾除了是成就非凡的創業家和投資人，他也是這個時代的公共知識份子領袖，閱讀這本書，你就能一探他為何能夠引領思潮。<br>暢銷書《大停滯》作者 泰勒‧柯文（Tyler Cowen）<br><br></p></body></html>',10,0,'2026-03-17 18:10:57','2026-03-17 18:10:57','https://www.eslite.com/product/10012030392683091421008'),(46,'贏在表達: 升學面試、工作簡報、會議發言, 打造開口就吸睛的自信說話法','胡中中','9786264177801','遠見天下文化出版股份有限公司','2026-01-23',420,'商業財經','https://s.eslite.com/b2b/newItem/2026/01/13/9033_190543350_747_mainCoverImage1.jpg','<p style=\"text-align:center;\"><b>站上舞台的自信，需要不斷練習<br /></b><b>完美不是目標，持續進步才是關鍵</b></p><p style=\"text-align:center;\"><b>最有成效的表達方式，最具感染力的聲音表情，<br /></b><b>掌握從容應答的對話訣竅，讓你從不敢開口到博得滿堂喝采。</b></p><p><b></b></p><p><b>＊ 3</b>動作完成開口準備<br /><b>＊ 4</b><span style=\"font-size:0.875rem; display:inline !important;\">步驟說清楚內容重點<br /></span><b>＊ 12</b><span style=\"font-size:0.875rem; display:inline !important;\">秒開場關鍵，擄獲全場注意力和好感度</span></p><p>微調聲音、情緒和儀態，說出傳達力、感染力和影響力<br /><span style=\"font-size:0.875rem; display:inline !important;\">讓你從緊張結巴，到侃侃而談；從無人回應，到全場叫好！</span></p><p><b>「這裡藏著一種「心法」，培養你面對變動與不確定時，依然可以穩穩站立、好好說話的內在穩定與心理韌性。」——胡中中</b></p><p><b>專文推薦</b>（依姓名筆畫排序）<b></b></p><p>「中中將正念、情緒教育、聲音表達及個人資源整合，與心理認知熔於一爐，條列出清晰的架構。這是一本專業，而且實用又豐富的書。」<b>——</b>李崇建（薩提爾推手）</p><p>「本書將這套經過無數次課堂驗證的系統分享出來，幫助更多人找回開口的勇氣與自信，學會如何掌握麥克風，贏在表達，更贏在真實的生命交流。」<b>——</b>張輝誠（學思達創始人）</p><p>「書裡歸納出三個核心感受，幫助我們進入自信狀態，讓我們就算緊張也能穩住自己。」<b>——</b>蔡淇華（作家）</p><p><b>有感推薦</b><b></b></p><p>林文煌（雨果文教基金會董事長）<br /><span style=\"font-size:0.875rem; display:inline !important;\">林耀隆（道明中學校長）<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">胡語姍（國立教育廣播電台主持人）<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">莊福泰（高雄中學校長）<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">愛瑞克（《命定之書》作者、TMBA共同創辦人）<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">劉繼文（均一教育平台資深研究教師）<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">藍偉瑩（財團法人瑩光教育協會創辦人）<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">（依姓名筆畫排序）</span></p><p><b>本書特點</b></p><p>1. 經歷多年課堂實際操作驗證，最有成效的說話養成法<br /><span style=\"font-size:0.875rem; display:inline !important;\">2. 幫助你打破說不好、不敢說、不知道怎麼說的表達困境<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">3. 從內容、語調、表情、動作到台風，全方位系統化的口語訓練<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">4. 羅列實用性高的說話範本，讓你上台不再腦袋一片空白</span></p>',10,0,'2026-03-17 18:11:01','2026-03-17 18:11:01','https://www.eslite.com/product/10012030542683078533007'),(47,'邏輯投資: 散戶贏過大盤的機會','邏輯投資 (劉冠宏)','9786264177597','遠見天下文化出版股份有限公司','2026-02-26',480,'商業財經','https://s.eslite.com/b2b/newItem/2026/02/05/9033_200053061_434_mainCoverImage1.jpg','<p style=\"text-align:center;\"><b>當你停止問「還會上漲嗎」，才真正開始投資。<br /></b></p><div style=\"text-align:center;\"><b><b>散戶不是輸在不夠努力，而是輸在錯誤的思考框架。<br /></b><b>停止追逐市場焦點，找出適合自己的戰場，<br /></b><b>才是轉虧為盈的關鍵。</b></b></div><p><b></b></p><p><b>★ </b><b>散戶在市場上永遠只有被宰的份？看到自己的優點，找出突破口</b></p><p>散戶之所以會輸錢，是不夠了解自身的優缺點。要贏錢，不必與機構投資人硬碰硬。只要選對自己有利的：</p><p>1. 法人資金大，使投資標的受限<br /><span style=\"font-size:0.875rem; display:inline !important;\">→散戶的機會：</span><b>散戶資金小，卻能靈活交易</b></p><p>2. 法人有同儕壓力，只能保守操作<br /><span style=\"font-size:0.875rem; display:inline !important;\">→散戶的機會：</span><b>散戶僅須盈虧自負，沒有績效壓力</b></p><p>3. 法人須顧慮短期績效，難以做長線<br /><span style=\"font-size:0.875rem; display:inline !important;\">→散戶的機會：</span><b>散戶可用耐心與時間換取報酬</b></p><p>4. 法人資訊必須涵蓋多領域，難以深入<br /><span style=\"font-size:0.875rem; display:inline !important;\">→散戶的機會：</span><b>散戶可成為特定領域專家，出奇制勝</b></p><p><b></b></p><p><b>★ </b><b>散戶輸在資訊不夠快？還是資金不夠大？找到市場的規則，就有散戶的機會</b></p><p>作者認為，散戶真正的弱點在於「盲目崇拜」與「缺乏系統性認知」。<span style=\"font-size:0.875rem; display:inline !important;\">市場是由各類投資人組成，找出意見分歧點就能看到機會。</span></p><p>股市規則❶ 股價是對未來的預測，而非過往績效。<br /><span style=\"font-size:0.875rem; display:inline !important;\">股市規則❷ 股市是資訊不對稱的不公平競爭。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">股市規則❸ 市場充滿變數與干擾因素，沒有人能100% 預測一切。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">股市規則❹ 高風險不等於高報酬，承擔風險之前必須三思。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">股市規則❺ 價格不等於價值，關鍵在於市場情緒與短期共識。</span></p><p><b>散戶的機會，就是找到「低效率市場」，樹立個人的投資優勢</b>。<br /><span style=\"font-size:0.875rem; display:inline !important;\">當市場情緒過熱過冷，或共識出錯，導致價格與價值之間出現落差， 便是進場時機！</span></p><p><b>★ </b><b>散戶難以找到更好獲利路徑？六大適合散戶選股策略，讓你獲利可期。</b></p><p>作者為散戶量身打造六種思路，發掘低估標的。以下是適合散戶發揮自身優勢的戰場：</p><p>❶ 價值修復：瞄準基本面重挫但仍有穩固護城河的標的。<br /><span style=\"font-size:0.875rem; display:inline !important;\">❷ 等待時間報酬：尋找暫時利空或利多尚未反映的股票。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❸ 理解商業模式：用九宮格檢視四種可能被低估的企業。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❹ 尋找成長股：看基本面+ 產業面五大篩選原則，尋找潛力股。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❺ 利用景氣循環：觀察產業盛衰週期，逢低買進靜待景氣回溫。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❻ 挖掘冷門股：從低成交量冷門股中，尋找有上漲機會的好股。</span></p><p>★ <b>散戶沒有更完整的投資邏輯？5</b><b>步驟拆解投資過程，創造穩定績效</b></p><p>作者認為，將投資過程化為紀律，按部就班完成每一次的投資，才能有效提升成功機率，逐步放大資產。</p><p><b>步驟1：選擇適合自己的戰場<br /></b><span style=\"font-size:0.875rem; display:inline !important;\">❶ 由個人較熟悉或感興趣的領域著手，例如：科技類、軍工類、營建類，並專注了解該領域。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❷ 專注「低效率市場」，如冷門股、景氣循環產業、轉型期公司等。</span></p><p><b>步驟2：篩選有投資潛力的股票<br /></b><span style=\"font-size:0.875rem; display:inline !important;\">依據本書所列六種適合散戶的戰略思路，在選定領域中尋找投資標的。</span></p><p><b>步驟3：四大進場原則，提升選股勝率<br /></b><span style=\"font-size:0.875rem; display:inline !important;\">❶ 價格低於價值。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❷ 具有可預期的合理回報。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❸ 足夠的安全邊際。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❹ 背後有中長期結構性因素支撐。</span></p><p><b>步驟4：四大出場原則，確保市場存活率<br /></b><span style=\"font-size:0.875rem; display:inline !important;\">❶ 達到目標價。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❷ 評估題材與利多已被市場充分定價。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❸ 持股預期報酬下修。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❹ 發現自身假設錯誤。</span></p><p><b>步驟5：提升勝率／放大獲利<br /></b><span style=\"font-size:0.875rem; display:inline !important;\">❶ 期望值思維：提升勝率、確保每筆交易潛在獲利大於風險。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❷ 讓獲利奔跑：耐心持有，不要急著停利。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❸ 交易檢討：記錄每次交易進、出場理由，透過檢討反省累積經驗。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❹ 提升知識：從選股過程學習產業、基本面、財報知識。<br /></span><span style=\"font-size:0.875rem; display:inline !important;\">❺ 發展投資風格：建立適合自己的投資風格，不盲從，不比較。</span></p><p>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n這不是教你「一夜致富」的魔法，而是教你「如何贏得更有道理」的生存手冊！</p>',10,0,'2026-03-17 18:11:06','2026-03-17 18:11:06','https://www.eslite.com/product/10012030542683094739001'),(48,'人比AI凶: AI再強, 你的微決策才是關鍵!','萬維鋼','9789861345659','先覺出版股份有限公司','2026-03-01',520,'商業財經','https://s.eslite.com/b2b/vendor/vendor177062439554820260209160640/mainCoverImage1_1601598.png','<html><head></head><body><p>「精英日課」重磅講者萬維鋼	最新趨勢大作<br>──為不甘平庸的你而寫！ <br><br><br>在AI時代，智商越來越不重要，選擇的智慧卻越來越重要。<br>AI看似什麼都能做，唯獨「微決策」，只能由人來做。<br><br>這本書，不僅是對超級人工智慧的回應，更是對人類自身的深度思考。<br>AI可以無限進步，但世界的真正走向，仍由人的判斷與行動決定！<br><br>萬維鋼從各個面向為你剖析：該如何正確使用AI，而非被它取代？如何擁有決策的智慧？為什麼手機不會毀了孩子，AI也不會取代白領工作？為什麼機器人之戰決定了大國的未來？算力為王的時代，經濟會衰退還是走向富足？<br><br>AI再強，也無法完整掌握你在商業、生活、教養現場的各種微妙情境。真正的進步不是AI推導而來的，而是你在現實生活中，透過無數個「微決策」所實踐出來的──因為人，總是比AI凶。<br><br>這本書說得不一定全對，但它獨一無二——<br>控制每一個微決策，展現你的風格和喜好，才能自我升級、塑造未來！</p></body></html>',10,0,'2026-03-17 18:11:09','2026-03-17 18:11:09','https://www.eslite.com/product/10012036172683095837003'),(49,'破局思維','賴聲焜','9786267735961','春天出版國際文化股份有限公司','2026-01-23',330,'商業財經','https://s.eslite.com/b2b/newItem/2026/01/08/8753_162646806_418_mainCoverImage1.jpg','<html><head></head><body><p>當你陷入困境、停滯不前時，真正能救你的，不是運氣，而是「破局力」。<br>\n本書以破局思維為核心，教你看透局勢、識破人心、調整思維，<br>\n從逆風中尋找突破，從低谷中尋回力量。<br>\n<br>\n</p><p>透過三十個實戰破局法，<br>\n你將學會——如何在逆境中重整旗鼓、在人際中見招拆招、<br>\n在職場中脫穎而出，在修心中找到內在定力。<br>\n<br>\n</p><p><strong>破局，是一場人生的進階修練。</strong><br>\n學會見局、佈局、破局，你將不再被局勢左右，而能成為操盤者。</p><p><br></p><p><b>破局，從逆襲開始。</b></p><p>當你以為無路可走，<br>\n也許，真正的轉機正在轉角等待。</p><p>我們喜歡「<b>逆襲</b>」，<br>\n因為那是一種普通人也能創造奇蹟的力量。<br>\n無論是個人還是企業，當環境劇變、風向逆轉，<br>\n唯有看清局勢、敢於破局，才能在危機中重生。</p><p><b>本書告訴你——破局不是運氣，而是方法。</b></p><p>📘 <b>破逆風局</b>：逆勢突圍，讓劣勢成為你的優勢。<br>\n🧠 <b>破認知局</b>：拆掉思維的牆，看見更大的格局。<br>\n💼 <b>破職場局</b>：在低谷中重整旗鼓，贏回主動。<br>\n🤝 <b>破人際局</b>：識人懂局，不被情緒與關係牽制。<br>\n💫 <b>破修心局</b>：修煉定力，讓心態決定成敗。</p><p>失敗是常態，成功是偶然。<br>\n但懂得「破局」的人，能把偶然變成必然。<br>\n你渴望旅行、渴望成功、渴望被看見，<br>\n卻常用各種理由說服自己原地不動——<br>\n那不是現實困住了你，而是你的思維。</p><p><b>破舊思維，才能見新世界。</b><br>\n本書結合古今經典破局案例與實戰策略，<br>\n從「認知、行動、執行」三個層次，<br>\n教你一步步培養破局思維，重啟人生賽局。</p><p>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p>無論你選擇從哪一章開始，<br>\n每一次閱讀，都是一次思維的突破與升級。</p></body></html>',10,0,'2026-03-17 18:11:13','2026-03-17 18:11:13','https://www.eslite.com/product/10012011202683073807004'),(50,'從破產人生逆襲到財務自由: 你一定要懂的財商真相, 36個翻轉心法把人生找回來','李文森','9786264442312','時報文化出版企業股份有限公司','2026-02-10',390,'商業財經','https://s.eslite.com/b2b/newItem/2026/01/23/7951_143202814_901_mainCoverImage1.jpg','<p>從負債百萬、誤入歧途，到實現財務自由——<br />一本結合真實人生故事 × 實用財商觀念 ×實踐方法的逆襲之書。<br /><br />寫給正在為金錢焦慮、對投資有興趣，但對市場風險與騙局感到不安<br />對未來迷惘、渴望翻身卻不知道從哪裡開始的你<br />跟著作者的指引，善用36個翻轉心法，<br />一起邁向財務自由之路<br /><br /><br /><br />他不是含著金湯匙出生的人，<br />相反地，從國中開始就歷經一連串的變故，人生似乎就此走向低谷……<br />童年失序、年少誤入歧途，大學畢業後負債百萬，工作、投資、人生方向，全都走錯。<br />那時候的他，只是不斷告訴自己：「再撐一下就會好。」<br />直到某一天，他終於看懂一件事——解決問題不單靠努力，還要加上正確的觀念。<br /><br />這本書，記錄了作者李文森從破產邊緣，一步步建立正確財商思維、避開投資陷阱、累積穩定現金流，最終走向財務自由的真實過程。<br /><br />沒有速成公式，沒有一夜致富，只有一次次修正錯誤的選擇。<br /><br />書中整理出「逆襲人生三十六技」，從自我認知、行動力建立、金錢觀念、投資風險判斷，到面對低潮時，如何不再把人生越過越糟。<br /><br />如果你也曾經——<br />努力工作，卻始終存不到錢；<br />想投資翻身，卻害怕踩雷；<br />明明很認真，人生卻原地踏步；<br />那麼你需要的，或許不是更拚命，<br />而是一次重新理解人生與金錢規則的機會。<br />如果你願意重新理解人生的規則，逆襲，永遠不嫌晚。<br />本書特色：<br />●真實逆襲，不包裝成功<br />從負債、踩雷、被騙，到重新站穩腳步，完整揭露一般人最容易走錯的關鍵轉折。<br /><br />●看懂錢怎麼流，人生才會動<br />系統化拆解財商觀念、投資迷思與常見陷阱，幫助讀者建立可長期運作的金錢邏輯。<br /><br />●給正在卡關的你<br />不是寫給天才或菁英，而是寫給努力卻看不到出口的你。<br /><br /><br /></p>',10,0,'2026-03-17 18:11:19','2026-03-17 18:11:19','https://www.eslite.com/product/10012010632683083731009'),(51,'向上管理: 升職加薪、拒收爛攤! 10堂高效對話讓主管挺你','梅洛蒂．懷丁','9786263588585','三采文化股份有限公司','2026-02-26',480,'商業財經','https://s.eslite.com/b2b/vendor/vendor177059424835720260209074413/mainCoverImage1_1601277.jpg','<html><head></head><body><p>【網書大標】<br><br>★★亞馬遜4.9星、GoodReads4.1星好評★★<br><br>不懂向上溝通，就只能自己做到死還得不到讚揚！<br>現代上班族更需要有智慧與方法掌控工作，<br>人類行為學教授/職業教練的工作對話實踐法，<br>是你獲得職場主導權的實用指南。<br><br><br><br>　「本書透過新的視角來詮釋職場上的關係，將潛在衝突轉化為成長契機。以真實案例和清晰架構，教你解讀主管的行為，在職場上解鎖屬於你的成就。」── 丹尼爾．品克（Daniel H. Pink），《紐約時報》暢銷榜冠軍作者<br><br>　　「本書教你如何借力使力與主管合作──無論剛踏入職場，還是晉升主管職，向上管理是每個人都必須學會的重要能力。」── 凡妮莎．范．愛德華茲（Vanessa Van Edwards），人際智商實驗室（The Science of People）創辦人暨暢銷書作者<br><br>　　「這是一堂教授職涯關鍵軟實力的大師級課程。懷爾汀用這份職場教戰手冊，教我們如何應對職場中的人際關係，內容淺顯易懂、符合現代習慣。」── 多利．克拉克（Dorie Clark），《華爾街日報》暢銷作者，著有《長線思維》，於哥倫比亞大學商學院教授高階主管教育課程<br><br><br><br>【內容簡介】<br><br>「主管又突發奇想，丟工作給我要怎麼拒絕？」<br>「被過度監督、在會議中被打斷、被指派不重要的工作，影響到升遷機會，該如何是好？」<br>「要怎麼展現工作績效讓主管看見，又不被認為過度膨脹？」<br>「世界上是否有方法，能巧妙地讓我獲得主管的尊重？」<br><br><br><br>＃在變動的職場世界中，重新掌控自己的職業生涯。<br>透過十場對話課引導你如何成功倡導自己的職場需求，累積關係資本，提升：<br><br>• 情緒智力：掌握主管們的思維模式，理解主管優先事項。<br>「我注意到，我與主管對於 × × 抱持不一樣的看法。不知是否能談一談您的想法嗎？想請問您最看重的事情是什麼？」<br><br>• 人際資本：贏得主管的尊重，加強職場關係、擺脫情緒勞動。<br>「我希望在 × × 專案能夠成功，我想談談覺得有幫助的事。」<br><br>• 談判能力：有技巧地拒絕和反駁，避免無謂的工作負擔。<br>「我們可以重新討論專案的目標和難度設定嗎？有沒有彈性，可以針對成果或資源做些調整？」<br><br><br><br>書中的對話範例和策略不限產業類別或公司規模，不論你是新人想贏在起跑點，還是工作多年想改變他人對待你的方式，都能適用。本書引導你弄懂該如何遣詞用字才受重視，並透過「周遭權力地圖」、「主管4C風格象限圖」、「拒絕權力評估表」、「意見表達ABC表等圖表工具」，清楚呈現概念、分析情境，教你如何在每一場對話中調整說話的方式，包括何時輕鬆帶過、何時嚴肅以對，以及如何在真誠與專業、坦率與保留之間取平衡。另外，書中也會討論遭遇不平等待遇、偏見或歧視的應對方法。你將讀到學員的真實心聲與案例，以及數千位受訪讀者的寶貴意見。<br><br><br><br>【適用場景】公司會議、年度績效檢視，談升遷、談加薪、與主管的主管交流、談離職......等。<br><br><br><br>【本書特色】<br><br>1.除溝通之外，教你如何搞定社內人際，適當展現個人優勢、績效，讓你從談加薪、升遷、到離職都順順利利。<br>2.本書提供多種對話、信件範本，並設計「現學現賣」專欄補充情境應對技巧，可直接套用至現實情境中即刻運用。<br>3.搭配分析圖表，讓重點概念一目了然，加深讀者印象。</p></body></html>',10,0,'2026-03-17 18:11:24','2026-03-17 18:11:24','https://www.eslite.com/product/10012014082683094878007'),(52,'設計力創新 (第3版)','羅伯托．維甘提','9786267747537','馬可孛羅文化事業股份有限公司','2026-02-05',440,'商業財經','https://s.eslite.com/b2b/newItem/2026/01/27/15138_192150807_241_mainCoverImage1.jpg','<p>榮獲義大利設計最高榮譽「金圓規獎」\n<br /> \n<br />\n<br />★美國《商業週刊》年度十大好書\n<br />★《華爾街日報》、《舊金山書評》重磅好評\n<br /> \n<br />\n<br />激進式創新✕進化策略管理✕品牌價值與文化優勢＝競爭力\n<br />\n<br />一本完整詮釋設計力創新理論與實務的專書\n<br />一場影響全球企業與設計界的創新思潮革命\n<br />\n<br />\n<br />羅伯托・維甘提提出的「第三條創新之路」⸺⸺\n<br />設計力創新（Design-Driven Innovation）\n<br />\n<br />　　\n<br />         ◉當技術突破成為日常，\n<br />　　    真正讓你脫穎而出的是——為技術賦予「意義」的能力！\n<br />\n<br />　　傳統創新有兩條主線：技術推動的顛覆，以及市場牽引的漸進。然而維甘提教授指出，最能改變一場賽局的往往是第三種力量：意義的激進創新——\n<br />\n<br />　　不是迎合需求，而是創造需求；不是推出新技術，而是提出新願景。\n<br />\n<br />　　為何 Alessi、Kartell、Bang &amp; Olufsen 等多為中小規模、甚至未設置設計部門的企業，卻能長年引領潮流？答案是：創造意義。一旦組織培養出「意義的激進創新」能力，便能形成難以複製的文化優勢與長期獲利。\n<br />\n<br />　　從 任天堂 Wii 改寫「遊戲」的定義、Apple iPod 重塑「聆聽」的體驗，以至於Artemide 以照明重構「感受」本身。這些劃時代的產品，皆源自一群深諳文化、科技與生活脈絡的「詮釋者」——他們洞見人類尚未說出口的渴望。\n<br />\n<br />　　本書以消費電子、材料、醫療、食品、鐘錶等跨產業案例深入說明，當技術人人可得、日新月異，產生差異化的關鍵就在於：找到最有價值的應用與意義。設計者不僅僅是造型與使用者研究的執行者，更該是意義的研究者。企業領導者應以願景為核心，連結設計、技術與市場，主動向社會提出生活提案。　\n<br />　\n<br />\n<br />　　「每一位關注創新的經理人都應該讀這本書。\n<br />　　書中的觀點，將成為二十一世紀經營者脫穎而出的關鍵優勢。」\n<br />　　——哈佛商學院教授  馬可・伊安西提 \n<br />\n<br />\n<br />❖國際媒體讚譽❖\n<br />\n<br />「一本商業人士必備的設計入門書。米蘭理工大學教授維甘提挑戰『顧客永遠是對的』的傳統思維，主張以顛覆市場預期心理、創造意義的設計，開啟全新的競爭方式，並提出具體方法，幫助經營管理者自我啟動『激進創新計畫』。」——《商業周刊》（BusinessWeek）\n<br />\n<br />「企業該如何創造新的意義，並以設計賦予產品靈魂？作者建議：應與那些深諳文化脈絡、能詮釋市場趨勢的『詮釋者』建立連結。若藝術反映人生，那麼企業創新也該學習藝術創作。」——《華爾街日報》（The Wall Street Journal）\n<br />\n<br />「遵循作者的建議，或許需要花點時間，但終有一天，競爭對手將困惑於你究竟如何重新定義並奪走整個市場。」——《舊金山書評》（San Francisco Book Review）\n<br />\n<br />「具備設計創新力的人能創造出『消費者未曾意識到，卻發自內心渴望的意義』，從而打造出讓人們愛不釋手的產品。」——《BiZed》雙月刊\n<br />\n<br />「當代消費者追求的不再只是物質與地位，而是認同、歸屬與意義。作者在書中主張『第三種創新』——由文化詮釋者所驅動，以重新賦予事物新意義，開創全新的市場。」——《Design Mind》雜誌\n<br />\n<br />「羅伯特・維甘提的著作闡明：在今日，創造意義的能力是創新的核心。」——魯卡・迪拜瑟（Luca De Biase），《24小時太陽報》（Il Sole 24 Ore）\n<br />\n<br />\n<br />❖專業人士力薦❖\n<br />\n<br />紐約現代藝術博物館（MoMA）建築設計領域資深策展人  寶拉・安東奈莉（Paola Antonelli）\n<br />義大利法拉利與飛雅特集團董事長   盧卡・迪・蒙特澤莫羅（Luca di Montezemolo）\n<br />Herman Miller總裁兼首席執行長   布萊恩・沃克（Brian C. Walker）\n<br />\n<br />明基電通、佳世達科技副總經理暨設計長  王千睿\n<br />《美學CEO》作者  吳翰中\n<br />實踐大學副校長．工業產品設計學系教授  官政能\n<br />政治大學商學院智財所副教授  邱奕嘉\n<br />國立政治大學企業管理研究所特聘教授、美國西北大學Kellogg School行銷學博士  洪順慶\n<br />國立臺灣師範大學設計研究所教授  鄧成連\n<br />奇想創造群創辦人暨設計總監  謝榮雅\n<br />\n<br />★揭示創新的新方向\n<br />　　市場上一片創新聲，所有的企業都以創新為年度主軸，把創新當作企業翻升的關鍵密碼。\n<br />　　一般的創新法則是從了解顧客行為開始，從人性的角度去思考創新的發展，屬於「無中生有」的創新；《設計力創新》一書卻揭示了一個新的方向，作者認為創新即是向顧客提案，透過傾聽、詮釋、訴說而賦予創新全新的意義，因此這是一個精心設計的過程。\n<br />　　創新的高度不確定性和高風險，往往是企業寧願因襲舊制、裹足不前的原因。本書提供培養設計力創新能力的方法，讓企業可以更精準賦予創新的意義，更清楚掌握創新的內涵。《設計力創新》的意念佐以精簡的文字與多元的範例，為企業另闢創新的蹊徑。\n<br />　　站在巨人的肩膀上，才能看得更遠；懂得設計力創新的企業，才能立於不敗。——政治大學商學院智財所副教授　邱奕嘉\n<br />\n<br />★超乎消費者預期的品牌經營\n<br />　　企業要創造競爭優勢，只經營顧客滿意是不夠的。奢華品牌 LV、Prada、Gucci的愛用者不只是對他們所擁有的品牌滿意，還以擁有這些品牌為榮；蘋果的顧客使用一系列的蘋果產品如 MacBook、iPod、iPhone、iPad，他們會因為擁有這些產品而引以為傲；MontBlanc 也不遑多讓，其忠誠顧客經常擁有其手表、名片夾、公事包、鋼筆、原子筆、鑰匙包等。這些顧客不只是滿意，而是愛戀他們所擁有的品牌。愛戀的最重要原因之一是這些品牌的經營者，所設計出來的產品不斷創新，超乎他們的想像和預期。\n<br />　　現代行銷哲學的中心思想是市場導向，即公司上下針對有關現在與未來顧客需求市場情報的蒐集，跨部門的情報傳播，並據此採取反應行動的經營理念。大多數公司若能服膺市場導向的經營哲學，必能創造極佳的競爭優勢和顧客滿意度（Customer Satisfaction, CS），因為這些公司能滿足消費者需求。經營顧客滿意度，是每一家公司的重要目標，很多公司定期搜集顧客意見，追蹤、管理顧客滿意度。\n<br />　　不過少數的公司並不以此為滿足，他們認為要讓消費者喜出望外，超越顧客預期，創造驚喜，不能被動地只研究消費者需求，而是主動睿智地對消費者提案。相較於市場導向的演進式（evolutionary）創新，根基於對消費者的洞察；設計驅動（design-driven）的革命式（revolutionary）創新，則奠基於不同領域專家的詮釋。例如在Alessi公司，建築師為茶與咖啡餐具用品設計帶來完全不同的理念；生活型態領導者Apple為電腦、音樂和手機顛覆傳統的創新思維。《設計力創新》一書果敢地指出，創新性公司的成功之道，在於和各不同領域許多詮釋者的互動網路，而非只是一味地依賴焦點團體研究或市場調查。——國立政治大學企業管理研究所特聘教授、美國西北大學 Kellogg School 行銷學博士　洪順慶\n<br />\n<br />★維甘提教授的精采分析，不僅能激發商業書讀者、學生與業界人士的思考，書中的精闢論述與敏銳觀察，以及具啟發性的嶄新觀點，對有志於設計，並決心在專業領域中不斷精進、追求創新的人而言，都極具參考價值。——盧卡・迪・蒙特澤莫羅，義大利法拉利與飛雅特集團董事長   \n<br />\n<br />★每一位關注創新的經理人都應該讀這本書。書中提出的觀點，將成為二十一世紀經理人脫穎而出的關鍵優勢。——馬可・伊安希帝（Marco Iansiti），哈佛商學院教授\n<br />\n<br />★ 設計或許不能拯救世界，但能讓世界變得更好。維甘提是那少數熱情且富遠見的先鋒，致力於讓掌握決策權的人理解設計文化的真正力量。——寶拉．安東奈莉，紐約現代藝術博物館（MoMA）建築設計領域資深策展人</p>',10,0,'2026-03-17 18:11:28','2026-03-17 18:11:28','https://www.eslite.com/product/10012013192683083514008'),(69,'守護女主角哥哥的方法 3 (首刷附錄版)','KIN','9786267793329','三日月書版股份有限公司','2026-03-11',500,'輕小說','https://s.eslite.com/b2b/vendor/vendor177252569375220260303161458/mainCoverImage1_1608782.jpg','<html><head></head><body><p>★這段人生，究竟是喜是悲？<br>★毀滅與混亂過後，是否會迎來重生──<br>★首刷附贈〈女王〉精美閃卡<br>★KAKAO評價滿分、觀看次數破億超人氣韓國小說<br><br>曾獨自離開阿格里奇的羅莎娜<br>為了將一切做個了結，<br>來到世界樹參加五大家族的和睦會，<br>並且與傑瑞米重逢。<br><br>但這場和睦會果然不如預想中順利，<br>阿格里奇與海伯里昂頻頻爆發衝突、<br>加斯東勒不堪的祕密遭揭開、<br>人偶尼克斯引發不安，<br>貝爾提烏姆的戰鬥人偶更突然出現，<br>血染世界樹……<br><br>黑夜終將過去，黎明總會來臨──<br>在一切毀滅結束之後，<br>是否有機會重新開始？</p></body></html>',10,0,'2026-03-17 18:14:09','2026-03-17 18:14:09','https://www.eslite.com/product/10012017642683103941005'),(70,'克羅洛戰記: 轉移到異世界的我, 最擅長的好像只有床上功夫 2 (首刷限定版)','サイトウアユム','9789572668832','東立出版社有限公司','2021-05-15',240,'輕小說','https://s.eslite.com/upload/product/o/2682005365001/20210417040216197138.jpg','<div>「我正煩惱該殺了你，還是該讓你活命。」克羅洛立下戰功，成為侯爵領地的領主。堆積如山的問題當前，克羅洛動用原本世界的知識，與女神官及女騎士成為夥伴的同時，設法進行領地改革。然而，對那些知識感到事有蹊蹺的皇女蒂莉雅，向克羅洛逼問──「你老實說。這麼一來或許還可以免於一死。」克羅洛能夠順利改革領地，並且建立後宮嗎!?然後又有一名美少女爬上了床!!劇情與色情兼具，大受歡迎的情色王道戰記，第二彈！</div>',10,0,'2026-03-17 18:14:17','2026-03-17 18:14:17','https://www.eslite.com/product/1001129222682005365001'),(71,'我買下了與她的每週密會~在一個屋簷下, 屬於兩人的祕密~ 5','羽田宇佐','9786264158343','台灣角川股份有限公司','2025-07-24',280,'輕小說','https://s.eslite.com/b2b/vendor/mod_vendor175273111254320250717134517/mainCoverImage1_2682910540005.jpg','<p>來到春天，我「做不到的事情」增加了。<br />\n成為室友後，我跟宮城應該會變得更為親近，<br />\n我們相處起來卻莫名尷尬。<br />\n不說碰觸或接吻，就連交談都非常少。<br />\n為了找回過去那些理所當然的互動，<br />\n我們需要找出代替五千圓的新藉口──一個新的規則。<br />\n來到春天，我「不明白的事情」增加了。<br />\n沒被花掉的五千圓和變成室友的仙台同學。<br />\n我過去為這段關係賦予的那個理所當然的解釋，<br />\n因為這些事實而有了一百八十度大轉變。<br />\n為什麼仙台同學那時候會──<br />\n面對事到如今才湧上心頭的疑問，<br />\n我甚至不明白自己到底想不想知道答案。<br /><br />©Usa Haneda, U35 2024 / KADOKAWA CORPORATION</p>',10,0,'2026-03-17 18:14:20','2026-03-17 18:14:20','https://www.eslite.com/product/10012011762682910540005'),(72,'娑婆 (精裝/2冊合售)','詩無茶','9786269253210','一豆文化有限公司','2026-03-13',910,'輕小說','https://s.eslite.com/b2b/vendor/vendor177252029055620260303144455/mainCoverImage1_1608619.jpg','<p>謝九樓當了三百年閻王。<br /><br />他在陰司見到提燈第一眼，心裡就想：這人好看，我要把他留下來。<br />於是就把提燈扣了三百年。<br /><br />三百年間，該做的不該做的他全對提燈做了，對方渾身上下沒哪一處是他沒碰過的。<br /><br />除了兩樣東西。<br />謝九樓絕不敢碰。<br /><br />一是玉扳指，二是金筷子。<br />兩樣東西都是那個人送給提燈的。<br /><br />那個人是誰，謝九樓從來不問。<br /><br />只是提燈每多看它們一次，謝九樓就會想方設法報復回去。<br /><br />在他的寢殿中，他的垂簾後，他給提燈造的椒房裡。<br />在一切讓提燈不願意的地方，用提燈不願意的方式。<br /><br />後來有一次謝九樓忍不住，偷偷跟著提燈出去，看他在街上與人閒聊。<br /><br />那人說:「你這玉扳指真好看。」<br />提燈笑:「一位故人送的。」<br /><br />提燈一笑，謝九樓就恨得牙癢癢：提燈從來沒對他這麼笑過。<br /><br />那人又問:「什麼故人？」<br />提燈又笑:「你不認識的。」<br /><br />謝九樓牙更癢了：提燈笑得那麼好看，就跟那個故人是什麼私藏的寶貝似的，一點捨不得讓外人知道。<br /><br />然後他聽見提燈說:「叫謝九樓。死了很多年了。」</p>',9,1,'2026-03-17 18:14:24','2026-04-10 14:41:15','https://www.eslite.com/product/10012012032683104250007'),(73,'琥珀之秋, 0秒之旅','八目迷','9786263775992','尖端出版','2024-03-08',260,'輕小說','https://s.eslite.com/b2b/vendor/030420240221121230/mainCoverImage1_1220236.jpg','<p>★科幻 X 青春 X 成長，繼《在昨日的春天等待你》後，再次讓你感動的八目 迷系列新作登場！<br />★當世界靜止時，我跟妳的故事才剛要開始。少男少女的公路旅行，寫下秋日最動人的詩篇。<br /><br />時間停在十一點十四分三十六秒。這並不是譬喻或修飾，時間真的停止了。<br /><br />內向的高中生麥野茅人參加修學旅行，來到函館卻遇上離奇的神祕現象，全世界的時間靜止不動。<br />街道上所有事物毫無動靜，只有麥野能活動……正當麥野疑惑的時候，他忽然發現還有一個人能動。<br />那是函館當地的不良少女——井熊光。<br /><br />兩人想讓時間重新恢復流動。這時麥野想起了一件事，幾天前去世的叔叔曾經提到——「琥珀的世界」。<br />兩人猜想全世界的時間停止，也許跟這個有關，於是他們朝向東京前進，尋找恢復時間流動的線索。<br /><br />在時間靜止的世界中，麥野與井熊踏上僅有彼此為伴的青春旅程。</p>',10,0,'2026-03-17 18:14:29','2026-03-17 18:14:29','https://www.eslite.com/product/10012116312682527251004'),(74,'在昨日的春天等待你','八目迷','9789571094496','尖端出版','2021-04-06',280,'輕小說','https://s.eslite.com/upload/product/o/2681993645003/20210320040615185774.jpg','<div>真相揭露時，肯定會想要讀第二次！<br/>特殊時間輪迴設定！ 感動的青春SF登場！<br/><br/>【故事簡介】<br/>傍晚六點的報時鐘聲開始播放時，奏江的意識就會進行時間跳躍──<br/>從東京離家出走到曾經居住過的離島，袖島的船見奏江，被捲入了名為「回滾」的時間回溯現象。在紊亂的時間線中，時隔兩年再會的青梅竹馬保科明里，對奏江許了個願：「希望你救我哥哥」。為了拯救明里幾天前過世的哥哥彰人，奏江利用回滾盡力奔走。在他回溯時間的同時，明里的祕密也逐漸浮出水面……兩人甜蜜又苦澀的春天開始了。</div>',10,0,'2026-03-17 18:14:34','2026-03-17 18:14:34','https://www.eslite.com/product/1001125622681993645003'),(75,'末日時在做什麼? 有沒有空? 可以來拯救嗎? EX','枯野 瑛','9789578531277','台灣角川股份有限公司','2017-12-25',210,'輕小說','https://s.eslite.com/upload/product/o/2681528534000/ec1405182.jpg','<div>◎《這本輕小說真厲害2016》作品部門第5名，新作部門第2名。◎在網路上蔚為話題的末日系作品。◎以人類滅亡後五百年的世界為舞台，妖精少女與人類青年共同經歷的日子。在春天的暖陽中，年幼的少女妖精菈琪旭捧著《聖劍》瑟尼歐里斯陷入遐想－－那是五百年前發生的事。正規勇者黎拉十四歲，準勇者威廉十五歲。拯救人類免於星神威脅的這對師兄妹，平日的生活既荒唐又多采多姿……那是稍早前發生的事。註定赴死的成體妖精兵珂朵莉，以及二等咒器技官威廉。受思慕的每一分每一秒，都將成為他們倆難以忘懷的夢。出自《末日時在做什麼？》第一部的外傳故事登場。相關系列日本動畫：上映時間：2017年4月     輕小說：末日時在做什麼？能不能再見一面？</div>',10,0,'2026-03-17 18:14:37','2026-03-17 18:14:37','https://www.eslite.com/product/1001125122641562'),(76,'守護女主角哥哥的方法 2','KIN','9786267793039','三日月書版股份有限公司','2025-12-10',480,'輕小說','https://s.eslite.com/b2b/vendor/vendor176465013575920251202123536/mainCoverImage1_1563942.jpg','<html><head></head><body><p>★故事走向已無法預測，早已死去之人竟出現在眼前!?<br>★把妳剩下的時間給我吧。<br>★正義化身女主角哥哥╳美艷毒蝶反派女角<br>★KAKAO評價滿分、觀看次數破億超人氣韓國小說<br><br>離開阿格里奇後倒下的羅莎娜，<br>被卡西斯救起並帶往費德里安。<br>而將羅莎娜帶回費德里安的卡西斯，<br>逐漸壓抑不住想占有她的欲望……<br>然而，故事中的其他男主角也接連找上門！<br>白之魔獸師奧爾卡莫名入侵費德里安，<br>對羅莎娜表露出興趣；<br>黃之首長諾埃爾寄來「邀請函」邀請羅莎娜前往，<br>更附上一撮熟悉的金髮──<br>為了確認事情是否正如自己所想，<br>羅莎娜決定瞞著卡西斯，<br>獨自前往黃之貝爾提烏姆……</p></body></html>',10,0,'2026-03-17 18:14:41','2026-03-17 18:14:41','https://www.eslite.com/product/10012017642683050300009'),(77,'獵人只想安靜生活 3','103','9786267412954','深空出版','2026-02-25',400,'輕小說','https://s.eslite.com/b2b/newItem/2025/12/04/8113_111015282_877_mainCoverImage1.jpg','<p>厭世系淡定受╳執著系腹黑攻 <br />跨越時空、蹚過地獄， <br />直到你我得以再度相逢── <br /><br />八年的時光憑空消失， <br />也吞噬了車宜再心中僅存的淨土。 <br />那名Ｊ親手從毒沼中救出的瀕死少年， <br />如今彷彿被誰抹去痕跡，連同病房徹底人間蒸發。 <br />拋下對方自生自滅，是車宜再必須背負餘生的罪， <br />而贖罪的第一步，便是找出少年失蹤的真相。 <br />巧合的是，所有蛛絲馬跡， <br />皆指向李俟瀛致力圍剿的恐怖組織──普羅米修斯。 <br />毒液、綁架、實驗體……隨著拼圖逐一湊齊， <br />車宜再記憶中善良乖巧的少年身影， <br />竟逐漸與囂張恣意的李俟瀛重疊…… <br />「你的存在，是我唯一的救贖</p>',10,0,'2026-03-17 18:14:45','2026-03-17 18:14:45','https://www.eslite.com/product/10012011762683048955006'),(78,'人生何處無鯤鵬 3 (完/簽名特裝組)','黑蛋白','9789754772302','愛呦文創有限公司','2026-03-05',1190,'輕小說','https://s.eslite.com/b2b/newItem/2026/02/13/8113_094753036_602_mainCoverImage1.jpg','<p>★引頸期待三年的盛大完結！甜到心口，刀到見骨！ <br />終於開竅的黑兒，以及繼續失憶的大掌櫃，一起火熱緝兇 <br /><br />★鯤鵬社被盯上了── <br />燒分社、截信件、追到竹林放暗箭！ <br />天！這年頭談戀愛之前是不是得先活下來？ <br /><br />★隨書好禮大方送： <br />第一重：新銳繪師凜舞REKU精心繪製「來，抱一下」拉頁海報 <br />第二重：隨書贈送「人生處處有鯤鵬」留言明信片（兩款隨機出貨） <br />第三重：特別收錄獨家訪談最終回，什麼？坑剛填完，又要開新的？ <br />第四重：作者後記內心話──人生果然還是要被雷劈一下的！ <br /><br />★預購限量好禮： <br />預購贈品A5文件夾乙個（3款隨機） <br />　預購送「水榭對飲款」或「楓林相擁款」或「雪庭相偎款」A5文件夾乙個 <br />　（數量有限，送完為止） <br /><br /><br />人生何處無鯤鵬3（完）【簽名特裝組】╱小說+3.7萬字肉番《四季如春》+「鯤鵬誌系列」壓克力裱裝燙金親簽簽名板+「鯤鵬誌系列」古風場景大場景立牌組+A5文件夾乙個（3款隨機） <br /><br />=商品簡介= <br /><br />一、「鯤鵬誌系列周邊」古風場景壓克力立牌組 <br />材質：2+1mm透明壓克力╱雙面同圖╱保護膜請自行撕除 <br />尺寸：大背景立牌約12.5x12.35cm、底座約9x9cm <br />（內附2片14x20cm+1片9x9cm自組板，總共有3個角色牌、1大6小個場景牌） <br /><br />備註： <br />1. 壓克力表面可能存在細小劃痕，此情況不在售後範圍內 <br />2. 大背板體積較大，若單獨使用時，請插在靠中心的位子，以免重心不穩翻倒 <br />3. 附3款Q圖立牌，可自行替換，前面的裝飾小插牌亦可自由組合搭配 <br /><br />二、「鯤鵬誌系列周邊」壓克力裱裝燙金親簽簽名板（作者親簽） <br />尺寸：約14.2x20.2cm╱壓克力裱裝╱拉絲銀蔥閃底╱包流沙金邊╱表層燙流沙淺金╱此為「鯤鵬誌系列周邊」，為關山盡和吳幸子的雲雨圖╱繪師60全新繪製色氣滿滿的精美插圖╱簽名板上有作者親筆簽名，壓克力表層的透明度和顯色效果比PET更佳，質感再升級！ <br /><br />注意事項： <br />1. 表面可能存在細小劃痕，此情況不在售後範圍內 <br />2. PET表層為了燙金，會先將保護膜撕除再燙金，故表面無法覆膜，請勿嘗試撕膜，如因人為破壞導致　　PET層被撕開，此情況不得退換貨 <br />3.包邊因工藝限制可能存在皺褶、翹邊、溢膠等情況，屬正常現象，不視為瑕疵 <br />4.商品出廠後，板子會因環境因素產生彎曲，屬正常現象，不視為瑕疵 <br /><br /><br />=番外別冊簡介= <br /><br />雖然已記不起十年前和「哥哥」相處的點滴， <br />那麼，現在重新創造和「哥哥」的甜蜜日常也不遲…… <br /><br />〈鬧洞房〉 <br />「我都想好了，無論妳將來生了男娃娃還是女娃娃， <br />我手裡的產業都交給他來管……」 <br /><br />〈秋高氣爽馬蹄疾〉 <br />「我慣壞你了，現在什麼下流話都敢說。」 <br />「近朱者赤，近墨者黑。」 <br />「那我可得瞧瞧，黑副將在草民這兒，黑成什麼樣兒了。」 <br /><br />〈隔牆有耳〉 <br />「不了，我身上又是泥又是水，別弄髒你。」 <br />「我就喜歡被哥哥弄髒。」 <br /><br />〈煙花會〉 <br />「你有話想同我說吧？」 <br /><br />〈探親〉 <br />餘生，他們也會這樣， <br />繼續相融著度過歲歲年年…… <br /><br /><br />=小說內容簡介= <br /><br />「我問過了，若夫妻或情人想求長久相伴，就打成同心結，掛在寺裡的姻緣樹上，必定能白首到老。」 <br />「那就打成同心結吧。」黑兒雖然不信這一套，可內心難免跟著火熱起來。 <br /><br />馬面城的秋夜祭未至，一場突如其來的刺殺卻先染紅了楓林。黑兒故人的死，不僅揭開了兩年前那夜荒唐的真相，更引來了名為「玉風閣」的神祕敵手。同時，鯤鵬社各地分社接連遭祝融之災，對方手段狠辣，似乎想要染翠的一條命？ <br /><br />雪上加霜的是，鯤鵬社背後的靠山，也就是染翠的義父榮親王，竟然放任玉風閣四處作亂，大有要把染翠當成棄子的架式，於是染翠索性將大掌櫃印信寄出，甩手不幹了，並悄悄上京想找義父討個說法。 <br /><br />誰知平日裡悶不吭聲的臭木頭黑兒，竟不管不顧地追了上來！從馬面城到丹川縣，兩人一路在殺機中逃亡，卻也在生死與共的懸崖底，捅破了那層橫亙十餘年的窗戶紙。 <br /><br />原來，黑兒隱瞞的過往，竟是為了守護染翠活下去的承諾；而那個一心想置染翠於死地的幕後黑手，竟是…… <br /><br />面對扭曲的親情與遲來的深情，染大掌櫃這回不只要算清這筆陳年爛帳，更要與他的「哥哥」一起回到最初的芎宜，補上那場錯過了十多年的璀璨煙花。 <br /><br />＝延伸閱讀＝ <br />愛生活◆愛閱讀◆愛創作 <br />更多精采活動與新書訊息請關注： <br />愛呦文創粉絲團：https://www.facebook.com/iyao.book/</p>',10,0,'2026-03-17 18:14:48','2026-03-17 18:14:48','https://www.eslite.com/product/10012011762683097007008'),(79,'妄想限界 白夜今明 1: 異維殺戮','杉原夜季','9786269973484','更生文化設計有限公司','2026-03-13',320,'輕小說','https://s.eslite.com/b2b/vendor/vendor177183292664520260223154826/mainCoverImage1_1604608.jpg','<p>★ 本書是由「作者自費出版」原創輕小說，委託「更生文化設計有限公司」排版設計並出版，希望大家能多支持原創作者！<br />★ 精緻文庫本尺寸，一手掌握的冒險世界，隨身翻閱、完美收藏。<br />★ 輕小說也能有收藏品般的質感！<br />★ 封面採用「250磅頂級銅西卡」，於高端四色印刷機印製，色彩絢麗！再上一層多麗亮膜，打造出高質感的艷麗封面。<br />★ 內頁採用「永豐80磅頂級米色道林紙」印製，紙張色澤、質地出眾，長時間閱讀能護眼不易疲勞，翻閱手感滑順舒適！<br />★ 彩頁採用「120磅進口頂級雪銅紙」於高端四色印刷機印製，色彩絢麗！<br />★ 全書採用「最新一代水晶網點」製版技術，於「高端新型印刷機」印製，微電腦輔助控墨，色彩細緻度令人驚豔，色彩永久絢麗。<br />★ 最新一代PUR裝訂技術，美觀堅固又耐久，盡情翻閱不用怕掉頁。<br />★ 總編輯親自到場監製，耗時費工全程看印，只為給讀者獻上最高品質！<br />★ 用創造藝術品的心，讓每一本書近乎完美！<br /><br /><br />　　這是與「虛假」無緣的世事。<br />　　這是與「真實」無關的命運。<br /><br />　　世界首款完全沉浸式角色扮演遊戲『月星-Online-』一經問世，立即成為了全社會的關註焦點。遊戲內相較於現實144倍的時間與擬真度極高的遊戲體驗，俘獲了許多玩家的心。月星世界將是許多對現實心灰意冷之人重生的舞台。<br /><br />　　作為被校園霸凌數年的受害者，高中女生向瀨白夜最大的願望就是｜｜獲得僅三千份的月星公測參與資格，卻因得知自己落選而陷入絕望。自殺前夕，她卻從意外離世的舊識黑羽諒璃手中，獲得了二手的月星遊戲帳號。<br /><br />　　但她心中百感交集，進入遊戲的自己完全繼承了諒璃的角色數據與外貌。而將帳號轉贈給她的諒璃，即是霸凌白夜最久的罪魁禍首。</p>',10,0,'2026-03-17 18:14:53','2026-03-17 18:14:53','https://www.eslite.com/product/10012012032683099110003'),(80,'變成伯爵家的混混 5','Yu Ryeo Han','9786267744130','深空出版','2026-02-11',420,'輕小說','https://s.eslite.com/b2b/newItem/2026/02/10/8113_102623287_577_mainCoverImage1.jpg','<p>◆ 與《全知讀者視角》並列，韓國網路小說三巨頭之一 <br />◆ 讀者9.9★推薦！韓國知名小說平臺Ridibooks網路小說大賞獲獎作 <br />◆ Kakao Webtoon人氣漫畫同名原作小說 <br />◆ 角色扮演＋經營類＋養成類(?)，異世界奇幻冒險故事華麗降臨！ <br />◆ 韓國大手繪師 달리 跨海合作 <br />◆ 首刷即贈〈天使化崔漢〉炫彩雷射票！ <br /><br />唯有不滅的信念，才能鑄出不破之盾！ <br /><br />藉著訪問帝國之機， <br />凱爾暗中謀劃破壞帝國力量根源「煉金術塔」， <br />並追查神祕組織「黯」與帝國盤根錯節的關係。 <br />然而帝國的監視，讓他們難以行動， <br />所謂禮尚往來，身為壚韵大使的他自然也要好好「回敬」一番。 <br />前教皇隱匿的聖物與祕寶，就交由他來好好處理囉！ <br /><br />金綠秀的介入，徹底打亂了原作的命運軌跡。 <br />帝國與黯組織不再暗中籌謀，而是聯手掀起戰火， <br />壚韵王國的東北邊境燃起戰爭之焰！ <br />即使命運的劇本被徹底改寫，凱爾也早已整裝待發。 <br />這場戰局的勝負與未來——將由他親自決定！</p>',10,0,'2026-03-17 18:15:01','2026-03-17 18:15:01','https://www.eslite.com/product/10012011762683066480009'),(81,'逃避仙尊追殺的那些年','Lori Engel','9786267854136','城邦原創股份有限公司','2026-03-14',399,'輕小說','https://s.eslite.com/b2b/newItem/2026/03/06/15138_103034658_624_mainCoverImage1.jpg','<p>★ 口碑好評不斷！ POPO原創首本古風耽美小說！★\n<br />★ POPO華文創作大賞──耽美百合組入圍作品！★\n<br /> \n<br />\n<br />清冷淡漠仙尊攻 X 遲鈍瀟灑魔頭受\n<br /> \n<br />\n<br />師兄，你離開我的這些年，\n<br />我無一不想念、無一不衝動想將你抓回，\n<br />困在懷裡哪裡也不能去……\n<br />\n<br />☯ 特邀人氣繪師 JN 繪製精美書封\n<br />☯ 特別收錄番外〈第一次成為魔界中人〉\n<br />☯ 全新加筆萬字長篇番外〈道侶得了健忘症〉\n<br />\n<br />∞\n<br />\n<br />沈莫若醒了，正確說來，是「活」過來了。\n<br />\n<br />闔眼前，沈莫若已經成為人人喊殺的大魔頭，\n<br />修真界駭人聽聞的顧家滅門慘案，多年後發現正是他所為。\n<br />唯一的倖存者無非仙尊，同時也是他的師弟顧以明，\n<br />得知真相後心碎欲裂。\n<br />憤怒與被背叛的痛苦，淹沒了他一直以來對沈莫若的情意，\n<br />他決定大義滅親，親手報殺父之仇。\n<br />\n<br />逃避顧以明的追殺十三年，\n<br />沈莫若最終還是被綑於囚神台，受刑三千六百刀， \n<br />孤零零、受盡唾罵與凌遲，痛苦不堪地死去。\n<br />\n<br />睜眼後，十幾年過去，\n<br />他莫名重生成為了另外一個人──沈蘭之，\n<br />身邊還有位想與他日日雙修，甚至自願成為他爐鼎的道侶，\n<br />而這男人長得竟和顧以明有些神似！\n<br />\n<br />面對如此怪異的情況，沈莫若只能走一步算一步，\n<br />暗自調查前世未能及時阻止的某人的詭計，一邊尋找重生的原因。\n<br />豈料陰錯陽差之下，這世的他反倒與顧以明有了更曖昧的牽扯……</p>',9,1,'2026-03-17 18:15:05','2026-04-10 14:41:15','https://www.eslite.com/product/10012013192683102785006'),(82,'同班的資優生是我的契約妹妹。她似乎想盡情撒嬌。 1','冰高悠','9786264451086','台灣角川股份有限公司','2026-02-25',250,'輕小說','https://s.eslite.com/b2b/vendor/mod_vendor177080288614420260211174102/mainCoverImage1_2683088429000.jpg','<html><head></head><body><p>我，鷹戶流希因為和父親關係不好而離家出走， <br>結果被同班同學加古川青緒撿回去。 <br>我和青緒締結了某個「契約」，那就是…… <br>成為她的家人並一起生活！ <br>「哥哥～～現在沒有別人，讓我充電一下！」 <br>青緒在學校是資優生，回到家卻超級依賴我這個「哥哥」！ <br>不僅如此，平時害羞內向，但其實很想照顧人的妹妹絆菜， <br>還有青緒的表姊──在學校很受歡迎的老師優香里， <br>加古川家這三位美少女都開始向我撒嬌…… <br>雖然是奇妙的關係，日常生活卻充滿樂趣，令人興奮不已！ <br>成為「家人」後，戀情開始萌芽。溫馨的同居系戀愛喜劇！ <br><br>©Yuu Hidaka,Tantan 2024╱KADOKAWA CORPORATION</p></body></html>',10,0,'2026-03-17 18:15:09','2026-03-17 18:15:09','https://www.eslite.com/product/10012011762683088429000'),(83,'靠死亡遊戲混飯吃。 7','鵜飼有志','9786264359399','台灣角川股份有限公司','2026-02-05',240,'輕小說','https://s.eslite.com/b2b/vendor/mod_vendor176966486170220260129133404/mainCoverImage1_2683069115007.jpg','<html><head></head><body><p>我，幽鬼，在戰勝幻影後獲得了更高層次的感官， <br>並利用這樣的力量輕鬆通過海戰遊戲、鬼屋遊戲， <br>甚至地雷區遊戲，過著順遂的玩家生活。 <br>可是──大概命中注定一生顛沛，\\ <br>或是有餘力注意外面的世界了──遊戲外狀況頻傳。 <br>一下有殺手少女拜訪，一下公寓鄰居被綁架，有時被捲入不良團體對幹。 <br>我是否能夠安然度過這一切，徹底守住安穩生活呢──？ <br>時至今日我依然靠死亡遊戲混飯吃。 <br><br>©Yushi Ukai 2024 Illustration：Nekometaru / KADOKAWA CORPORATION</p></body></html>',10,0,'2026-03-17 18:15:13','2026-03-17 18:15:13','https://www.eslite.com/product/10012011762683069115007'),(84,'惡魔來了 1: 空白契約書','星子','9786263842793','蓋亞文化有限公司','2026-02-04',320,'輕小說','https://s.eslite.com/b2b/newItem/2026/02/02/8852_000452034_441_mainCoverImage1.jpg','<p>西洋惡魔✕在地風景<br />Netflix影集《乩身》原著作者 星子<br />從東方神明到西洋惡魔，最新奇幻力作！</p><p><br /></p><p><br /></p><p>所羅門王並不是第一個想控制惡魔的人。<br />七十二魔神，不只是傳說。<br />只要能與惡魔簽下契約，即使是人類也能驅策惡魔。<br />問題從來不在於能不能，而在於付不付得起代價。<br /><br />在無盡的時間與殺戮之後，迪奇奇早已忘了自己為何仍然留在地獄。<br />在地獄，他的力量足以跟那七位強大的君王並列，但卻始終獨來獨往，對地盤與權力毫無興趣，也因此有了「地獄第八君王」這個稱號。<br />然而那天，一場學生的通靈遊戲，卻意外讓他重回人間。在那個名為劉心月的少女身上，他感受到一股久違的氣息。某種他以為早已遺忘、卻仍能觸動他的氣息。<br />為了找回那段模糊的記憶，迪奇奇化身轉學生，踏入現代校園，並以一杯手搖飲為代價，與劉心月締結契約。<br />教訓校園惡霸、保護劉家人、順手打擊黑幫；他很清楚這些會引發什麼連鎖反應，只是懶得在意後果。<br />畢竟，在人類世界，召喚惡魔、訂定契約早已不是第一次；只是這一次，有人似乎希望事情走得更遠⋯⋯</p>',10,0,'2026-03-17 18:15:18','2026-03-17 18:15:18','https://www.eslite.com/product/10012046692683084086009'),(85,'鄰居是公會成員 1-2 (特裝版/2冊合售)','HoneyTrap','9780020